	inline unsigned char Processor::CPU_Core::RequireArchRegister(IntRegister register_Keyword, const std::wstring &paramName)
	{
		unsigned short regId = register_Keyword.getArchRegisterID();

		if (regId > ArchRegId::MaxValue)
		{
		throw std::out_of_range("architectural register id is out of range");
		}

		return static_cast<unsigned char>(regId);
	}

	inline std::shared_ptr<ArchRegId> Processor::CPU_Core::RequireArchRegId(IntRegister register_Keyword, const std::wstring &paramName)
	{
		return std::make_shared<ArchRegId>(RequireArchRegister(register_Keyword, paramName));
	}

	inline unsigned long long Processor::CPU_Core::PackIntRegistersAsArchRegs(IntRegister reg1)
	{
		return ArchRegisterTripletEncoding::Pack(RequireArchRegister(reg1, L"reg1"), ArchRegisterTripletEncoding::NoArchReg, ArchRegisterTripletEncoding::NoArchReg);
	}

	inline unsigned long long Processor::CPU_Core::PackIntRegistersAsArchRegs(IntRegister reg1, IntRegister reg2)
	{
		return ArchRegisterTripletEncoding::Pack(RequireArchRegister(reg1, L"reg1"), RequireArchRegister(reg2, L"reg2"), ArchRegisterTripletEncoding::NoArchReg);
	}

	inline unsigned long long Processor::CPU_Core::PackIntRegistersAsArchRegs(IntRegister reg1, IntRegister reg2, IntRegister reg3)
	{
		return ArchRegisterTripletEncoding::Pack(RequireArchRegister(reg1, L"reg1"), RequireArchRegister(reg2, L"reg2"), RequireArchRegister(reg3, L"reg3"));
	}

	inline unsigned long long Processor::CPU_Core::PackArchRegistersAsArchRegs(std::shared_ptr<ArchRegId> reg1)
	{
		return ArchRegisterTripletEncoding::Pack(reg1 ? reg1->ToRawValue() : ArchRegisterTripletEncoding::NoArchReg, ArchRegisterTripletEncoding::NoArchReg, ArchRegisterTripletEncoding::NoArchReg);
	}

	inline unsigned long long Processor::CPU_Core::PackArchRegistersAsArchRegs(std::shared_ptr<ArchRegId> reg1, std::shared_ptr<ArchRegId> reg2)
	{
		return ArchRegisterTripletEncoding::Pack(reg1 ? reg1->ToRawValue() : ArchRegisterTripletEncoding::NoArchReg, reg2 ? reg2->ToRawValue() : ArchRegisterTripletEncoding::NoArchReg, ArchRegisterTripletEncoding::NoArchReg);
	}

	inline unsigned long long Processor::CPU_Core::PackArchRegistersAsArchRegs(std::shared_ptr<ArchRegId> reg1, std::shared_ptr<ArchRegId> reg2, std::shared_ptr<ArchRegId> reg3)
	{
		return ArchRegisterTripletEncoding::Pack(reg1 ? reg1->ToRawValue() : ArchRegisterTripletEncoding::NoArchReg, reg2 ? reg2->ToRawValue() : ArchRegisterTripletEncoding::NoArchReg, reg3 ? reg3->ToRawValue() : ArchRegisterTripletEncoding::NoArchReg);
	}

	inline unsigned long long Processor::CPU_Core::ReadActiveArchValue(std::shared_ptr<ArchRegId> regId)
	{
		return ReadArch(ReadActiveVirtualThreadId(), regId ? regId->ToRawValue() : ArchRegisterTripletEncoding::NoArchReg);
	}

	inline void Processor::CPU_Core::WriteActiveArchValue(std::shared_ptr<ArchRegId> regId, unsigned long long value)
	{
		getRetireCoordinator()->Retire(RetireRecord::RegisterWrite(ReadActiveVirtualThreadId(), (regId ? regId->ToRawValue() : ArchRegisterTripletEncoding::NoArchReg), value));
	}

	unsigned long long Processor::CPU_Core::ReadPodCSR(int csrAddr)
	{
		switch (csrAddr)
		{
			case CSR_POD_ID:
				return getRuntime()->getArchitectural()->PodId;
			case CSR_POD_AFFINITY_MASK:
				return getRuntime()->getArchitectural()->PodAffinityMask;
			case CSR_MEM_DOMAIN_CERT:
				return getRuntime()->getArchitectural()->MemoryDomainCertificate;
			case CSR_NOC_ROUTE_CFG:
				return getRuntime()->getArchitectural()->NocRouteConfiguration;
			default:
				throw CsrUnknownAddressException(static_cast<unsigned short>(csrAddr));
		}
	}

	void Processor::CPU_Core::PublishFirmwarePodId(unsigned long long value)
	{
		BeginLiveSecureSourceMutation();
		auto finishMutation = std::shared_ptr<void>(this, [this](void*) { EndLiveSecureSourceMutation(); });
		try
		{
			// Physical topology publication starts a new source lifetime,
			// including equal bits. Cancel original pending attempts and
			// replay before the first store; guest WritePodCSR never calls here.
			FlushPipelineUnderSecureGate(Core::AssistInvalidationReason::OwnerInvalidation);
			getRuntime()->getArchitectural()->PodId = value;
		}
// C# TO C++ CONVERTER TASK: There is no C++ equivalent to the exception 'finally' clause:
		catch (...) { throw; }
	}

	void Processor::CPU_Core::WritePodCSR(int csrAddr, unsigned long long value)
	{
		switch (csrAddr)
		{
			case CSR_POD_ID:
				// Read-only at runtime — only firmware/reset can set this
				break;
			case CSR_POD_AFFINITY_MASK:
				// Every original write publishes, including equal bits.
				// Reserve before the store; the value facade delegates here.
				BeginLiveSecureSourceMutation();
			{
				auto finishMutation = std::shared_ptr<void>(this, [this](void*) { EndLiveSecureSourceMutation(); });
				try
				{
					getRuntime()->getArchitectural()->PodAffinityMask = value;
				}
// C# TO C++ CONVERTER TASK: There is no C++ equivalent to the exception 'finally' clause:
				catch (...) { throw; }
				}
				break;
			case CSR_MEM_DOMAIN_CERT:
				if (getCsrMemDomainCert() == value)
				{
					break;
				}
				BeginLiveSecureSourceMutation();
				{
				auto finishMutation = std::shared_ptr<void>(this, [this](void*) { EndLiveSecureSourceMutation(); });
				try
				{
					InvalidateAssistRuntime(Core::AssistInvalidationReason::OwnerInvalidation);
					// Original changed-certificate publication. The
					// public facade delegates here; do not recurse into
					// its setter or publish before this owner reserves.
					getRuntime()->getArchitectural()->MemoryDomainCertificate = value;
				}
// C# TO C++ CONVERTER TASK: There is no C++ equivalent to the exception 'finally' clause:
				catch (...) { throw; }
				}
				break;
			case CSR_NOC_ROUTE_CFG:
				// Every original write publishes, including equal bits.
				// Reserve before the store; the value facade delegates here.
				BeginLiveSecureSourceMutation();
				{
				auto finishMutation = std::shared_ptr<void>(this, [this](void*) { EndLiveSecureSourceMutation(); });
				try
				{
					getRuntime()->getArchitectural()->NocRouteConfiguration = value;
				}
// C# TO C++ CONVERTER TASK: There is no C++ equivalent to the exception 'finally' clause:
				catch (...) { throw; }
				}
				break;
		}
	}

	inline bool Processor::CPU_Core::IsEmulationExecutionMode()
	{
		return getRuntime()->getBinding()->ExecutionMode == ProcessorMode::Emulation;
	}

	inline bool Processor::CPU_Core::IsCompilerExecutionMode()
	{
		return getRuntime()->getBinding()->ExecutionMode == ProcessorMode::Compiler;
	}

	inline void Processor::CPU_Core::SynchronizeExecutionMode()
	{
		auto platformContext = getRuntime()->getBinding()->PlatformContext;
		if (platformContext != nullptr && platformContext->IsConfigured)
		{
			getRuntime()->getBinding()->ExecutionMode = platformContext->ResolveExecutionMode();
			return;
		}

		getRuntime()->getBinding()->ExecutionMode = Processor::CurrentProcessorMode;
	}

