		getRuntime()->getArchitectural()->PredicateRegister8 = 0xFFFFFFFFFFFFFFFFULL;
		getRuntime()->getArchitectural()->PredicateRegister9 = 0xFFFFFFFFFFFFFFFFULL;
		getRuntime()->getArchitectural()->PredicateRegister10 = 0xFFFFFFFFFFFFFFFFULL;
		getRuntime()->getArchitectural()->PredicateRegister11 = 0xFFFFFFFFFFFFFFFFULL;
		getRuntime()->getArchitectural()->PredicateRegister12 = 0xFFFFFFFFFFFFFFFFULL;
		getRuntime()->getArchitectural()->PredicateRegister13 = 0xFFFFFFFFFFFFFFFFULL;
		getRuntime()->getArchitectural()->PredicateRegister14 = 0xFFFFFFFFFFFFFFFFULL;
		getRuntime()->getArchitectural()->PredicateRegister15 = 0xFFFFFFFFFFFFFFFFULL;

