	void Processor::CPU_Core::FPExceptionContext::Clear()
	{
		FCSR = 0;
		RoundingMode = 0;
		ExceptionFlags = 0;
		InvalidOp = false;
		DivByZero = false;
		Overflow = false;
		Underflow = false;
		Inexact = false;
	}

	void Processor::CPU_Core::FPExceptionContext::MergeFrom(FPExceptionContext other)
	{
		InvalidOp |= other.InvalidOp;
		DivByZero |= other.DivByZero;
		Overflow |= other.Overflow;
		Underflow |= other.Underflow;
		Inexact |= other.Inexact;

		// Update ExceptionFlags byte
		ExceptionFlags = 0;
		if (InvalidOp)
		{
			ExceptionFlags |= 0x01;
		}
		if (DivByZero)
		{
			ExceptionFlags |= 0x02;
		}
		if (Overflow)
		{
			ExceptionFlags |= 0x04;
		}
		if (Underflow)
		{
			ExceptionFlags |= 0x08;
		}
		if (Inexact)
		{
			ExceptionFlags |= 0x10;
		}
	}

	bool Processor::CPU_Core::FPExceptionContext::HasException()
	{
		return InvalidOp || DivByZero || Overflow || Underflow || Inexact;
	}

