	void Processor::CPU_Core::PublishActiveVirtualThreadId(int vtId)
	{
		int resolved = ResolveLiveStateVtIdOrThrow(vtId, L"ActiveVirtualThreadId");
		BeginLiveSecureSourceMutation();
		auto finishMutation = std::shared_ptr<void>(this, [this](void*) { EndLiveSecureSourceMutation(); });
		// Discard the previous selection's fetched/admitted work through its existing owners.
		FlushPipelineUnderSecureGate(Core::AssistInvalidationReason::PipelineFlush);
		getRuntime()->getScheduling()->ActiveVirtualThreadId = resolved;
	}

