	{
		return ReadVirtualThreadPipelineState(ReadActiveVirtualThreadId());
	}

	PipelineState Processor::CPU_Core::ReadVirtualThreadPipelineState(int vtId)
	{
		EnsureVirtualThreadPipelineStatesInitialized();
		vtId = ResolveLiveStateVtIdOrThrow(vtId, L"ReadVirtualThreadPipelineState");
		return VirtualThreadPipelineStates[vtId];
	}

	std::pair<int, unsigned long long> Processor::CPU_Core::GetCallStackSnapshot() const
	{
		const auto &stack = Call_Callback_Addresses;
		return {static_cast<int>(stack.size()), stack.empty() ? 0ULL : stack.back()};
	}

	std::pair<int, unsigned long long> Processor::CPU_Core::GetInterruptStackSnapshot() const
	{
		const auto &stack = Interrupt_Callback_Addresses;
		return {static_cast<int>(stack.size()), stack.empty() ? 0ULL : stack.back()};
	}

	std::array<int, 4> Processor::CPU_Core::GetCacheEntryCountsSnapshot() const
	{
		const auto cache = getRuntime()->getCache();
		return {static_cast<int>(cache->L1VliwBundles.size()), static_cast<int>(cache->L1Data.size()), static_cast<int>(cache->L2VliwBundles.size()), static_cast<int>(cache->L2Data.size())};
	}

	bool Processor::CPU_Core::ReadVirtualThreadStalled(int vtId) const
	{
		if (vtId < 0 || vtId >= SmtWays)
		{
			throw ArgumentOutOfRangeException(L"vtId", L"Virtual thread ID is outside the SMT range");
		}
		const auto scheduling = getRuntime()->getScheduling();
		return scheduling != nullptr && static_cast<std::size_t>(vtId) < scheduling->VirtualThreadStalled.size() && scheduling->VirtualThreadStalled[vtId];
	}

	Processor::CPU_Core::FPExceptionContext Processor::CPU_Core::ReadThreadFpContext(int vtId) const
	{
		if (vtId < 0 || vtId >= SmtWays)
		{
			throw ArgumentOutOfRangeException(L"vtId", L"Virtual thread ID is outside the SMT range");
		}
		const auto architectural = getRuntime()->getArchitectural();
		return architectural != nullptr && static_cast<std::size_t>(vtId) < architectural->FloatingPointContexts.size()
			? architectural->FloatingPointContexts[vtId]
			: FPExceptionContext{};
	}

