	void Processor::CPU_Core::ApplyRetiredVmxPipelineStateOwnership(int vtId, Core::VmxRetireEffect const effect, Core::VmxRetireOutcome const outcome)
	{
		if (!effect.isValid() || effect.isFaulted())
		{
			return;
		}

		int normalizedVtId = ResolveLiveStateVtIdOrThrow(vtId, L"ApplyRetiredVmxPipelineStateOwnership");

		switch (effect.getOperation())
		{
			case Core::VmxOperationKind::VmLaunch:
				ApplyVirtualThreadPipelineTransition(normalizedVtId, PipelineTransitionTrigger::VmLaunch);
				ApplyVirtualThreadPipelineTransition(normalizedVtId, outcome.Faulted ? PipelineTransitionTrigger::EntryFail : PipelineTransitionTrigger::EntryOk);
				break;

			case Core::VmxOperationKind::VmResume:
				ApplyVirtualThreadPipelineTransition(normalizedVtId, PipelineTransitionTrigger::VmResume);
				ApplyVirtualThreadPipelineTransition(normalizedVtId, outcome.Faulted ? PipelineTransitionTrigger::EntryFail : PipelineTransitionTrigger::EntryOk);
				break;

			case Core::VmxOperationKind::VmxOff:
				if (!effect.getExitGuestContextOnRetire())
				{
					return;
				}

				ApplyVirtualThreadPipelineTransition(normalizedVtId, PipelineTransitionTrigger::VmxOff);
				ApplyVirtualThreadPipelineTransition(normalizedVtId, PipelineTransitionTrigger::ExitComplete);
				break;
		}
	}

