	inline void Processor::CPU_Core::ExecuteCSRRead(IntRegister destReg, unsigned short csrAddr)
	{
		if (ShouldRejectRetainedDirectHelperSurface())
		{
			throw CreateUnsupportedDirectCsrHelperSurfaceException(L"ExecuteCSRRead", csrAddr);
		}

		unsigned long long temp_var12;
		switch (csrAddr)
		{
			// Vector Configuration (0x000–0x00F)
			case 0x000:
				temp_var12 = getVectorConfig()->getVL();
				break;
			case 0x001:
				temp_var12 = getVectorConfig()->getVTYPE();
				break;
			case 0x002:
				temp_var12 = getRuntime()->getArchitectural()->VectorConfig.TailAgnostic;
				break;
			case 0x003:
				temp_var12 = getRuntime()->getArchitectural()->VectorConfig.MaskAgnostic;
				break;
			case 0x004:
				temp_var12 = RVV_Config::VLMAX;
				break;

			// Floating-Point Control (0x010–0x01F)
			case 0x010:
				temp_var12 = getExceptionStatus()->getRoundingMode();
				break;
			case 0x011:
				temp_var12 = getExceptionStatus()->getExceptionMode();
				break;

			// Exception Counters (0x020–0x02F)
			case 0x020:
				temp_var12 = getExceptionStatus()->getOverflowCount();
				break;
			case 0x021:
				temp_var12 = getExceptionStatus()->getUnderflowCount();
				break;
			case 0x022:
				temp_var12 = getExceptionStatus()->getDivByZeroCount();
				break;
			case 0x023:
				temp_var12 = getExceptionStatus()->getInvalidOpCount();
				break;
			case 0x024:
				temp_var12 = getExceptionStatus()->getInexactCount();
				break;
			case 0x025:
				temp_var12 = getExceptionStatus()->TotalExceptions();
				break;
			case 0x026:
				temp_var12 = getExceptionStatus()->HasExceptions() ? 1ULL : 0ULL;
				break;

			// Vector Unit Status (0x030–0x03F)
			case 0x030:
				temp_var12 = getExceptionStatus()->getVectorDirty();
				break;
			case 0x031:
				temp_var12 = getExceptionStatus()->getVectorEnabled();
				break;

			// Vector Exception Control (0x900–0x9FF)
			case 0x900: // VEXCPMASK
				temp_var12 = getExceptionStatus()->GetMask();
				break;
			case 0x901: // VEXCPPRI
				temp_var12 = ReadPackedPriorities();
				break;

			// FSP Control Registers (0xA00–0xA0F)
			case 0xA00: // VLIW_STEAL_ENABLE
				temp_var12 = getVectorConfig()->getFSPEnabled();
				break;
			case 0xA01: // VLIW_STEAL_MASK
				temp_var12 = getVectorConfig()->getFSPStealMask();
				break;
			case 0xA02: // VLIW_STEAL_POLICY
				temp_var12 = getVectorConfig()->getFSPPolicy();
				break;

			// FSP Statistics (0xA10–0xA1F) - read-only
			case 0xA10: // FSP_STATS_INJECTIONS
				temp_var12 = getVectorConfig()->getFSPInjectionCount();
				break;
			case 0xA11: // FSP_STATS_REJECTIONS
				temp_var12 = getVectorConfig()->getFSPRejectionCount();
				break;

			default:
				temp_var12 = 0;
				break;
		}
		unsigned long long value = temp_var12;

		WriteVectorScalarRegisterValue(destReg, L"destReg", value);
	}

	inline unsigned long long Processor::CPU_Core::ReadPackedPriorities()
	{
		unsigned long long packed = 0;
		for (int i = 0; i < 5; i++)
		{
			unsigned char pri = getExceptionStatus()->GetPriority(i);
			packed |= static_cast<unsigned long long>(pri & 0x7) << (i * 3);
		}
		return packed;
	}

	inline void Processor::CPU_Core::ExecuteCSRWrite(IntRegister srcReg, unsigned short csrAddr)
	{
		if (ShouldRejectRetainedDirectHelperSurface())
		{
			throw CreateUnsupportedDirectCsrHelperSurfaceException(L"ExecuteCSRWrite", csrAddr);
		}

		unsigned long long sourceValue = ReadVectorScalarRegisterValue(srcReg, L"srcReg");
		unsigned char val = static_cast<unsigned char>(sourceValue);
		switch (csrAddr)
		{
			// Vector Configuration (VL is read-only — use VSETVL)
			case 0x001:
				getVectorConfig()->setVTYPE(sourceValue);
				break;
			case 0x002:
				getVectorConfig()->setTailAgnostic(val);
				break;
			case 0x003:
				getVectorConfig()->setMaskAgnostic(val);
				break;

			// Floating-Point Control
			case 0x010:
				getExceptionStatus()->SetRoundingMode(val);
				break;
			case 0x011:
				getExceptionStatus()->SetExceptionMode(val);
				break;

			// Vector Unit Status
			case 0x030:
				getExceptionStatus()->setVectorDirty(val);
				break;
			case 0x031:
				getExceptionStatus()->setVectorEnabled(val);
				break;

			// Vector Exception Control
			case 0x900:
				Exec_VSETVEXCPMASK(sourceValue);
				break; // VEXCPMASK
			case 0x901:
				Exec_VSETVEXCPPRI(sourceValue);
				break; // VEXCPPRI

			// FSP Control Registers
			case 0xA00:
				getVectorConfig()->setFSPEnabled(static_cast<unsigned char>(sourceValue & 0x1));
				break; // VLIW_STEAL_ENABLE
			case 0xA01:
				getVectorConfig()->setFSPStealMask(static_cast<unsigned char>(sourceValue & 0xFF));
				break; // VLIW_STEAL_MASK
			case 0xA02:
				getVectorConfig()->setFSPPolicy(static_cast<unsigned char>(sourceValue & 0x3));
				break; // VLIW_STEAL_POLICY (0-2 valid)

			// FSP Statistics (0xA10–0xA1F) are read-only, writes ignored
		}
	}

	inline void Processor::CPU_Core::Exec_VSETVEXCPMASK(unsigned long long rs1Value)
	{
		unsigned char mask = static_cast<unsigned char>(rs1Value & 0x1F);
		auto status = getExceptionStatus();
		status->SetMask(mask);
	}

	inline void Processor::CPU_Core::Exec_VSETVEXCPPRI(unsigned long long rs1Value)
	{
		BeginLiveSecureSourceMutation(nullptr, CoreSourceMutationKind::Lifecycle, CoreSourceReservationMode::NonblockingContext);
		auto finishMutation = std::shared_ptr<void>(this, [this](void*) { EndLiveSecureSourceMutation(); });
		FlushPipelineUnderSecureGate(Core::AssistInvalidationReason::OwnerInvalidation);
		WritePackedExceptionPriorities(rs1Value);
	}

	void Processor::CPU_Core::WriteCanonicalVectorPodPlaneCsr(int csrAddr, unsigned long long value)
	{
		if (csrAddr >= Processor::CPU_Core::CSR_POD_ID && csrAddr <= Processor::CPU_Core::CSR_NOC_ROUTE_CFG)
		{
			WritePodCSR(csrAddr, value);
			return;
		}

// C# TO C++ CONVERTER NOTE: The following 'using' block is replaced by its C++ equivalent:
// ORIGINAL LINE: using var access = ReserveCanonicalCoreWrite(null);
		{
			auto access = ReserveCanonicalCoreWrite(nullptr);
			switch (csrAddr)
			{
				case CsrAddresses::VexcpMask:
					getRuntime()->getArchitectural()->VectorExceptionStatus.SetMask(static_cast<unsigned char>(value));
					return;
				case CsrAddresses::VexcpPri:
					WritePackedExceptionPriorities(value);
					return;
				case static_cast<int>(Processor::CPU_Core::VectorCSR::VLIW_STEAL_ENABLE):
					getRuntime()->getArchitectural()->VectorConfig.FSP_Enabled = static_cast<unsigned char>(value & 1);
					return;
				case static_cast<int>(Processor::CPU_Core::VectorCSR::VLIW_STEAL_MASK):
					getRuntime()->getArchitectural()->VectorConfig.FSP_StealMask = static_cast<unsigned char>(value & 0xFF);
					return;
				case static_cast<int>(Processor::CPU_Core::VectorCSR::VLIW_STEAL_POLICY):
					getRuntime()->getArchitectural()->VectorConfig.FSP_Policy = static_cast<unsigned char>(value & 0xFF);
					return;
				default:
					throw InvalidOperationException(std::format(L"CSR address 0x{0:0>3X} is not writable via the vector/pod CSR plane.", static_cast<unsigned short>(csrAddr)));
			}
		}
	}

	void Processor::CPU_Core::WritePackedExceptionPriorities(unsigned long long rs1Value)
	{
// C# TO C++ CONVERTER TASK: 'ref locals' are not converted by C# to C++ Converter:
// ORIGINAL LINE: ref VectorExceptionStatus status = ref Runtime.Architectural.VectorExceptionStatus;
		VectorExceptionStatus &status = getRuntime()->getArchitectural()->VectorExceptionStatus;
		for (int i = 0; i < 5; i++)
		{
			unsigned char pri = static_cast<unsigned char>((rs1Value >> (i * 3)) & 0x7);
			status.SetPriority(i, pri);
		}
	}

