	bool Processor::CPU_Core::HasExactBoundMainMemoryRange(unsigned long long address, int size)
	{
		if (size <= 0)
		{
			return false;
		}

		unsigned long long memoryLength = GetBoundMainMemoryLength();
		unsigned long long requestSize = static_cast<unsigned long long>(size);
		return requestSize <= memoryLength && address <= memoryLength - requestSize;
	}

	void Processor::CPU_Core::ThrowIfBoundMainMemoryRangeUnavailable(unsigned long long address, int size, const std::wstring &executionSurface)
	{
		if (HasExactBoundMainMemoryRange(address, size))
		{
			return;
		}

		throw InvalidOperationException(std::format(L"{0} reached synchronous MainMemory fallback at 0x{1:0X} for {2} byte(s) without a fully materializable in-range surface. ", executionSurface, address, size) + L"The authoritative fallback must fail closed instead of decoding partial bytes, reusing zeros, or reporting a boundary-crossing memory success.");
	}

	inline std::vector<unsigned char> Processor::CPU_Core::ReadBoundMainMemory(unsigned long long address, std::vector<unsigned char> &buffer, int accessSize, const std::wstring &operation)
	{
		if (buffer.empty()) return buffer;

		if (buffer.size() < accessSize)
		{
// C# TO C++ CONVERTER TASK: This exception's constructor requires only one argument:
// ORIGINAL LINE: throw new ArgumentException(string.Format("Bound main-memory read buffer was smaller than the requested access size {0}.", accessSize), nameof(buffer));
			throw std::invalid_argument(std::format("Bound main-memory read buffer was smaller than the requested access size {}.", accessSize));
		}

		if (!GetBoundMainMemory()->TryReadPhysicalRange(address, std::span<unsigned char>(buffer.data(), static_cast<std::size_t>(accessSize))))
		{
			throw IOException(std::format(L"{0} failed to read {1} byte(s) from bound main memory at physical address 0x{2:0X}.", operation, accessSize, address));
		}

		return buffer;
	}

	void Processor::CPU_Core::ReadBoundMainMemoryExact(unsigned long long address, std::vector<unsigned char> &buffer, const std::wstring &executionSurface)
	{
		if (buffer.empty()) return;
		ThrowIfBoundMainMemoryRangeUnavailable(address, buffer.size(), executionSurface);
		ReadBoundMainMemory(address, buffer, buffer.size(), executionSurface);
	}

	inline void Processor::CPU_Core::WriteBoundMainMemory(unsigned long long address, std::vector<unsigned char> &buffer, const std::wstring &operation)
	{
		if (buffer.empty()) return;

		if (!GetBoundMainMemory()->TryWritePhysicalRange(address, buffer))
		{
			throw IOException(std::format(L"{0} failed to write {1} byte(s) to bound main memory at physical address 0x{2:0X}.", operation, buffer.size(), address));
		}

	}

	void Processor::CPU_Core::WriteBoundMainMemoryExact(unsigned long long address, std::vector<unsigned char> &buffer, const std::wstring &executionSurface)
	{
		if (buffer.empty()) return;
		ThrowIfBoundMainMemoryRangeUnavailable(address, buffer.size(), executionSurface);
		WriteBoundMainMemory(address, buffer, executionSurface);
	}

