	inline bool Processor::CPU_Core::TryPrefetchAssistDataLine(unsigned long long memoryAddress, unsigned long long domainTag, Core::AssistCarrierKind carrierKind, Core::AssistCacheRejectKind &rejectKind)
	{
		EnsureAssistDataCacheAllocated();
		int ignoredSlotIndex = -1;

		if (TryFindL1DataLineIndex(memoryAddress, domainTag, ignoredSlotIndex))
		{
			rejectKind = Core::AssistCacheRejectKind::None;
			return true;
		}

		Core::AssistCachePartitionPolicy policy = Core::AssistCachePartitionPolicy::getDefault();
		int totalAssistResidentLines = CountAssistResidentLines();
		int carrierAssistResidentLines = CountAssistResidentLines(carrierKind);
		int slotIndex = FindEmptyL1DataSlot();

		if (carrierAssistResidentLines >= policy.ResolveCarrierLineBudget(carrierKind))
		{
			slotIndex = FindAssistVictimSlot(carrierKind, false);
			if (slotIndex < 0)
			{
				rejectKind = Core::AssistCacheRejectKind::CarrierLineBudget;
				return false;
			}
		}
		else if (totalAssistResidentLines >= policy.getTotalLineBudget())
		{
			slotIndex = FindAssistVictimSlot(carrierKind, true);
			if (slotIndex < 0)
			{
				rejectKind = Core::AssistCacheRejectKind::TotalLineBudget;
				return false;
			}
		}
		else if (slotIndex < 0)
		{
			slotIndex = FindAssistVictimSlot(carrierKind, true);
			if (slotIndex < 0)
			{
				rejectKind = Core::AssistCacheRejectKind::NoAssistVictim;
				return false;
			}
		}

		Cache_Data_Object prefetchedLine = GetDataByPointer(memoryAddress, domainTag);
		prefetchedLine.AssistResident = true;
		prefetchedLine.AssistCarrierKind = carrierKind;
		(*L1_Data)[slotIndex] = prefetchedLine;
		rejectKind = Core::AssistCacheRejectKind::None;
		return true;
	}

	inline void Processor::CPU_Core::EnsureAssistDataCacheAllocated()
	{
		if (L1_Data->empty())
		{
			L1_Data->resize(2048);
		}

		if (L1_VLIWBundles->empty())
		{
			L1_VLIWBundles->resize(256);
		}
	}

	bool Processor::CPU_Core::TryFindL1DataLineIndex(unsigned long long memoryAddress, unsigned long long domainTag, int &slotIndex)
	{
		EnsureAssistDataCacheAllocated();
		for (int index = 0; index < L1_Data->size(); index++)
		{
			if ((*L1_Data)[index].DataCache_MemoryAddress != memoryAddress)
			{
				continue;
			}

			if (domainTag != 0 && (*L1_Data)[index].DomainTag != 0 && (*L1_Data)[index].DomainTag != domainTag)
			{
				continue;
			}

			slotIndex = index;
			return true;
		}

		slotIndex = -1;
		return false;
	}

	int Processor::CPU_Core::FindEmptyL1DataSlot()
	{
		EnsureAssistDataCacheAllocated();
		for (int index = 0; index < L1_Data->size(); index++)
		{
			if ((*L1_Data)[index].DataCache_MemoryAddress == 0 && (*L1_Data)[index].DataCache_StoredValue.empty())
			{
				return index;
			}
		}

		return -1;
	}

	int Processor::CPU_Core::CountAssistResidentLines()
	{
		EnsureAssistDataCacheAllocated();
		int count = 0;
		for (int index = 0; index < L1_Data->size(); index++)
		{
			if ((*L1_Data)[index].AssistResident && (*L1_Data)[index].DataCache_MemoryAddress != 0)
			{
				count++;
			}
		}

		return count;
	}

	int Processor::CPU_Core::CountAssistResidentLines(Core::AssistCarrierKind carrierKind)
	{
		EnsureAssistDataCacheAllocated();
		int count = 0;
		for (int index = 0; index < L1_Data->size(); index++)
		{
			if ((*L1_Data)[index].AssistResident && (*L1_Data)[index].AssistCarrierKind == carrierKind && (*L1_Data)[index].DataCache_MemoryAddress != 0)
			{
				count++;
			}
		}

		return count;
	}

	int Processor::CPU_Core::FindAssistVictimSlot(Core::AssistCarrierKind preferredCarrierKind, bool allowCrossCarrierVictim)
	{
		int preferredVictim = FindAssistVictimSlotCore(preferredCarrierKind);
		if (preferredVictim >= 0 || !allowCrossCarrierVictim)
		{
			return preferredVictim;
		}

		return FindAssistVictimSlotCore(std::nullopt);
	}

	int Processor::CPU_Core::FindAssistVictimSlotCore(std::optional<Core::AssistCarrierKind> carrierKind)
	{
		EnsureAssistDataCacheAllocated();

		int selectedIndex = -1;
		unsigned long long selectedQueryCount = std::numeric_limits<unsigned long long>::max();

		for (int index = 0; index < L1_Data->size(); index++)
		{
			Cache_Data_Object line = (*L1_Data)[index];
			if (!line.AssistResident || line.DataCache_MemoryAddress == 0)
			{
				continue;
			}

			if (carrierKind && line.AssistCarrierKind != carrierKind.value())
			{
				continue;
			}

			if (selectedIndex < 0 || line.DataCache_L1QueryCounter < selectedQueryCount)
			{
				selectedIndex = index;
				selectedQueryCount = line.DataCache_L1QueryCounter;
			}
		}

		return selectedIndex;
	}

	void Processor::CPU_Core::PrefetchRegisterData(unsigned long long MemoryAddress, unsigned long long domainTag)
	{
		for (int int_CycleCount = 0; int_CycleCount != L1_Data->size(); int_CycleCount++)
		{
			if ((*L1_Data)[int_CycleCount].DataCache_MemoryAddress == MemoryAddress)
			{
				// Phase §2: Domain isolation — treat cross-domain hit as miss
				if (domainTag != 0 && (*L1_Data)[int_CycleCount].DomainTag != 0 && (*L1_Data)[int_CycleCount].DomainTag != domainTag)
				{
					continue;
				}

				(*L1_Data)[int_CycleCount].AssistResident = false;
				return;
			}
		}

		Current_DataObject_Position++;

		(*L1_Data)[Current_DataObject_Position] = GetDataByPointer(MemoryAddress, domainTag);
	}

	void Processor::CPU_Core::PrefetchVLIWBundle(unsigned long long MemoryAddress)
	{
		// Advisory prefetch must neither materialize unowned code nor
		// turn a valid final image bundle into an execution fault.
		if (!GetBoundMainMemory()->IsInstructionFetchTranslationAllowed(MemoryAddress, MemoryAddress, 256))
		{
			return;
		}
		_hasMaterializedVliwFetchState = true;
		Current_VLIWBundle_Position++;

		(*L1_VLIWBundles)[Current_VLIWBundle_Position] = GetVLIWBundleByPointer(MemoryAddress);
	}

	Processor::CPU_Core::Cache_Data_Object Processor::CPU_Core::GetDataByMemPtr(unsigned long long MemoryAddress, unsigned long long domainTag)
	{
		for (int int_CycleCount = 0; int_CycleCount != L1_Data->size(); int_CycleCount++)
		{
			if ((*L1_Data)[int_CycleCount].DataCache_MemoryAddress == MemoryAddress)
			{
				// Phase §2: Domain isolation — treat cross-domain hit as miss
				if (domainTag != 0 && (*L1_Data)[int_CycleCount].DomainTag != 0 && (*L1_Data)[int_CycleCount].DomainTag != domainTag)
				{
					continue;
				}

				(*L1_Data)[int_CycleCount].AssistResident = false;
				return (*L1_Data)[int_CycleCount];
			}
		}

		Current_DataObject_Position++;

		(*L1_Data)[Current_DataObject_Position] = GetDataByPointer(MemoryAddress, domainTag);

		return (*L1_Data)[Current_DataObject_Position];
	}

	Processor::CPU_Core::Cache_VLIWBundle_Object Processor::CPU_Core::GetVLIWBundleByPointer(unsigned long long MemoryAddress)
	{
		if (!GetBoundMainMemory()->IsInstructionFetchTranslationAllowed(MemoryAddress, MemoryAddress, 256))
		{
			throw InvalidOperationException(L"Physical bundle fetch lost its original executable-memory owner.");
		}
		_hasMaterializedVliwFetchState = true;

		if (L1_VLIWBundles->empty() || L1_Data->empty())
		{
			L1_VLIWBundles->resize(256);

			L1_Data->resize(2048); // 2048*32bytes=65536 data items. Only for MemPtr (Memory Array)
		}

		{
			for (int int_CycleCount = 0; int_CycleCount != L1_VLIWBundles->size(); int_CycleCount++)
			{
				if ((*L1_VLIWBundles)[int_CycleCount].VLIWCache_MemoryAddress == MemoryAddress && MemoryAddress > 0)
				{
					RequireCurrentVliwPayload((*L1_VLIWBundles)[int_CycleCount]);
					(*L1_VLIWBundles)[int_CycleCount].VLIWCache_L1QueryCounter++;

					return (*L1_VLIWBundles)[int_CycleCount];
				}
			}

			Current_VLIWBundle_Position++;

			ulong_MinL1Query = std::numeric_limits<unsigned long long>::max();

			for (int int_CycleCount = 0; int_CycleCount != L1_VLIWBundles->size(); int_CycleCount++)
			{
				if ((*L1_VLIWBundles)[int_CycleCount].VLIWCache_L1QueryCounter < ulong_MinL1Query)
				{
					ulong_MinL1Query = (*L1_VLIWBundles)[int_CycleCount].VLIWCache_L1QueryCounter;

					int_CycleCount = 0;

					Current_VLIWBundle_Position = static_cast<unsigned long long>(int_CycleCount);

					continue;
				}
			}

			(*L1_VLIWBundles)[Current_VLIWBundle_Position].VLIWCache_L1QueryCounter++;

			(*L1_VLIWBundles)[Current_VLIWBundle_Position].VLIWCache_MemoryAddress = MemoryAddress;

			Cache_VLIWBundle_Object fetchedBundle = GetL2_VLIWBundleByPointer((*L1_VLIWBundles)[Current_VLIWBundle_Position].VLIWCache_MemoryAddress);
			(*L1_VLIWBundles)[Current_VLIWBundle_Position].VLIWCache_VLIWBundle = fetchedBundle.VLIWCache_VLIWBundle;
			(*L1_VLIWBundles)[Current_VLIWBundle_Position].VLIWCache_BundleAnnotations = fetchedBundle.VLIWCache_BundleAnnotations;
			(*L1_VLIWBundles)[Current_VLIWBundle_Position].VLIWCache_HasAnnotationCarrier = fetchedBundle.VLIWCache_HasAnnotationCarrier;
			LoadTo_Cache_L2((*L1_VLIWBundles)[Current_VLIWBundle_Position]);

			RequireCurrentVliwPayload((*L1_VLIWBundles)[Current_VLIWBundle_Position]);
			return (*L1_VLIWBundles)[Current_VLIWBundle_Position];
		}
	}

	void Processor::CPU_Core::InvalidateVliwFetchState(unsigned long long memoryAddress)
	{
		AdvanceReplayCodeGenerationEpoch();
		if (!_hasMaterializedVliwFetchState)
		{
			_loopBuffer.Invalidate(Core::ReplayPhaseInvalidationReason::CertificateMutation);
			PublishReplayPhaseContextIfNeeded(_fspScheduler, _loopBuffer.getCurrentReplayPhase());
			return;
		}

		InvalidateVliwBundleCacheLine(L1_VLIWBundles, memoryAddress);
		InvalidateVliwBundleCacheLine(L2_VLIWBundles, memoryAddress);
		_loopBuffer.Invalidate(Core::ReplayPhaseInvalidationReason::CertificateMutation);
		PublishReplayPhaseContextIfNeeded(_fspScheduler, _loopBuffer.getCurrentReplayPhase());
	}

	void Processor::CPU_Core::InvalidateAllVliwFetchState(Core::ReplayPhaseInvalidationReason invalidationReason)
	{
		InvalidateAllVliwFetchState(invalidationReason, true);
	}

	void Processor::CPU_Core::InvalidateAllVliwFetchState(Core::ReplayPhaseInvalidationReason invalidationReason, bool advanceCodeGenerationEpoch)
	{
		if (advanceCodeGenerationEpoch)
		{
			AdvanceReplayCodeGenerationEpoch();
		}

		if (_hasMaterializedVliwFetchState)
		{
			ClearVliwBundleCache(L1_VLIWBundles);
			ClearVliwBundleCache(L2_VLIWBundles);
			_hasMaterializedVliwFetchState = false;
		}

		_loopBuffer.Invalidate(invalidationReason);
		PublishReplayPhaseContextIfNeeded(_fspScheduler, _loopBuffer.getCurrentReplayPhase());
	}

