	{
		_hasMaterializedVliwFetchState = true;
	}
#endif

	void Processor::CPU_Core::InvalidateVliwBundleCacheLine(std::shared_ptr<std::vector<Cache_VLIWBundle_Object>> cache, unsigned long long memoryAddress)
	{
		if (cache == nullptr)
		{
			return;
		}

		for (int index = 0; index < cache->size(); index++)
		{
			if ((*cache)[index].VLIWCache_MemoryAddress == memoryAddress)
			{
				(*cache)[index] = Cache_VLIWBundle_Object{};
			}
		}
	}

	void Processor::CPU_Core::ClearVliwBundleCache(std::shared_ptr<std::vector<Cache_VLIWBundle_Object>> cache)
	{
		if (cache == nullptr)
		{
			return;
		}

		std::fill(cache->begin(), cache->end(), Cache_VLIWBundle_Object{});
	}

	std::pair<std::shared_ptr<std::vector<Processor::CPU_Core::Cache_Data_Object>>, std::shared_ptr<std::vector<Processor::CPU_Core::Cache_Data_Object>>> Processor::CPU_Core::GetDataCacheArrays()
	{
		auto cache = getRuntime()->getCache();
		return {std::shared_ptr<std::vector<Cache_Data_Object>>(cache, &cache->L1Data), std::shared_ptr<std::vector<Cache_Data_Object>>(cache, &cache->L2Data)};
	}

