	inline void Processor::CPU_Core::RefreshControlFlowRedirectWindow(unsigned long long memoryAddress)
	{
		unsigned long long bundleBase = memoryAddress - (memoryAddress % VliwBundleBytes);
		unsigned long long bundleEnd = bundleBase + VliwBundleBytes;

		CoreFlagsRegister.setJumpFlag(true);
		CoreFlagsRegister.setJumpOutsideVLIWFlag(memoryAddress < CoreFlagsRegister.VLIW_Begin_MemPtr || memoryAddress >= CoreFlagsRegister.VLIW_End_MemPtr);
		CoreFlagsRegister.VLIW_Begin_MemPtr = bundleBase;
		CoreFlagsRegister.VLIW_End_MemPtr = bundleEnd;
		CoreFlagsRegister.Offset_VLIWOpCode = static_cast<unsigned char>((memoryAddress - bundleBase) / VliwSlotBytes);
	}

	void Processor::CPU_Core::RedirectActiveExecutionForControlFlow(unsigned long long memoryAddress, bool prefetchVliwBundle)
	{
		WriteActiveLivePc(memoryAddress);
		RefreshControlFlowRedirectWindow(memoryAddress);

		if (prefetchVliwBundle)
		{
			PrefetchVLIWBundle(CoreFlagsRegister.VLIW_Begin_MemPtr);
		}
	}

	inline void Processor::CPU_Core::EnterExternalInterruptHandler(unsigned long long handlerAddress)
	{
		Push_Interrupt_EntryPoint_Address();
		FlushPipeline(Core::AssistInvalidationReason::Trap);
		ApplyInterruptTransitionToVirtualThread(ReadActiveVirtualThreadId());
		RedirectActiveExecutionForControlFlow(handlerAddress, !pipeCtrl.Enabled);
	}

	void Processor::CPU_Core::Push_Flag_Register()
	{
		Core_FlagsRegisters_Stack.push_back(CoreFlagsRegister);
	}

	void Processor::CPU_Core::Pop_Flag_Register()
	{
		if (!Core_FlagsRegisters_Stack.empty())
		{
			CoreFlagsRegister = Core_FlagsRegisters_Stack.back();

			Core_FlagsRegisters_Stack.pop_back();
		}
	}

	void Processor::CPU_Core::Push_Call_EntryPoint_Address()
	{
		Call_Callback_Addresses.push_back(ReadActiveLivePc() + 32);
	}

	unsigned long long Processor::CPU_Core::Pop_Call_EntryPoint_Address()
	{
		if (!Call_Callback_Addresses.empty())
		{
			unsigned long long ulong_Call_EntryPoint_Address = Call_Callback_Addresses.back();

			Call_Callback_Addresses.pop_back();

			return ulong_Call_EntryPoint_Address;
		}

		throw ControlFlowStackUnderflowException(L"Call");
	}

	void Processor::CPU_Core::Push_Interrupt_EntryPoint_Address()
	{
		Interrupt_Callback_Addresses.push_back(ReadActiveLivePc() + 32);
	}

	unsigned long long Processor::CPU_Core::Pop_Interrupt_EntryPoint_Address()
	{
		if (!Interrupt_Callback_Addresses.empty())
		{
			unsigned long long ulong_Interrupt_EntryPoint_Address = Interrupt_Callback_Addresses.back();

			Interrupt_Callback_Addresses.pop_back();

			return ulong_Interrupt_EntryPoint_Address;
		}

		throw ControlFlowStackUnderflowException(L"Interrupt");
	}

	void Processor::CPU_Core::ENTRY_POINT(Processor::EntryPoint &EntryPoint)
	{
		if (EntryPoint.getEntryPointAddressAlreadyDefined())
		{
			std::optional<unsigned long long> requestedAddress;
            throw EntryPointDefinitionException(L"ENTRY_POINT", EntryPoint.getEntryPointAddress(), requestedAddress, L"EntryPoint is already declared. Please use another EntryPoint descriptor.");
		}

		EntryPoint.setType(Processor::EntryPoint::EntryPointType::EntryPoint);

		Jump_Call_EntryPoint(EntryPoint, Processor::EntryPoint::EntryPointType::EntryPoint);
	}

	void Processor::CPU_Core::Jump_Call_EntryPoint(Processor::EntryPoint &EntryPoint, Processor::EntryPoint::EntryPointType EntryPoint_CurrentType)
	{
		if (IsCompilerExecutionMode())
		{
			EntryPoint.setType(EntryPoint_CurrentType);

			EntryPoint.AddAddress(static_cast<unsigned long long>(MainMemory->getPosition()));

			PublishPendingEntryPointRelocations(EntryPoint);
		}
	}

	void Processor::CPU_Core::PublishPendingEntryPointRelocations(Processor::EntryPoint &entryPoint)
	{
		if (!entryPoint.getEntryPointAddressAlreadyDefined())
		{
			return;
		}

		PublishPendingEntryPointRelocations(entryPoint, entryPoint.List_Jump_Addresses, RelocationKind::AbsoluteJump);

		PublishPendingEntryPointRelocations(entryPoint, entryPoint.List_Call_Addresses, RelocationKind::AbsoluteCall);

		PublishPendingEntryPointRelocations(entryPoint, entryPoint.List_Interrupt_Addresses, RelocationKind::AbsoluteInterrupt);
	}

	void Processor::CPU_Core::PublishPendingEntryPointRelocations(Processor::EntryPoint &entryPoint, std::vector<unsigned long long> &pendingAddresses, RelocationKind kind)
	{
		if (pendingAddresses.empty())
		{
			return;
		}

		for (; pendingAddresses.size() != 0;)
		{
			unsigned long long emissionCursor = pendingAddresses[pendingAddresses.size() - 1];
			entryPoint.AddRelocation(kind, emissionCursor);
			pendingAddresses.pop_back();
		}
	}

	std::shared_ptr<CanonicalDecodeContext> Processor::CPU_Core::CaptureReplayDecodeContext()
	{
		int vtId = ReadActiveVirtualThreadId();
		if (getArchContexts()->empty() || static_cast<unsigned int>(vtId) >= static_cast<unsigned int>(getArchContexts()->size()) || (*getArchContexts())[vtId] == nullptr)
		{
			return CanonicalDecodeContext::Unbound;
		}

		std::shared_ptr<Processor::MainMemoryArea> mainMemory = GetBoundMainMemory();
		std::shared_ptr<Core::Registers::ArchContextState> archContext = (*getArchContexts())[vtId];
		std::wstring privilegeContext = std::format(L"vt={};priv={};vmx-non-root={};vmx-root={}", vtId, static_cast<int>(archContext->getCurrentPrivilege()), (archContext->isVmxNonRoot() ? 1 : 0), (IsVMXRoot ? 1 : 0));
		std::wstring domainIdentity = std::format(L"core={};vt={};pod={:016X};mem-cert={:016X}", CoreID, vtId, getCsrPodId(), getCsrMemDomainCert());
		std::wstring addressSpaceIdentity = std::format(L"physical-memory-instance={};vmx-root={};vmx-non-root={}", mainMemory->getReplayAddressSpaceIdentity(), (IsVMXRoot ? 1 : 0), (archContext->isVmxNonRoot() ? 1 : 0));
		std::wstring vectorConfiguration = std::format(L"vl={:016X};vtype={:016X};tail={};mask={};fsp-enabled={};fsp-mask={:02X};fsp-policy={}", getVectorConfig()->getVL(), getVectorConfig()->getVTYPE(), getRuntime()->getArchitectural()->VectorConfig.TailAgnostic, getRuntime()->getArchitectural()->VectorConfig.MaskAgnostic, getVectorConfig()->getFSPEnabled(), getVectorConfig()->getFSPStealMask(), getVectorConfig()->getFSPPolicy());

		std::shared_ptr<CanonicalDecodeContext> temp_var = std::make_shared<CanonicalDecodeContext>();
		temp_var->ManifestVersion = GeneratedIsaCatalog::ManifestVersion;
		temp_var->ManifestHash = GeneratedIsaCatalog::ManifestSha256;
		temp_var->ExtensionConfigurationFingerprint = std::format(L"generated-catalog:{};frontend:VliwDecoderV4;selection:unconditional", GeneratedIsaCatalog::ManifestSha256);
		temp_var->DecoderEpoch = ReplayDecoderEpoch;
		temp_var->DecoderVersion = ReplayDecoderVersion;
		temp_var->PrivilegeContext = privilegeContext;
		temp_var->DomainIdentity = domainIdentity;
		temp_var->AddressSpaceIdentity = addressSpaceIdentity;
		temp_var->VectorConfigurationFingerprint = vectorConfiguration;
		temp_var->ExecutableMemoryInvalidationEpoch = mainMemory->getReplayRelevantMutationEpoch();
		temp_var->CodeGenerationEpoch = getRuntime()->getReplay()->CodeGenerationEpoch;
		temp_var->IsReplayEligible = mainMemory->getReplayAddressSpaceIdentity() != 0;
		return temp_var;
	}

	void Processor::CPU_Core::AdvanceReplayCodeGenerationEpoch(bool transientOnly)
	{
// C# TO C++ CONVERTER TASK: There is no C++ equivalent to 'checked' in this context:
// ORIGINAL LINE: _replayCodeGenerationEpoch = checked(_replayCodeGenerationEpoch + 1UL);
		if (getRuntime()->getReplay()->CodeGenerationEpoch == std::numeric_limits<unsigned long long>::max()) throw std::overflow_error("Replay code generation epoch overflow");
		getRuntime()->getReplay()->CodeGenerationEpoch = getRuntime()->getReplay()->CodeGenerationEpoch + 1ULL;
		if (!transientOnly)
		{
// C# TO C++ CONVERTER TASK: There is no C++ equivalent to 'checked' in this context:
// ORIGINAL LINE: _shadowSemanticEpoch = checked(_shadowSemanticEpoch + 1UL);
			if (_shadowSemanticEpoch == std::numeric_limits<unsigned long long>::max()) throw std::overflow_error("Shadow semantic epoch overflow");
			_shadowSemanticEpoch = _shadowSemanticEpoch + 1ULL;
		}
		if (getRuntime()->getReplay()->SemanticShadowLookup != nullptr)
		{
			getRuntime()->getReplay()->SemanticShadowLookup->Invalidate();
		}
	}

	ReplaySemanticShadowObservation Processor::CPU_Core::ObserveReplaySemanticShadow(std::shared_ptr<CanonicalBundle> liveCanonicalBundle)
	{
		auto &lookup = getRuntime()->getReplay()->SemanticShadowLookup;
        if (!lookup) lookup = std::make_shared<ReplaySemanticShadowLookup>();
		return lookup->ObserveLiveDecode(liveCanonicalBundle);
	}

	void Processor::CPU_Core::SynchronizeReplayRelevantMemoryEpoch()
	{
		unsigned long long currentEpoch = GetBoundMainMemory()->getReplayRelevantMutationEpoch();
		if (currentEpoch == getRuntime()->getReplay()->ObservedRelevantMemoryEpoch)
		{
			return;
		}

		InvalidateAllVliwFetchState(Core::ReplayPhaseInvalidationReason::CertificateMutation, true);
		getRuntime()->getReplay()->ObservedRelevantMemoryEpoch = currentEpoch;
	}

	bool Processor::CPU_Core::IsFetchedDecodeContextCurrent()
	{
		const auto fetched = pipeIF.DecodeContext.value_or(nullptr);
		const auto shadow = _shadowFetchContext.value_or(nullptr);
		const bool sameShadowContext = shadow && fetched && *shadow == *fetched;
		const auto payloadAddress = _shadowFrontendMode != ShadowFrontendMode::Off && sameShadowContext && _shadowFetchPc == pipeIF.PC ? _shadowFetchPhysicalPc : pipeIF.PC;
		return fetched && IsFetchedArchitecturalOwnerCurrent() &&
			(!_shadowServingCurrentBundle || (_shadowFrontend && _shadowFrontend->IsCurrent(std::make_shared<HybridCpu::ShadowFrontend::BundleRequest>(pipeIF.PC, ReadActiveVirtualThreadId(), 0)))) &&
			GetBoundMainMemory()->IsInstructionFetchIntentAllowed(pipeIF.PC, 256) &&
			GetBoundMainMemory()->IsInstructionFetchPayloadCurrent(payloadAddress, pipeIF.VLIWBundle, pipeIF.BundleAnnotations, pipeIF.HasBundleAnnotations) &&
			fetched->IsReplayEligible && *fetched == *CaptureReplayDecodeContext();
	}

	void Processor::CPU_Core::CaptureFetchedArchitecturalOwner()
	{
		const int vt = ReadActiveVirtualThreadId();
		pipeIF.OwnerVirtualThreadId = vt;
		pipeIF.ArchitecturalContextOwner = getArchContexts() && static_cast<unsigned int>(vt) < getArchContexts()->size() ? (*getArchContexts())[vt] : nullptr;
	}

	bool Processor::CPU_Core::IsFetchedArchitecturalOwnerCurrent()
	{
		const int vt = pipeIF.OwnerVirtualThreadId;
		return vt == ReadActiveVirtualThreadId() && getArchContexts() && static_cast<unsigned int>(vt) < getArchContexts()->size() &&
			pipeIF.ArchitecturalContextOwner && pipeIF.ArchitecturalContextOwner == (*getArchContexts())[vt];
	}

	bool Processor::CPU_Core::IsSourceRefreshContextCompatible(std::shared_ptr<CanonicalDecodeContext> previous, std::shared_ptr<Core::Registers::ArchContextState> owner)
	{
		const auto current = CaptureReplayDecodeContext();
		const int vt = ReadActiveVirtualThreadId();
		if (!previous || !current || !previous->IsReplayEligible || !current->IsReplayEligible || !getArchContexts() ||
			static_cast<unsigned int>(vt) >= getArchContexts()->size() || !owner || owner != (*getArchContexts())[vt]) return false;
		auto adjusted = *previous;
		adjusted.ExecutableMemoryInvalidationEpoch = current->ExecutableMemoryInvalidationEpoch;
		adjusted.CodeGenerationEpoch = current->CodeGenerationEpoch;
		return adjusted == *current;
	}

	bool Processor::CPU_Core::HasPendingSourceRefreshForCurrentFetch()
	{
		const auto previous = getRuntime()->getDecode()->SourceRefreshContext.value_or(nullptr);
		return previous && getRuntime()->getDecode()->BundleProgress.getBundlePc() == pipeIF.PC && IsFetchedArchitecturalOwnerCurrent() &&
			IsSourceRefreshContextCompatible(previous, getRuntime()->getDecode()->SourceRefreshArchitecturalOwner);
	}

	void Processor::CPU_Core::ClearPendingSourceRefresh()
	{
		getRuntime()->getDecode()->SourceRefreshContext = std::nullopt;
		getRuntime()->getDecode()->SourceRefreshArchitecturalOwner = nullptr;
	}

	bool Processor::CPU_Core::PreserveProgressForSourceRefresh()
	{
		if (HasPendingSourceRefreshForCurrentFetch()) return true;
		const auto previous = pipeIF.DecodeContext.value_or(nullptr);
		const auto &progress = getRuntime()->getDecode()->BundleProgress;
		if (!getRuntime()->getDecode()->BundleDecodedAndPacked || !progress.getHasRemaining() || progress.getBundlePc() != pipeIF.PC ||
			!IsFetchedArchitecturalOwnerCurrent() || !previous || !IsSourceRefreshContextCompatible(previous, pipeIF.ArchitecturalContextOwner)) return false;
		getRuntime()->getDecode()->SourceRefreshContext = previous;
		getRuntime()->getDecode()->SourceRefreshArchitecturalOwner = pipeIF.ArchitecturalContextOwner;
		return true;
	}
