	void Processor::CPU_Core::ConfigureShadowFrontend(ShadowFrontendMode mode)
	{
		if (mode != ShadowFrontendMode::Off && mode != ShadowFrontendMode::Observe && mode != ShadowFrontendMode::ColdWarm)
		{
			throw std::out_of_range("mode");
		}
		if (pipeCtrl.getCycleCount() != 0 && pipeCtrl.Enabled)
		{
			throw std::logic_error("Configure ShadowFrontend before starting execution or after disabling the pipeline.");
		}
		_shadowFrontendMode = mode;
		_shadowFrontend = nullptr; // New provider/cache lifetime; never recover a poisoned object.
	}

	std::shared_ptr<ShadowFrontendCpuSnapshot> Processor::CPU_Core::ReadShadowFrontendSnapshot()
	{
		return std::make_shared<ShadowFrontendCpuSnapshot>(ShadowFrontendCpuSnapshot{_shadowFrontendMode, _shadowComparisons, _shadowMismatches, _shadowServedCold, _shadowServedWarm, _shadowUnsupported, _shadowRuntimeCanonicalDecodes, _shadowRuntimeRestores, (_shadowFrontend == nullptr ? nullptr : _shadowFrontend->getCache()->getTelemetry())});
	}

	void Processor::CPU_Core::ResetShadowFrontendLifetime()
	{
		_shadowFrontend = nullptr;
		_shadowFetchContext = std::nullopt;
		_shadowFetchTranslationOwner = nullptr;
		_shadowServingCurrentBundle = false;
	}

	std::optional<std::shared_ptr<IngressResult>> Processor::CPU_Core::RequestShadowFrontend()
	{
		_shadowIngressStale = false;
		if (_shadowFrontendMode == ShadowFrontendMode::Off)
		{
			return std::nullopt;
		}
		// The original full-range Fetch translation already ran. Immutable
		// bounded mappings can serve after that source capture; mutable
		// two-stage mappings remain on the original route pending adoption.
		if (!getCpuInstructionTranslationOwner()->getHasImmutableInstructionMapping() || _shadowFetchContext != pipeIF.DecodeContext || _shadowFetchPc != pipeIF.PC || pipeIF.VLIWBundle.empty() || !pipeIF.BundleAnnotations)
		{
			_shadowUnsupported++;
			return std::nullopt;
		}
		if (_shadowFrontend == nullptr || !_shadowFrontend->isTranslationOwnerCurrent())
		{
			_shadowFrontend = std::make_shared<CpuShadowFrontend>(shared_from_this());
			_shadowFrontend->InitializeCache();
		}
		std::shared_ptr<IngressResult> result = _shadowFrontend->Request();
		_shadowIngressStale = result->Facts == nullptr;
		return result;
	}

	bool Processor::CPU_Core::IsShadowFetchTranslationCurrent()
	{
		std::shared_ptr<Core::Memory::CpuInstructionTranslationRequest> original = _shadowFetchTranslationRequest;
		if (_shadowFetchTranslationOwner != getCpuInstructionTranslationOwner() || !getCpuInstructionTranslationOwner()->getHasImmutableInstructionMapping() || original->AccessKind != Core::Memory::CpuInstructionTranslationAccessKind::InstructionFetch || original->VirtualAddress != pipeIF.PC || original->AccessSize != 256 || original->Scope.VirtualThreadId != ReadActiveVirtualThreadId())
		{
			return false;
		}
		// Reuse the original request identity. A guard must neither issue a
		// new fetch identity nor publish a second translation-fault effect.
		std::shared_ptr<Core::Memory::CpuInstructionTranslationResult> current = getCpuInstructionTranslationOwner()->Translate(original);
		return current->Succeeded && current == _shadowFetchTranslationResult && current->PhysicalAddress == _shadowFetchPhysicalPc;
	}

	void Processor::CPU_Core::CompareShadowFrontend(std::optional<std::shared_ptr<IngressResult>> &ingress, std::shared_ptr<CanonicalBundle> canonical)
	{
		if (!ingress || !*ingress || !(**ingress).Facts)
		{
			return;
		}
		_shadowComparisons++;
		if (!ShadowSemanticProjection::Project(canonical)->SameFacts((**ingress).Facts))
		{
			ShadowFrontendMismatch(canonical->getBundleAddress(), L"canonical success differs from Shadow facts");
		}
	}

	void Processor::CPU_Core::CompareShadowFrontendFailure(std::optional<std::shared_ptr<IngressResult>> &ingress, std::span<const VLIW_Instruction> raw, std::shared_ptr<VliwBundleAnnotations> annotations)
	{
		if (!ingress || !*ingress || !(**ingress).Facts)
		{
			return;
		}
		_shadowComparisons++;
	// C# TO C++ CONVERTER TASK: There is no C++ equivalent to the C# 'null-forgiving operator':
	// ORIGINAL LINE: if (DeclarativeDecoderPipeline.TryDecodeBundle(raw, annotations, pipeIF.PC, 0, pipeIF.DecodeContext, out _, out DecodeFailure? failure) || !ShadowSemanticProjection.Illegal(new(pipeIF.VLIWBundle!), failure!).SameFacts(ingress.Facts))
		std::optional<std::shared_ptr<DeclarativeDecodedBundle>> decodedBundle;
		std::optional<std::shared_ptr<DecodeFailure>> failure;
		if (DeclarativeDecoderPipeline::TryDecodeBundle(raw, annotations, pipeIF.PC, 0, pipeIF.DecodeContext, decodedBundle, failure) || !failure || !*failure || !ShadowSemanticProjection::Illegal(std::make_shared<FrozenBytes>(pipeIF.VLIWBundle), *failure)->SameFacts((**ingress).Facts))
		{
			ShadowFrontendMismatch(pipeIF.PC, L"ordered typed canonical failure differs from Shadow facts");
		}
	}

	void Processor::CPU_Core::ShadowFrontendMismatch(unsigned long long pc, const std::wstring &reason)
	{
		_shadowMismatches++;
		throw InvalidOperationException(std::format(L"ShadowFrontend terminal comparator mismatch at PC 0x{:X}: {}", pc, reason));
	}

	bool Processor::CPU_Core::TryServeShadowFrontend(std::optional<std::shared_ptr<IngressResult>> &ingress)
	{
		if (_shadowFrontendMode != ShadowFrontendMode::ColdWarm || !ingress || !*ingress) return false;
		auto result = *ingress;
		if (!result->Facts || !result->Facts->isSuccess()) return false;
		auto facts = result->Facts;
		if (!facts->getRaw()->Equals(std::make_shared<FrozenBytes>(pipeIF.VLIWBundle)))
		{
			ShadowFrontendMismatch(pipeIF.PC, L"cached raw differs from the actual private fetched source");
		}
		if (!pipeIF.DecodeContext || !*pipeIF.DecodeContext) return false;
		auto canonical = ShadowSemanticProjection::Restore(facts, result->Placement, *pipeIF.DecodeContext);
		auto state = BuildReplayDecodedBundleState(ReplayEntry::Create(canonical), pipeIF.PC);
		auto memory = GetBoundMainMemory();
		{
			std::scoped_lock<std::mutex> lock(memory->getInstructionFetchCommitMutex());
			if (!IsFetchedDecodeContextCurrent() || !_shadowFrontend || !_shadowFrontend->IsCurrent(result->Placement))
			{
				_shadowIngressStale = true;
				return false;
			}
			ObserveReplaySemanticShadow(canonical);
			PublishCurrentCanonicalDecodedBundleState(state);
			_shadowRuntimeRestores++;
			_shadowServingCurrentBundle = true;
			if (result->Outcome == IngressOutcome::Warm) _shadowServedWarm++;
			else _shadowServedCold++;
			return true;
		}
	}
