	Processor::CPU_Core::CpuShadowFrontend::CpuShadowFrontend(std::shared_ptr<CPU_Core> owner) : core(std::move(owner)), translationOwner(core->getCpuInstructionTranslationOwner()) {}

	void Processor::CPU_Core::CpuShadowFrontend::InitializeCache()
	{
		if (Cache) return;
		auto self = core->_shadowFrontend;
		Cache = std::make_shared<SemanticBundleCache>(std::make_shared<FreshnessState>(), [this](std::shared_ptr<BundleRequest>) { return CaptureContext(); }, self, self);
	}
	bool Processor::CPU_Core::CpuShadowFrontend::isTranslationOwnerCurrent() const
	{
		return translationOwner == core->getCpuInstructionTranslationOwner();
	}

	std::shared_ptr<DecodeContext> Processor::CPU_Core::CpuShadowFrontend::CaptureContext()
	{
		const auto c = core->CaptureReplayDecodeContext();
		const auto current = core->pipeIF.BundleAnnotations;
		const int vt = core->ReadActiveVirtualThreadId();
		const auto contexts = core->getArchContexts();
		std::shared_ptr<Core::Registers::ArchContextState> owner;
		if (contexts && vt >= 0 && static_cast<std::size_t>(vt) < contexts->size()) owner = (*contexts)[vt];
		if (vt < 0 || static_cast<std::size_t>(vt) >= contextOwners.size()) throw std::out_of_range("active virtual thread id");
		if (contextOwners[vt] != owner)
		{
			contextOwners[vt] = owner;
			contextIncarnations[vt] = Guid::NewGuid().ToString(L"N");
		}
		return std::make_shared<DecodeContext>(DecodeContext{
			c->ManifestVersion, c->ManifestHash, c->ExtensionConfigurationFingerprint, c->DecoderEpoch, c->DecoderVersion,
			c->PrivilegeContext, c->DomainIdentity,
			std::format(L"{};translation-incarnation={};physical={:016X}", c->AddressSpaceIdentity, incarnation, core->_shadowFetchPhysicalPc),
			c->VectorConfigurationFingerprint, c->ExecutableMemoryInvalidationEpoch, core->_shadowSemanticEpoch,
			c->IsReplayEligible && current && owner && isTranslationOwnerCurrent(), incarnation + L":" + contextIncarnations[vt],
			current ? ShadowSemanticProjection::SidebandIdentity(current) : L"unbound"});
	}
