	inline void Processor::CPU_Core::ReadCurrentDecodedBundleRuntimeState(Core::DecodedBundleRuntimeState &runtimeState)
	{
		ReplaceSnapshot(runtimeState, getRuntime()->getDecode()->BundleRuntime);
	}

	inline void Processor::CPU_Core::ReadCurrentExecutionDecodedBundleRuntimeState(Core::DecodedBundleRuntimeState &runtimeState)
	{
		if (getRuntime()->getDecode()->DerivedIssuePlan.isActive())
		{
			getRuntime()->getDecode()->DerivedIssuePlan.ValidateAgainstBaseRuntimeState(getRuntime()->getDecode()->BundleRuntime, L"ReadCurrentExecutionDecodedBundleRuntimeState");
			ReplaceSnapshot(runtimeState, getRuntime()->getDecode()->DerivedIssuePlan.getRuntimeState());
			return;
		}

		ReplaceSnapshot(runtimeState, getRuntime()->getDecode()->BundleRuntime);
	}

	inline void Processor::CPU_Core::ReadCurrentForegroundDecodedBundleRuntimeState(Core::DecodedBundleRuntimeState &runtimeState)
	{
		ReadCurrentExecutionDecodedBundleRuntimeState(runtimeState);
		ReplaceSnapshot(runtimeState, runtimeState.ApplyProgressProjection(ProjectCurrentDecodedBundleTransportFactsThroughProgress(runtimeState.getTransportFacts())));
	}

