	inline Core::DecodedBundleTransportFacts Processor::CPU_Core::ProjectCurrentDecodedBundleTransportFactsThroughProgress(Core::DecodedBundleTransportFacts const transportFacts)
	{
		Core::BundleProgressState progressState = getRuntime()->getDecode()->BundleProgress;
		if (progressState.getBundlePc() != transportFacts.getPC())
		{
			ReplaceSnapshot(progressState, Core::BundleProgressState::CreateForCursor(transportFacts.getPC(), transportFacts.getValidNonEmptyMask(), getRuntime()->getDecode()->PipelineBundleSlot));
			ReplaceSnapshot(getRuntime()->getDecode()->BundleProgress, progressState);
		}

		return Core::DecodedBundleSlotCarrierBuilder::BuildTransportFactsFromProgressProjection(transportFacts, progressState.getRemainingMask());
	}

	inline void Processor::CPU_Core::SyncCurrentDecodedBundleProgressState(Core::DecodedBundleTransportFacts const transportFacts, bool preserveCurrentProgress, unsigned char consumedMask)
	{
		unsigned char remainingMask = transportFacts.getValidNonEmptyMask();
		if (preserveCurrentProgress && getRuntime()->getDecode()->BundleProgress.getBundlePc() == transportFacts.getPC())
		{
			remainingMask = static_cast<unsigned char>(getRuntime()->getDecode()->BundleProgress.getRemainingMask() & remainingMask);
			consumedMask |= getRuntime()->getDecode()->BundleProgress.getConsumedMask();
		}

		remainingMask = static_cast<unsigned char>(remainingMask & ~consumedMask);

		ReplaceSnapshot(getRuntime()->getDecode()->BundleProgress, Core::BundleProgressState::CreateForCursor(transportFacts.getPC(), remainingMask, getRuntime()->getDecode()->PipelineBundleSlot, consumedMask));
	}

	inline void Processor::CPU_Core::PublishCurrentFallbackDecodedBundleState(unsigned long long pc, Core::DecodedBundleTransportFacts const transportFacts, unsigned long long bundleSerial)
	{
		pipeCtrl.setDecodeFaultBundleCount(pipeCtrl.getDecodeFaultBundleCount() + 1);
		// A canonical full-bundle fault keeps its original priority;
		// never hide it because its trap slot was in the old prefix.
		if (getRuntime()->getDecode()->SourceRefreshContext)
		{
			getRuntime()->getDecode()->PipelineBundleSlot = 0;
		}
		ClearPendingSourceRefresh();
		PublishCurrentDecodedBundleRuntimeState(Core::DecodedBundleRuntimeState::CreateFallback(pc, transportFacts, bundleSerial));
	}

	inline void Processor::CPU_Core::PublishCurrentCanonicalDecodedBundleState(Core::DecodedBundleRuntimeState const runtimeState)
	{
		bool resume = HasPendingSourceRefreshForCurrentFetch();
		if (resume)
		{
			ReplaceSnapshot(getRuntime()->getDecode()->BundleProgress, getRuntime()->getDecode()->BundleProgress.RebaseAfterSourceRefresh(runtimeState.getTransportFacts().getValidNonEmptyMask()));
		}
		PublishCurrentDecodedBundleRuntimeState(runtimeState, resume);
		if (resume)
		{
			getRuntime()->getDecode()->PipelineBundleSlot = getRuntime()->getDecode()->BundleProgress.getNextSlotIndex();
		}
		ClearPendingSourceRefresh();
	}

