	inline bool Processor::CPU_Core::TryReadFetchedBundleInstructionUnchecked(std::span<const unsigned char> source, int slotIndex, VLIW_Instruction &instruction)
	{
		instruction = HybridCPU_ISE::Arch::VLIW_Instruction();

		if (static_cast<unsigned int>(slotIndex) >= 8)
		{
			return false;
		}

		int offset = slotIndex * 32;
		if (offset < 0 || static_cast<std::size_t>(offset) > source.size() || source.size() - static_cast<std::size_t>(offset) < 32)
		{
			return false;
		}

		auto readWord = [&source](std::size_t at) {
			std::uint64_t value = 0;
			for (std::size_t byte = 0; byte < 8; ++byte) value |= static_cast<std::uint64_t>(source[at + byte]) << (byte * 8);
			return value;
		};
		instruction.setWord0(readWord(offset));
		instruction.setWord1(readWord(offset + 8));
		instruction.setWord2(readWord(offset + 16));
		instruction.setWord3(readWord(offset + 24));
		return true;
	}

	bool Processor::CPU_Core::TryCopyFetchedBundleInstructionsUnchecked(std::span<const unsigned char> source, std::span<VLIW_Instruction> destination)
	{
		if (destination.size() < 8)
		{
			throw std::out_of_range("Destination span must have room for 8 bundle slots.");
		}

		for (int slotIndex = 0; slotIndex < 8; slotIndex++)
		{
			if (!TryReadFetchedBundleInstructionUnchecked(source, slotIndex, destination[slotIndex]))
			{
				return false;
			}
		}

		return true;
	}

