	inline void Processor::CPU_Core::ResetAssistRuntimeState()
	{
		// Pipeline reinitialization can follow an earlier execution on the
		// same core. Never revive its local or already delivered assists.
		InvalidateAssistRuntime(Core::AssistInvalidationReason::OwnerInvalidation);
		getRuntime()->getAssist()->LastInvalidationReason = Core::AssistInvalidationReason::None;
		getRuntime()->getTelemetry()->ClearAssist();
	}

