	inline void Processor::CPU_Core::InvalidateAssistRuntime(Core::AssistInvalidationReason reason)
	{
		// The exhausted value is terminal, never a new usable generation.
		if (getRuntime()->getAssist()->RuntimeEpoch != std::numeric_limits<unsigned long long>::max())
		{
			getRuntime()->getAssist()->RuntimeEpoch++;
		}
		// Recipients consult the published donor snapshot, not this core's
		// private epoch. Revoke it before the boundary can publish new state.
		if (Processor::GetPodForCore(static_cast<int>(CoreID)) != nullptr)
		{
			Processor::GetPodForCore(static_cast<int>(CoreID))->InvalidateAssistOwnerSnapshot(Processor::GetLocalCoreId(static_cast<int>(CoreID)));
		}
		getRuntime()->getTelemetry()->AssistInvalidationCount++;
		getRuntime()->getAssist()->LastInvalidationReason = reason;
		if (_fspScheduler != nullptr)
		{
			_fspScheduler->InvalidateAssistNominationState(reason);
		}
		if (getRuntime()->getAssist()->RuntimeEpoch == std::numeric_limits<unsigned long long>::max())
		{
			throw InvalidOperationException(L"Assist runtime epoch exhausted; the core cannot issue further assists.");
		}
	}

