	inline unsigned char Processor::CPU_Core::BuildRetireSlotMask(std::span<const unsigned char> retireOrder, int retireLaneCount)
	{
		unsigned char slotMask = 0;
		for (int laneIndex = 0; laneIndex < retireLaneCount; laneIndex++)
		{
			slotMask |= static_cast<unsigned char>(1 << retireOrder[laneIndex]);
		}

		return slotMask;
	}

