	Processor::CPU_Core::PipelineObservationSnapshot Processor::CPU_Core::GetPipelineObservationSnapshot()
	{
		Core::DecodedBundleRuntimeState observationState = getRuntime()->getDecode()->BundleRuntime;
		ReadCurrentForegroundDecodedBundleRuntimeState(observationState);
		Core::DecodedBundleTransportFacts observationTransportFacts = observationState.getTransportFacts();
		const auto cycleCount = pipeCtrl.getCycleCount();
		const auto instructionsRetired = pipeCtrl.getInstructionsRetired();
		const auto stallCycles = pipeCtrl.getStallCycles();
		Core::CoreTimebaseSnapshot timebase = Core::CoreTimebaseSnapshot(cycleCount, pipeCtrl.Stalled, pipeCtrl.Enabled || cycleCount != 0 || instructionsRetired != 0 || stallCycles != 0 || pipeCtrl.Stalled, pipeCtrl.Enabled || cycleCount != 0 || instructionsRetired != 0 || stallCycles != 0 || pipeCtrl.Stalled ? L"" : L"Pipeline timebase has not published any live timing facts yet.");

		return PipelineObservationSnapshot(ReadActiveVirtualThreadId(), ReadActiveLivePc(), timebase, ReadActiveVirtualThreadPipelineState(), pipeCtrl.CreateSnapshot(), getRuntime()->getDecode()->PipelineBundleSlot, observationTransportFacts.getPC(), observationState.getStateOwnerKind(), observationState.getStateEpoch(), observationState.getStateVersion(), observationTransportFacts.getStateKind(), observationTransportFacts.getStateOrigin(), observationTransportFacts.getValidMask(), observationTransportFacts.getNopMask(), observationState.getHasCanonicalDecode(), observationState.getHasCanonicalLegality(), observationState.getHasDecodeFault(), getRuntime()->getRetire()->DecodePublicationCertificate, getRuntime()->getRetire()->ExecuteCompletionCertificate, getRuntime()->getRetire()->RetireVisibilityCertificate, getRuntime()->getAdmission()->Preparation, getRuntime()->getAdmission()->CandidateView, getRuntime()->getAdmission()->DecisionDraft, getRuntime()->getAdmission()->Handoff);
	}

	inline bool Processor::CPU_Core::CanRouteDecodedSlotToConfiguredExecutionSurface(Core::DecodedBundleSlotDescriptor const slotDescriptor)
	{
		if (!slotDescriptor.isValid() || slotDescriptor.GetRuntimeExecutionIsEmptyOrNop())
		{
			return true;
		}

		unsigned int opCode = slotDescriptor.GetRuntimeExecutionOpCode();
		if (IsUnsupportedMainlineStreamControlSurface(opCode))
		{
			return false;
		}

		return std::dynamic_pointer_cast<Core::VmxMicroOp>(slotDescriptor.getMicroOp()) == nullptr || getHasWiredVmxExecutionPlane();
	}

	inline void Processor::CPU_Core::EnforceDecodedSlotExecutionSurfaceContract(Core::DecodedBundleSlotDescriptor const slotDescriptor, unsigned long long bundlePc)
	{
		if (CanRouteDecodedSlotToConfiguredExecutionSurface(slotDescriptor))
		{
			return;
		}

		unsigned int opCode = slotDescriptor.GetRuntimeExecutionOpCode();
		if (IsUnsupportedMainlineStreamControlSurface(opCode))
		{
			FlushPipeline(Core::AssistInvalidationReason::Trap);
			throw Core::UnsupportedExecutionSurfaceException::CreateForStreamControl(slotDescriptor.getSlotIndex(), opCode, bundlePc);
		}

		throw CreateUnwiredVmxDecodeSurfaceException(slotDescriptor.getSlotIndex(), opCode, bundlePc);
	}

	inline Core::IssuePacketLane Processor::CPU_Core::ApplyIssueLaneExecutionSurfaceContract(Core::IssuePacketLane issueLane, unsigned long long bundlePc)
	{
		if (!issueLane.isOccupied())
		{
			return issueLane;
		}

		unsigned int opCode = ResolveIssueLaneExecutionSurfaceOpCode(issueLane);
		if (IsUnsupportedMainlineStreamControlSurface(opCode))
		{
			FlushPipeline(Core::AssistInvalidationReason::Trap);
			throw Core::UnsupportedExecutionSurfaceException::CreateForStreamControl(issueLane.getSlotIndex(), opCode, bundlePc);
		}

		if (std::dynamic_pointer_cast<Core::VmxMicroOp>(issueLane.getMicroOp()) != nullptr && !getHasWiredVmxExecutionPlane())
		{
			throw CreateUnwiredVmxIssuePacketSurfaceException(issueLane.getSlotIndex(), ResolveIssueLaneExecutionSurfaceOpCode(issueLane), bundlePc);
		}

		return issueLane;
	}

	inline unsigned int Processor::CPU_Core::ResolveIssueLaneExecutionSurfaceOpCode(Core::IssuePacketLane const issueLane)
	{
		return issueLane.getOpCode();
	}

	inline bool Processor::CPU_Core::IsUnsupportedMainlineStreamControlSurface(unsigned int opCode)
	{
		return (opCode == IsaOpcodeValues::STREAM_SETUP || opCode == IsaOpcodeValues::STREAM_START);
	}

	std::shared_ptr<InvalidOperationException> Processor::CPU_Core::CreateUnwiredVmxDecodeSurfaceException(unsigned char slotIndex, unsigned int opCode, unsigned long long bundlePc)
	{
		return std::make_shared<InvalidOperationException>(std::format(L"VMX slot {} (opcode 0x{:X}) at PC 0x{:X} reached decode/admission without a wired VMX execution plane. Admission/routing must reject or defer VMX before execute.", slotIndex, opCode, bundlePc));
	}

	std::shared_ptr<InvalidOperationException> Processor::CPU_Core::CreateUnwiredVmxIssuePacketSurfaceException(unsigned char slotIndex, unsigned int opCode, unsigned long long bundlePc)
	{
		return std::make_shared<InvalidOperationException>(std::format(L"VMX slot {} (opcode 0x{:X}) at PC 0x{:X} reached issue-packet execute materialization without a wired VMX execution plane. Issue-packet routing must reject live VMX lanes explicitly instead of dropping them before execute.", slotIndex, opCode, bundlePc));
	}

