	void Processor::CPU_Core::EnforceIssueLaneExecutionSurfaceContractForTesting(Core::IssuePacketLane const issueLane, unsigned long long bundlePc)
	{
		static_cast<void>(ApplyIssueLaneExecutionSurfaceContract(issueLane, bundlePc));
	}

	inline void Processor::CPU_Core::RecordTraceEvent(unsigned long long pc, unsigned int opCode, unsigned long long resultValue, int ownerThreadId, int virtualThreadId, bool wasFspInjected, int originalThreadId)
	{
		if (Processor::Coverage != nullptr && opCode < 256)
		{
			Processor::Coverage->Record(opCode);
		}

// C# TO C++ CONVERTER WARNING: Nullable reference types have no equivalent in C++:
// ORIGINAL LINE: HybridCPU_ISE.Core.TraceSink? traceSink = Processor.TraceSink;
		std::shared_ptr<HybridCPU_ISE::Core::TraceSink> traceSink = Processor::TraceSink;
		if (traceSink != nullptr)
		{
			PipelineObservationSnapshot observation = GetPipelineObservationSnapshot();
			TraceEvent evt(static_cast<long long>(pc), static_cast<int>(pc / 256), static_cast<int>((pc % 256) / 32), opCode);
			evt.Result = resultValue;
			evt.ExceptionCount = this->getExceptionStatus()->TotalExceptions();

			if (this->getExceptionStatus()->HasExceptions())
			{
				evt.Flags = {.Overflow = this->getExceptionStatus()->getOverflowCount() > 0, .Underflow = this->getExceptionStatus()->getUnderflowCount() > 0, .DivByZero = this->getExceptionStatus()->getDivByZeroCount() > 0, .InvalidOp = this->getExceptionStatus()->getInvalidOpCount() > 0, .Inexact = this->getExceptionStatus()->getInexactCount() > 0};

				if (Processor::Coverage != nullptr)
				{
					Processor::Coverage->RecordException(evt.Flags);
				}
			}

			traceSink->Record(evt);

			if (traceSink->getShouldCaptureFullState())
			{
				const auto phaseContext = _loopBuffer.getCurrentReplayPhase();
				const auto phaseMetrics = _fspScheduler != nullptr ? _fspScheduler->GetPhaseMetrics() : SchedulerPhaseMetrics{};
				const auto invalidationReason = _fspScheduler != nullptr ? _fspScheduler->getLastPhaseCertificateInvalidationReason() : Core::ReplayPhaseInvalidationReason::None;
				HybridCPU_ISE::Core::FullStateTraceEvent temp_var;
				temp_var.PC = static_cast<long long>(pc);
				temp_var.BundleId = static_cast<int>(pc / 256);
				temp_var.OpIndex = static_cast<int>((pc % 256) / 32);
				temp_var.Opcode = opCode;
				temp_var.ThreadId = wasFspInjected ? 0 : ownerThreadId;
				temp_var.CycleNumber = static_cast<long long>(pipeCtrl.getCycleCount());
				temp_var.RegisterFile = std::make_shared<std::vector<unsigned long long>>(CaptureTraceRegisterFile(ownerThreadId));
				temp_var.PredicateRegisters = std::make_shared<std::vector<unsigned short>>(CaptureTracePredicateRegisters());
				temp_var.WasStolenSlot = wasFspInjected;
				temp_var.OriginalThreadId = originalThreadId;
				temp_var.PipelineStage = L"WB";
				temp_var.Stalled = observation.getPipelineControl().Stalled;
				temp_var.StallReason = PipelineStallText::Render(observation.getPipelineControl().StallReason, PipelineStallTextStyle::Trace);
				temp_var.DecodedBundleStateOwnerKind = observation.getDecodedBundleStateOwnerKind();
				temp_var.DecodedBundleStateEpoch = observation.getDecodedBundleStateEpoch();
				temp_var.DecodedBundleStateVersion = observation.getDecodedBundleStateVersion();
				temp_var.DecodedBundleStateKind = observation.getDecodedBundleStateKind();
				temp_var.DecodedBundleStateOrigin = observation.getDecodedBundleStateOrigin();
				temp_var.DecodedBundlePc = observation.getDecodedBundlePc();
				temp_var.DecodedBundleValidMask = observation.getDecodedBundleValidMask();
				temp_var.DecodedBundleNopMask = observation.getDecodedBundleNopMask();
				temp_var.DecodedBundleHasCanonicalDecode = observation.getDecodedBundleHasCanonicalDecode();
				temp_var.DecodedBundleHasCanonicalLegality = observation.getDecodedBundleHasCanonicalLegality();
				temp_var.DecodedBundleHasDecodeFault = observation.getDecodedBundleHasDecodeFault();
				temp_var.ActiveMemoryRequests = GetBoundMemorySubsystemCurrentQueuedRequests();
				temp_var.MemorySubsystemCycle = 0;
				if (_fspScheduler) temp_var.ThreadReadyQueueDepths = std::make_shared<std::vector<int>>(std::initializer_list<int>{_fspScheduler->GetOutstandingMemoryCount(0), _fspScheduler->GetOutstandingMemoryCount(1), _fspScheduler->GetOutstandingMemoryCount(2), _fspScheduler->GetOutstandingMemoryCount(3)});
				temp_var.CurrentFSPPolicy = phaseContext.isActive() ? L"ReplayAwarePhase1" : L"DeterministicFSP";
				traceSink->RecordPhaseAwareState(temp_var, phaseContext, phaseMetrics, phaseContext.isActive() && invalidationReason == Core::ReplayPhaseInvalidationReason::None);
			}
		}
	}

	std::vector<unsigned long long> Processor::CPU_Core::CaptureTraceRegisterFile(int ownerThreadId)
	{
		int vtId = NormalizePipelineStateVtId(ownerThreadId);
		std::vector<unsigned long long> registers(YAKSys_Hybrid_CPU::Core::Registers::RenameMap::ArchRegs);
		for (int i = 0; i < registers.size(); i++)
		{
			registers[i] = ReadArch(vtId, i);
		}

		return registers;
	}

	std::vector<unsigned short> Processor::CPU_Core::CaptureTracePredicateRegisters()
	{
		std::vector<unsigned short> predicates(16);
		for (int i = 0; i < predicates.size(); i++)
		{
			predicates[i] = static_cast<unsigned short>(GetPredicateRegister(i) & 0xFFFF);
		}

		return predicates;
	}

	void Processor::CPU_Core::RecordPhaseTimelineSample(const std::wstring &pipelineStage)
	{
// C# TO C++ CONVERTER WARNING: Nullable reference types have no equivalent in C++:
// ORIGINAL LINE: HybridCPU_ISE.Core.TraceSink? traceSink = Processor.TraceSink;
		std::shared_ptr<HybridCPU_ISE::Core::TraceSink> traceSink = Processor::TraceSink;
		if (traceSink == nullptr)
		{
			return;
		}

		ReplayPhaseContext phaseContext = _loopBuffer.getCurrentReplayPhase();
		if (!phaseContext.isActive() && !pipeCtrl.Stalled)
		{
			return;
		}

		unsigned long long samplePc = GetTraceSamplePC();
		unsigned int sampleOpCode = GetTraceSampleOpCode();
		int ownerThreadId = GetTraceSampleOwnerThreadId();
		bool wasFspInjected = GetTraceSampleWasFspInjected();
		int originalThreadId = GetTraceSampleOriginalThreadId();
		PipelineObservationSnapshot observation = GetPipelineObservationSnapshot();
		std::wstring runtimePolicy = GetTraceRuntimePolicyText(observation, phaseContext);

		if (traceSink->getShouldCaptureFullState())
		{
			const auto phaseMetrics = _fspScheduler != nullptr ? _fspScheduler->GetPhaseMetrics() : SchedulerPhaseMetrics{};
			const auto invalidationReason = _fspScheduler != nullptr ? _fspScheduler->getLastPhaseCertificateInvalidationReason() : Core::ReplayPhaseInvalidationReason::None;
			HybridCPU_ISE::Core::FullStateTraceEvent temp_var;
			temp_var.PC = static_cast<long long>(samplePc);
			temp_var.BundleId = static_cast<int>(samplePc / 256);
			temp_var.OpIndex = -1;
			temp_var.Opcode = sampleOpCode;
			temp_var.ThreadId = wasFspInjected ? 0 : ownerThreadId;
			temp_var.CycleNumber = static_cast<long long>(pipeCtrl.getCycleCount());
			temp_var.RegisterFile = std::make_shared<std::vector<unsigned long long>>(CaptureTraceRegisterFile(ownerThreadId));
			temp_var.PredicateRegisters = std::make_shared<std::vector<unsigned short>>(CaptureTracePredicateRegisters());
			temp_var.WasStolenSlot = wasFspInjected;
			temp_var.OriginalThreadId = originalThreadId;
			temp_var.PipelineStage = pipelineStage;
			temp_var.Stalled = observation.getPipelineControl().Stalled;
			temp_var.StallReason = PipelineStallText::Render(observation.getPipelineControl().StallReason, PipelineStallTextStyle::Trace);
			temp_var.DecodedBundleStateOwnerKind = observation.getDecodedBundleStateOwnerKind();
			temp_var.DecodedBundleStateEpoch = observation.getDecodedBundleStateEpoch();
			temp_var.DecodedBundleStateVersion = observation.getDecodedBundleStateVersion();
			temp_var.DecodedBundleStateKind = observation.getDecodedBundleStateKind();
			temp_var.DecodedBundleStateOrigin = observation.getDecodedBundleStateOrigin();
			temp_var.DecodedBundlePc = observation.getDecodedBundlePc();
			temp_var.DecodedBundleValidMask = observation.getDecodedBundleValidMask();
			temp_var.DecodedBundleNopMask = observation.getDecodedBundleNopMask();
			temp_var.DecodedBundleHasCanonicalDecode = observation.getDecodedBundleHasCanonicalDecode();
			temp_var.DecodedBundleHasCanonicalLegality = observation.getDecodedBundleHasCanonicalLegality();
			temp_var.DecodedBundleHasDecodeFault = observation.getDecodedBundleHasDecodeFault();
			temp_var.BankQueueDepths = std::make_shared<std::vector<int>>(GetBoundMemorySubsystemBankQueueDepths()->begin(), GetBoundMemorySubsystemBankQueueDepths()->end());
			temp_var.ActiveMemoryRequests = GetBoundMemorySubsystemCurrentQueuedRequests();
			temp_var.MemorySubsystemCycle = GetBoundMemorySubsystemCurrentCycle();
			if (_fspScheduler) temp_var.ThreadReadyQueueDepths = std::make_shared<std::vector<int>>(std::initializer_list<int>{_fspScheduler->GetOutstandingMemoryCount(0), _fspScheduler->GetOutstandingMemoryCount(1), _fspScheduler->GetOutstandingMemoryCount(2), _fspScheduler->GetOutstandingMemoryCount(3)});
			temp_var.CurrentFSPPolicy = runtimePolicy;
			traceSink->RecordPhaseAwareState(temp_var, phaseContext, phaseMetrics, phaseContext.isActive() && invalidationReason == Core::ReplayPhaseInvalidationReason::None);
		}
	}

	inline std::wstring Processor::CPU_Core::GetTraceRuntimePolicyText(PipelineObservationSnapshot const observation, Core::ReplayPhaseContext phaseContext)
	{
		std::wstring basePolicy = phaseContext.isActive() ? L"ReplayAwarePhase1.DenseTimeline" : L"DeterministicFSP";
		Core::RuntimeClusterAdmissionPreparation admissionPreparation = observation.getAdmissionPreparation();
		Core::RuntimeClusterAdmissionCandidateView admissionCandidateView = observation.getAdmissionCandidateView();
		Core::RuntimeClusterAdmissionDecisionDraft admissionDecisionDraft = observation.getAdmissionDecisionDraft();
		Core::RuntimeClusterAdmissionHandoff admissionHandoff = observation.getAdmissionHandoff();
		Core::ClusterFallbackDiagnosticsSnapshot fallbackDiagnosticsSnapshot = admissionCandidateView.getFallbackDiagnosticsSnapshot();

		return std::format(L"{}|DecodeMode={}|AdmissionReady={}|PreparedScalarCount={}|ScalarPrepared=0x{:02X}|AuxReservations={}|FallbackDiagnosticsMask=0x{:02X}|FallbackReasonMask=0x{:02X}|SuggestsFallbackDiagnostics={}|DraftCandidate={}|DraftIssueWidth={}|ScalarCandidates=0x{:02X}|BlockedScalar=0x{:02X}|AuxCandidates=0x{:02X}|AuxReserved=0x{:02X}|RegisterHazards=0x{:02X}|OrderingHazards=0x{:02X}|DecisionKind={}|DecisionScalarMask=0x{:02X}|DecisionAuxMask=0x{:02X}|ProbeClusterPath={}|RetainsReferenceSequential={}|HandoffReady={}|LegalitySeed={}|ClusterSeed={}", basePolicy, static_cast<unsigned int>(admissionPreparation.getDecodeMode()), admissionPreparation.getShouldConsiderClusterAdmission(), admissionPreparation.getPreparedScalarCount(), admissionPreparation.getPreparedScalarMask(), admissionPreparation.getAuxiliaryReservationCount(), fallbackDiagnosticsSnapshot.getFallbackDiagnosticsMask(), static_cast<unsigned char>(admissionDecisionDraft.getFallbackReasonMask()), fallbackDiagnosticsSnapshot.getSuggestsFallbackDiagnostics(), admissionCandidateView.getHasDraftCandidate(), admissionCandidateView.getAdvisoryScalarIssueWidth(), admissionCandidateView.getScalarCandidateMask(), admissionCandidateView.getBlockedScalarCandidateMask(), admissionCandidateView.getAuxiliaryCandidateMask(), admissionCandidateView.getAuxiliaryReservationMask(), admissionCandidateView.getRegisterHazardMask(), admissionCandidateView.getOrderingHazardMask(), static_cast<unsigned int>(admissionDecisionDraft.getDecisionKind()), admissionDecisionDraft.getScalarIssueMask(), admissionDecisionDraft.getAuxiliaryReservationMask(), admissionDecisionDraft.getShouldProbeClusterPath(), admissionDecisionDraft.getRetainsReferenceSequentialPath(), admissionHandoff.isHandoffReady(), admissionHandoff.getCanSeedLegalityIntegration(), admissionHandoff.getCanSeedClusterIntegration());
	}

	unsigned long long Processor::CPU_Core::GetTraceSamplePC()
	{
		if (getRuntime()->getMemoryPipeline()->WriteBack.Valid)
		{
			return getRuntime()->getMemoryPipeline()->WriteBack.getPC();
		}
		if (getRuntime()->getMemoryPipeline()->Memory.Valid)
		{
			return getRuntime()->getMemoryPipeline()->Memory.getPC();
		}
		if (getRuntime()->getExecution()->Execute.Valid)
		{
			return getRuntime()->getExecution()->Execute.getPC();
		}
		if (getRuntime()->getDecode()->Decode.Valid)
		{
			return getRuntime()->getDecode()->Decode.PC;
		}
		if (getRuntime()->getFrontend()->Fetch.Valid)
		{
			return getRuntime()->getFrontend()->Fetch.PC;
		}
		return ReadActiveLivePc();
	}

