	std::shared_ptr<InvalidOperationException> Processor::CPU_Core::CreateUnsupportedDirectStreamCompatControlSurfaceException(unsigned int opCode)
	{
		const std::wstring opcodeText = std::format(L"0x{:X}", opCode);
		if (opCode == static_cast<unsigned int>(InstructionsEnum::STREAM_WAIT))
		{
			return std::make_shared<InvalidOperationException>(L"Stream-control opcode " + opcodeText + L" reached the test-only direct stream compat executor without the authoritative serializing-boundary retire/apply follow-through. " +
				L"Direct callers must decode it through the canonical stream-control surface and use ExecutionDispatcherV4.CaptureRetireWindowPublications(...) or the mainline retire path instead of relying on compat-side stream execution/no-op behavior.");
		}

		if (opCode == static_cast<unsigned int>(InstructionsEnum::STREAM_SETUP) ||
			opCode == static_cast<unsigned int>(InstructionsEnum::STREAM_START))
		{
			return std::make_shared<InvalidOperationException>(L"Stream-control opcode " + opcodeText + L" reached the test-only direct stream compat executor without an authoritative retire/apply contour. " +
				L"Direct callers must reject/defer STREAM_SETUP/STREAM_START on this compat surface until an explicit canonical retire/apply path lands instead of relying on compat-side stream execution/no-op behavior.");
		}

		return std::make_shared<InvalidOperationException>(L"Opcode " + opcodeText + L" reached the test-only direct stream compat executor without an authoritative stream compat contour.");
	}

	std::shared_ptr<InvalidOperationException> Processor::CPU_Core::CreateUnsupportedZeroLengthDirectStreamCompatSurfaceException(StreamExecutionRequest const request)
	{
		return std::make_shared<InvalidOperationException>(std::format(L"Stream opcode 0x{:X} reached the test-only direct stream compat executor as a zero-length helper request without an authoritative retire/apply contour. ", request.getOpCode()) + L"Direct callers must not rely on compat-side StreamEngine.Execute(...) no-op behavior for this contour; use the canonical mainline path or add an explicit direct compat follow-through before reopening it.");
	}

	std::shared_ptr<InvalidOperationException> Processor::CPU_Core::CreateUnsupportedScalarizedVectorDirectStreamCompatSurfaceException(StreamExecutionRequest const request)
	{
		return std::make_shared<InvalidOperationException>(std::format(L"Stream opcode 0x{:X} reached the test-only direct stream compat executor through streamLength == 1 / IsScalar with a vector opcode. ", request.getOpCode()) + L"This compat surface is authoritative only for scalar ALU direct-retire contours and dedicated scalar-result VPOPC; vector compute opcodes must use the canonical vector carrier path instead of synthesizing GPR retire truth from scalarized stream encoding.");
	}

