	void Processor::CPU_Core::TestPrepareExplicitPacketAtomicForWriteBack(unsigned char laneIndex, std::shared_ptr<YAKSys_Hybrid_CPU::Core::AtomicMicroOp> atomicMicroOp, unsigned long long pc, int vtId)
	{
		if (!atomicMicroOp) throw std::invalid_argument("atomicMicroOp");

		if (laneIndex < 4 || laneIndex > 5)
		{
			throw std::out_of_range("Explicit packet Atomic WB tests are restricted to retire-visible LSU lanes 4..5.");
		}

		auto& writeBack = getRuntime()->getMemoryPipeline()->WriteBack;
		writeBack.Clear();
		getRuntime()->getMemoryPipeline()->Memory.Clear();
		getRuntime()->getExecution()->Execute.Clear();
		getRuntime()->getDecode()->Decode.Clear();

		atomicMicroOp->setOwnerThreadId(vtId);
		atomicMicroOp->setVirtualThreadId(vtId);
		atomicMicroOp->setOwnerContextId(vtId);
		atomicMicroOp->RefreshWriteMetadata();

		if (!ExecuteTestAtomicWithStableCoreIdentity(atomicMicroOp))
		{
			throw InvalidOperationException(L"Explicit packet Atomic test helper could not resolve a retire effect.");
		}

		YAKSys_Hybrid_CPU::Core::AtomicRetireEffect atomicEffect = atomicMicroOp->CreateRetireEffect();
		if (!atomicEffect.isValid())
		{
			throw InvalidOperationException(L"Explicit packet Atomic test helper expected a valid resolved Atomic retire effect.");
		}

		ScalarWriteBackLaneState lane = ScalarWriteBackLaneState();
		lane.Clear(laneIndex);
		lane.IsOccupied = true;
		lane.PC = pc;
		lane.OpCode = atomicMicroOp->getOpCode();
		lane.IsMemoryOp = true;
		lane.WritesRegister = false;
		lane.DestRegID = atomicMicroOp->getDestRegID();
		lane.MicroOp = atomicMicroOp;
		lane.OwnerThreadId = vtId;
		lane.VirtualThreadId = vtId;
		lane.OwnerContextId = vtId;
		lane.ResultValue = 0;
		lane.GeneratedAtomicEffect.emplace(atomicEffect);
		lane.MemoryAddress = atomicEffect.getAddress();
		lane.MemoryData = atomicEffect.getSourceValue();
		lane.MemoryAccessSize = atomicEffect.getAccessSize();

		writeBack.SetLane(laneIndex, lane);
		writeBack.Valid = true;
		writeBack.ActiveLaneIndex = laneIndex;
		writeBack.UsesExplicitPacketLanes = true;
		writeBack.MaterializedPhysicalLaneCount = 1;
		writeBack.MaterializedScalarLaneCount = 0;
	}

