		ScalarExecuteLaneState lane = ScalarExecuteLaneState();
		lane.Clear(laneIndex);
		lane.IsOccupied = true;
		lane.PC = pc;
		lane.OpCode = microOp->getOpCode();
		lane.IsMemoryOp = microOp->isMemoryOp();
		lane.WritesRegister = microOp->getWritesRegister();
