	void Processor::CPU_Core::TestExecuteSingleLaneReferenceRawFallback(unsigned long long operand1, unsigned long long operand2)
	{
		getRuntime()->getTelemetry()->TestReferenceRawFallbackCount++;
		auto& decode = getRuntime()->getDecode()->Decode;
		auto& execute = getRuntime()->getExecution()->Execute;

		if (decode.IsVectorOp)
		{
			FailCloseSingleLaneExecuteAfterNonFaultException();
			throw InvalidOperationException(std::format(L"Vector opcode 0x{:X} reached reference raw execute fallback without an authoritative mainline MicroOp. ", decode.OpCode) + L"Mainline vector/stream execution must enter the explicit MicroOp-owned runtime contour; direct StreamEngine fallback from the reference raw execute path is no longer permitted.");
		}

		if (decode.IsMemoryOp)
		{
			FailCloseSingleLaneExecuteAfterNonFaultException();
			throw UnsupportedExecutionSurfaceException::CreateForMemory(decode.SlotIndex, decode.OpCode, decode.PC);
		}

		if (decode.IsBranchOp)
		{
			FailCloseSingleLaneExecuteAfterNonFaultException();
			throw UnsupportedExecutionSurfaceException::CreateForControlFlow(decode.SlotIndex, decode.OpCode, decode.PC);
		}

		if (!IsTestReferenceRawFallbackAllowed(decode.OpCode))
		{
			FailCloseSingleLaneExecuteAfterNonFaultException();
			throw InvalidOperationException(std::format(L"Opcode 0x{:X} is not in the test-only reference raw execute allow-list. ", decode.OpCode) + L"Production memory/control-flow surfaces must remain on the canonical MicroOp-owned runtime contour.");
		}

		execute.setResultValue(Core::ScalarAluOps::Compute(decode.OpCode, operand1, operand2, decode.Instruction.getImmediate()));
		execute.setResultReady(true);
		execute.Valid = true;
		PublishExecuteCompletionContourCertificate(Core::PipelineContourOwner::ReferenceExecution, Core::PipelineContourVisibilityStage::Execute, execute.getPC(), static_cast<unsigned char>(1 << execute.ActiveLaneIndex));
		ConsumeDecodeStateAfterExecuteDispatch();
		PublishSingleLaneExecuteForwarding(false);
	}

