	std::shared_ptr<VliwBundleAnnotations> Processor::CPU_Core::BuildFetchedBundleAnnotationsForTesting(std::vector<VLIW_Instruction> &rawSlots)
	{
		if (!rawSlots.data() && !rawSlots.empty()) throw std::invalid_argument("rawSlots must not be null.");

		int defaultOwnerVirtualThreadId = ReadActiveVirtualThreadId();
		std::vector<std::shared_ptr<InstructionSlotMetadata>> slotMetadata(Core::BundleSlotCount);
		bool hasExplicitOwner = false;

		for (int slotIndex = 0; slotIndex < slotMetadata.size(); slotIndex++)
		{
			unsigned char explicitOwnerVirtualThreadId = slotIndex < rawSlots.size() ? rawSlots[slotIndex].getVirtualThreadId() : static_cast<unsigned char>(0);
			int slotOwnerVirtualThreadId = explicitOwnerVirtualThreadId != 0 ? explicitOwnerVirtualThreadId : defaultOwnerVirtualThreadId;

			InstructionSlotMetadata metadata = *InstructionSlotMetadata::getDefault();
			metadata.VirtualThreadId = YAKSys_Hybrid_CPU::Core::Registers::VtId::Create(slotOwnerVirtualThreadId);
			slotMetadata[slotIndex] = std::make_shared<InstructionSlotMetadata>(std::move(metadata));
			hasExplicitOwner |= slotOwnerVirtualThreadId != 0;
		}

		return hasExplicitOwner ? std::make_shared<VliwBundleAnnotations>(slotMetadata) : VliwBundleAnnotations::getEmpty();
	}

