	inline void Processor::CPU_Core::ApplyControlFlowDominanceBeforeRedirect()
	{
		std::array<unsigned char, 4> controlFlowOrderStorage{};
		std::span<unsigned char> controlFlowOrder(controlFlowOrderStorage);
		auto& executeStage = getRuntime()->getExecution()->Execute;
		int controlFlowOrderCount = ResolveStableControlFlowOrder(executeStage, controlFlowOrder);
		if (controlFlowOrderCount == 0)
		{
			return;
		}

		executeStage.ActiveLaneIndex = controlFlowOrder[0];

		unsigned char dominatedMask = ResolveDominatedScalarLanesForControlFlow(executeStage);
		if (dominatedMask == 0)
		{
			return;
		}

		SuppressDominatedExecuteScalarLanes(dominatedMask);
	}

	inline void Processor::CPU_Core::ApplyPipelineControlFlowRedirect(unsigned long long targetPc, Core::AssistInvalidationReason assistInvalidationReason)
	{
		ApplyControlFlowDominanceBeforeRedirect();
		FlushPipeline(assistInvalidationReason);
		RedirectActiveExecutionForControlFlow(targetPc);
	}

	inline void Processor::CPU_Core::SuppressDominatedExecuteScalarLanes(unsigned char dominatedMask)
	{
		if ((dominatedMask & (1 << 0)) != 0)
		{
			ScalarExecuteLaneState clearedLane = ScalarExecuteLaneState();
			clearedLane.Clear(0);
			getRuntime()->getExecution()->Execute.SetLane(0, clearedLane);
		}

		if ((dominatedMask & (1 << 1)) != 0)
		{
			ScalarExecuteLaneState clearedLane = ScalarExecuteLaneState();
			clearedLane.Clear(1);
			getRuntime()->getExecution()->Execute.SetLane(1, clearedLane);
		}

		if ((dominatedMask & (1 << 2)) != 0)
		{
			ScalarExecuteLaneState clearedLane = ScalarExecuteLaneState();
			clearedLane.Clear(2);
			getRuntime()->getExecution()->Execute.SetLane(2, clearedLane);
		}

		if ((dominatedMask & (1 << 3)) != 0)
		{
			ScalarExecuteLaneState clearedLane = ScalarExecuteLaneState();
			clearedLane.Clear(3);
			getRuntime()->getExecution()->Execute.SetLane(3, clearedLane);
		}

		auto& executeStage = getRuntime()->getExecution()->Execute;
		executeStage.MaterializedScalarLaneCount = CountOccupiedScalarExecuteLanes(executeStage);
		executeStage.MaterializedPhysicalLaneCount = CountOccupiedPhysicalExecuteLanes(executeStage);
	}

	inline bool Processor::CPU_Core::IsControlFlowOpcode(unsigned int opCode)
	{
		return Arch::OpcodeRegistry::IsControlFlowOp(opCode);
	}

	inline Core::BranchExecutionPayload Processor::CPU_Core::ResolveBranchExecutionPayload(ScalarExecuteLaneState const branchLane, std::shared_ptr<Core::BranchMicroOp> branchOp)
	{
		int consumerThreadId = NormalizePipelineStateVtId(branchLane.OwnerThreadId);
		unsigned long long operand1 = 0;
		unsigned long long operand2 = 0;
		unsigned long long baseValue = 0;

		if (branchOp->isConditional())
		{
			operand1 = GetRegisterValueWithForwarding(consumerThreadId, branchOp->getReg1ID());
			operand2 = GetRegisterValueWithForwarding(consumerThreadId, branchOp->getReg2ID());
		}
		else if (branchLane.OpCode == IsaOpcodeValues::JALR)
		{
			baseValue = GetRegisterValueWithForwarding(consumerThreadId, branchOp->getReg1ID());
		}

// C# TO C++ CONVERTER TASK: There is no C++ equivalent to 'unchecked' in this context:
// ORIGINAL LINE: return branchOp.ResolveExecutionPayload(unchecked((ushort)branchLane.OpCode), branchLane.PC, operand1, operand2, baseValue);
		return branchOp->ResolveExecutionPayload(static_cast<unsigned short>(branchLane.OpCode), branchLane.PC, operand1, operand2, baseValue);
	}

	inline void Processor::CPU_Core::MaterializeBranchExecuteCarrier(ScalarExecuteLaneState &branchLane, Core::BranchExecutionPayload const branchPayload)
	{
		branchLane.IsMemoryOp = false;
		branchLane.IsLoad = false;
		branchLane.MemoryAccessSize = 0;
		branchLane.MemoryAddress = 0;
		branchLane.MemoryData = 0;
		branchLane.GeneratedEvent = std::nullopt;
		branchLane.GeneratedCsrEffect = std::nullopt;
		branchLane.GeneratedAtomicEffect = std::nullopt;
		branchLane.GeneratedVmxEffect = std::nullopt;
		branchLane.GeneratedRetireRecordCount = 0;
		branchLane.VectorComplete = true;
		branchLane.ResultReady = true;
		branchLane.ResultValue = branchPayload.getMaterializedResultValue();
	}

	inline bool Processor::CPU_Core::TryExecuteScalarBranchMicroOp()
	{
		unsigned char laneIndex = getRuntime()->getExecution()->Execute.ActiveLaneIndex;
		ScalarExecuteLaneState branchLane = getRuntime()->getExecution()->Execute.GetLane(laneIndex);
		std::shared_ptr<Core::BranchMicroOp> branchOp = std::dynamic_pointer_cast<Core::BranchMicroOp>(branchLane.MicroOp);
		if (!branchLane.IsOccupied || branchOp == nullptr)
		{
			return false;
		}

		Core::BranchExecutionPayload branchPayload = ResolveBranchExecutionPayload(branchLane, branchOp);
		if (!branchPayload.isExecutable())
		{
			return false;
		}

		MaterializeBranchExecuteCarrier(branchLane, branchPayload);
		getRuntime()->getExecution()->Execute.SetLane(laneIndex, branchLane);
		getRuntime()->getExecution()->Execute.Valid = true;
		PublishExecuteCompletionContourCertificate(Core::PipelineContourOwner::SingleLaneMicroOpExecution, Core::PipelineContourVisibilityStage::Execute, branchLane.PC, static_cast<unsigned char>(1 << laneIndex));
		ConsumeDecodeStateAfterExecuteDispatch();
		PublishSingleLaneExecuteForwarding(true);
		return true;
	}

	inline bool Processor::CPU_Core::TryExecuteExplicitPacketLane7Branch(unsigned char laneIndex, ScalarExecuteLaneState &branchLane, int &executedPhysicalLaneCount)
	{
		std::shared_ptr<Core::BranchMicroOp> branchOp = std::dynamic_pointer_cast<Core::BranchMicroOp>(branchLane.MicroOp);
		if (laneIndex != 7 || !branchLane.IsOccupied || branchOp == nullptr)
		{
			return false;
		}

		getRuntime()->getExecution()->Execute.ActiveLaneIndex = 7;

		Core::BranchExecutionPayload branchPayload = ResolveBranchExecutionPayload(branchLane, branchOp);
		if (!branchPayload.isExecutable())
		{
			return false;
		}

		MaterializeBranchExecuteCarrier(branchLane, branchPayload);
		getRuntime()->getExecution()->Execute.SetLane(laneIndex, branchLane);
		executedPhysicalLaneCount++;

		RecordExecuteLaneTraceEvent(laneIndex, branchLane);
		if (branchOp->isConditional())
		{
			RecordLane7ConditionalBranchCompletion(branchPayload.getRedirectsControlFlow());
		}

		return true;
	}

	inline bool Processor::CPU_Core::IsForwardingRegisterMatch(bool isOccupied, bool writesRegister, unsigned short destRegId, int producerThreadId, int consumerThreadId, unsigned short regID)
	{
		return isOccupied && writesRegister && destRegId != 0 && destRegId == regID && producerThreadId == consumerThreadId;
	}

	inline bool Processor::CPU_Core::IsHiddenForwardingRegisterMatch(bool isOccupied, std::shared_ptr<Core::MicroOp> microOp, unsigned short primaryDestRegId, int producerThreadId, int consumerThreadId, unsigned short regID)
	{
		if (!isOccupied || microOp == nullptr || producerThreadId != consumerThreadId || regID == 0)
		{
			return false;
		}

// C# TO C++ CONVERTER WARNING: C++ has no equivalent to a 'readonly' collection which allows modification of internal state:
// ORIGINAL LINE: IReadOnlyList<int> writeRegisters = microOp.WriteRegisters;
		const std::vector<int> writeRegisters = microOp->getWriteRegisters();
		for (int i = 0; i < writeRegisters.size(); i++)
		{
			int writeReg = writeRegisters[i];
			if (writeReg <= 0 || writeReg > std::numeric_limits<unsigned short>::max())
			{
				continue;
			}

			unsigned short writeRegId = static_cast<unsigned short>(writeReg);
			if (writeRegId == primaryDestRegId)
			{
				continue;
			}

			if (writeRegId == regID)
			{
				return true;
			}
		}

		return false;
	}

	inline bool Processor::CPU_Core::TryResolveLaneAwareProducerMatch(ScalarExecuteLaneState lane, int consumerThreadId, unsigned short regID, LaneAwareForwardingMatch &match)
	{
		if (IsForwardingRegisterMatch(lane.IsOccupied, lane.WritesRegister, lane.DestRegID, lane.OwnerThreadId, consumerThreadId, regID))
		{
			match = {.ResultReady = lane.ResultReady, .DestRegID = lane.DestRegID, .ResultValue = lane.ResultValue, .SourceStage = PipelineStage::Execute, .SourceLaneIndex = lane.LaneIndex};
			return true;
		}

		match = YAKSys_Hybrid_CPU::Processor::CPU_Core::LaneAwareForwardingMatch();
		return false;
	}

