	inline bool Processor::CPU_Core::IsLaneAwareForwardingReady(int consumerThreadId, unsigned short regID)
	{
		if (regID == 0)
		{
			return true;
		}

		LaneAwareForwardingMatch match;
		if (TryResolveLaneAwareProducerMatch(consumerThreadId, regID, match))
		{
			return match.ResultReady;
		}

		long long currentCycle = static_cast<long long>(pipeCtrl.getCycleCount());

		if (getRuntime()->getExecution()->ExecuteForwarding.Valid && getRuntime()->getExecution()->ExecuteForwarding.DestRegID == regID)
		{
			return getRuntime()->getExecution()->ExecuteForwarding.IsAvailable(currentCycle);
		}

		if (getRuntime()->getExecution()->MemoryForwarding.Valid && getRuntime()->getExecution()->MemoryForwarding.DestRegID == regID)
		{
			return getRuntime()->getExecution()->MemoryForwarding.IsAvailable(currentCycle);
		}

		if (getRuntime()->getExecution()->WriteBackForwarding.Valid && getRuntime()->getExecution()->WriteBackForwarding.DestRegID == regID)
		{
			return getRuntime()->getExecution()->WriteBackForwarding.IsAvailable(currentCycle);
		}

		return true;
	}

	inline unsigned long long Processor::CPU_Core::GetRegisterValueWithForwarding(int consumerThreadId, unsigned short regID)
	{
		if (regID == 0 || regID >= YAKSys_Hybrid_CPU::Core::Registers::RenameMap::ArchRegs)
		{
			return 0;
		}

		LaneAwareForwardingMatch laneAwareMatch;
		if (TryResolveLaneAwareProducerMatch(consumerThreadId, regID, laneAwareMatch))
		{
			if (laneAwareMatch.ResultReady)
			{
				pipeCtrl.setForwardingEvents(pipeCtrl.getForwardingEvents() + 1);
				return laneAwareMatch.ResultValue;
			}

			throw InvalidOperationException(std::format(L"Register x{0} for VT{1} was consumed while its lane-aware producer remained not-ready. ", regID, consumerThreadId) + std::format(L"Producer stage={0}, lane={1}, ", static_cast<unsigned char>(laneAwareMatch.SourceStage), laneAwareMatch.SourceLaneIndex) + std::format(L"value=0x{0:0>16x}. ", laneAwareMatch.ResultValue) + L"The pipeline must interlock this consumer instead of exposing stale architectural state.");
		}

		long long currentCycle = static_cast<long long>(pipeCtrl.getCycleCount());

		if (getRuntime()->getExecution()->ExecuteForwarding.Valid && getRuntime()->getExecution()->ExecuteForwarding.DestRegID == regID && getRuntime()->getExecution()->ExecuteForwarding.IsAvailable(currentCycle))
		{
			pipeCtrl.setForwardingEvents(pipeCtrl.getForwardingEvents() + 1);
			return getRuntime()->getExecution()->ExecuteForwarding.ForwardedValue;
		}

		if (getRuntime()->getExecution()->MemoryForwarding.Valid && getRuntime()->getExecution()->MemoryForwarding.DestRegID == regID && getRuntime()->getExecution()->MemoryForwarding.IsAvailable(currentCycle))
		{
			pipeCtrl.setForwardingEvents(pipeCtrl.getForwardingEvents() + 1);
			return getRuntime()->getExecution()->MemoryForwarding.ForwardedValue;
		}

		if (getRuntime()->getExecution()->WriteBackForwarding.Valid && getRuntime()->getExecution()->WriteBackForwarding.DestRegID == regID && getRuntime()->getExecution()->WriteBackForwarding.IsAvailable(currentCycle))
		{
			pipeCtrl.setForwardingEvents(pipeCtrl.getForwardingEvents() + 1);
			return getRuntime()->getExecution()->WriteBackForwarding.ForwardedValue;
		}

		// With no live producer, a self-destination consumer may already own a new
		// rename mapping whose physical value is not initialized yet. Its source
		// operand is the last committed architectural version, not that destination.
		return ReadCommittedArch(consumerThreadId, regID);
	}

	inline unsigned long long Processor::CPU_Core::GetRegisterValueWithForwardingExcludingExecuteLane(int consumerThreadId, unsigned short regID, unsigned char consumerLaneIndex)
	{
		if (regID == 0 || regID >= YAKSys_Hybrid_CPU::Core::Registers::RenameMap::ArchRegs)
		{
			return 0;
		}

		LaneAwareForwardingMatch match;
		for (unsigned char laneIndex = 0; laneIndex < 8; laneIndex++)
		{
			if (laneIndex == consumerLaneIndex)
			{
				continue;
			}
			if (getRuntime()->getExecution()->Execute.Valid && TryResolveLaneAwareProducerMatch(getRuntime()->getExecution()->Execute.GetLane(laneIndex), consumerThreadId, regID, match))
			{
				if (!match.ResultReady)
				{
					throw InvalidOperationException(std::format(L"Register x{0} for VT{1} depends on not-ready EX lane {2}.", regID, consumerThreadId, laneIndex));
				}
				return match.ResultValue;
			}
		}

		for (unsigned char laneIndex = 0; laneIndex < 8; laneIndex++)
		{
			if (getRuntime()->getMemoryPipeline()->Memory.Valid && TryResolveLaneAwareProducerMatch(getRuntime()->getMemoryPipeline()->Memory.GetLane(laneIndex), consumerThreadId, regID, match))
			{
				if (!match.ResultReady)
				{
					throw InvalidOperationException(std::format(L"Register x{0} for VT{1} depends on not-ready MEM lane {2}.", regID, consumerThreadId, laneIndex));
				}
				return match.ResultValue;
			}
			if (getRuntime()->getMemoryPipeline()->WriteBack.Valid && TryResolveLaneAwareProducerMatch(getRuntime()->getMemoryPipeline()->WriteBack.GetLane(laneIndex), consumerThreadId, regID, match))
			{
				return match.ResultValue;
			}
		}

		return ReadCommittedArch(consumerThreadId, regID);
	}

	inline bool Processor::CPU_Core::CheckForwardingReadiness(unsigned short reg2ID, unsigned short reg3ID)
	{
		int consumerThreadId = GetCurrentDecodeThreadId();
		return IsLaneAwareForwardingReady(consumerThreadId, reg2ID) && IsLaneAwareForwardingReady(consumerThreadId, reg3ID);
	}

	std::shared_ptr<CpuInstructionTranslationResult> Processor::CPU_Core::TranslateScalarInstructionMemoryAddress(std::shared_ptr<Core::LoadStoreMicroOp> operation, CpuInstructionTranslationAccessKind accessKind, unsigned char accessSize)
	{
		if (operation == nullptr)
		{
			throw std::invalid_argument("operation");
		}
// C# TO C++ CONVERTER TASK: The following 'is' operator pattern is not converted by C# to C++ Converter:
		if ((accessKind != CpuInstructionTranslationAccessKind::ScalarLoad && accessKind != CpuInstructionTranslationAccessKind::ScalarStore))
		{
			throw ArgumentOutOfRangeException(L"accessKind");
		}

		std::shared_ptr<CpuInstructionTranslationOperationIdentity> identity;
		std::shared_ptr<Core::PostStageBIssuedAttempt> issuedAttempt = std::dynamic_pointer_cast<Core::PostStageBIssuedAttempt>(operation->getPostStageBIssuedAttempt());
		if (issuedAttempt != nullptr)
		{
			std::shared_ptr<Core::Decoder::VliwOperationId> operationId = issuedAttempt->getScheduledOperation()->getOperationId();
			unsigned long long eventId = Core::ArchitecturalCompletionEventIdentity::Create(operationId->WorkingBundleSequence, operationId->WorkingSlotIndex);
			identity = std::make_shared<CpuInstructionTranslationOperationIdentity>(operationId->OperationAttempt, eventId, CpuInstructionTranslationOwner::CreateMemoryOperationIdentity(operationId->OperationAttempt, eventId, accessKind, operation->getMemoryAddress()));
		}
		else
		{
			identity = getCpuInstructionTranslationOwner()->IssueFallbackMemoryIdentity(accessKind, operation->getMemoryAddress());
		}

		std::shared_ptr<CpuInstructionTranslationScope> scope = std::make_shared<CpuInstructionTranslationScope>(operation->getPlacement().DomainTag, operation->getOwnerContextId(), operation->getVirtualThreadId());
		std::shared_ptr<CpuInstructionTranslationRequest> request = std::make_shared<CpuInstructionTranslationRequest>(CpuInstructionTranslationRequest{*scope, accessKind, operation->getMemoryAddress(), static_cast<unsigned short>(accessSize == 0 ? 8 : accessSize), *identity});
		auto result = getCpuInstructionTranslationOwner()->Translate(request);
		auto binding = getCpuInstructionTranslationOwner()->BindPhysicalRead(request, result, (GetBoundMemorySubsystem() == nullptr ? nullptr : GetBoundMemorySubsystem()->getCycleController()));
		if (binding != nullptr)
		{
			operation->BindCpuPhysicalRead(binding);
		}
		return result;
	}

	inline std::shared_ptr<CpuInstructionTranslationResult> Processor::CPU_Core::TranslateInstructionFetch(unsigned long long virtualAddress)
	{
		std::shared_ptr<CpuInstructionTranslationScope> scope = getCpuInstructionTranslationOwner()->isIdentity() ? std::make_shared<CpuInstructionTranslationScope>(0, 0, ReadActiveVirtualThreadId()) : getCpuInstructionTranslationOwner()->getConfiguredScope();
		auto fetchIdentity = getCpuInstructionTranslationOwner()->IssueFetchIdentity(virtualAddress);
		std::shared_ptr<CpuInstructionTranslationRequest> request = std::make_shared<CpuInstructionTranslationRequest>(CpuInstructionTranslationRequest{*scope, CpuInstructionTranslationAccessKind::InstructionFetch, virtualAddress, 256, *fetchIdentity});
		if (_shadowFrontendMode != ShadowFrontendMode::Off)
		{
			_shadowFetchTranslationRequest = request;
		}
		return getCpuInstructionTranslationOwner()->Translate(request);
	}

	void Processor::CPU_Core::CommitCpuInstructionTranslationFault(std::shared_ptr<CpuInstructionTranslationFault> fault)
	{
		const CpuInstructionTranslationRequest& request = fault->Request;
		bool secondStage = fault->FaultStage == CpuInstructionTranslationFaultStage::SecondStage;
		std::shared_ptr<ArchitecturalCompletionCandidate> candidate = std::make_shared<Core::ArchitecturalCompletionCandidate>(request.Scope.DomainId, request.Scope.ContextId, request.Scope.VirtualThreadId, request.OperationIdentity.AttemptId, request.OperationIdentity.EventId, Core::NeutralArchitecturalCompletionFacts(Core::NeutralArchitecturalCompletionClass::TranslationFault, Core::NeutralScalarFact::Present(static_cast<unsigned long long>(static_cast<unsigned char>(fault->Reason))), Core::NeutralScalarFact::Present(fault->Qualification), Core::NeutralAddressFact::Present(secondStage ? fault->GuestPhysicalAddress : request.VirtualAddress, secondStage ? Core::NeutralFaultAddressSemantic::GuestPhysicalAddress : Core::NeutralFaultAddressSemantic::VirtualAddress), Core::NeutralAuxiliaryFact::Present(fault->Auxiliary, secondStage ? Core::NeutralFaultAuxiliarySemantic::SecondStageTranslationViolation : Core::NeutralFaultAuxiliarySemantic::TranslationFault)), Core::NeutralTranslationProvenance::Present(request.OperationIdentity.MemoryOperationId, fault->OwnerEpoch, fault->MemoryDomainOwnerEpoch, fault->AddressSpaceGeneration, fault->AddressSpaceIdentity));

		std::shared_ptr<Core::ArchitecturalCompletionCommitResult> result = getArchitecturalCompletionCommitOwner()->CommitAtCanonicalPreciseFaultBoundary(secondStage ? getCanonicalCpuSecondStageTranslationFaultCompletionProducer() : getCanonicalCpuTranslationFaultCompletionProducer(), candidate);
		if (result->Decision != Core::ArchitecturalCompletionCommitDecision::Committed)
		{
			throw InvalidOperationException(std::format(L"Mandatory CPU translation-fault completion commit was denied: {0}: {1}", static_cast<unsigned char>(result->Decision), result->Reason));
		}
	}

	void Processor::CPU_Core::DeliverCommittedCpuInstructionTranslationFault(std::shared_ptr<CpuInstructionTranslationFault> fault)
	{
		if (fault->Reason == CpuInstructionTranslationFaultReason::SecondStageSourceStale)
		{
			getRuntime()->getCpuInstructionTranslation()->PendingFetchFault = std::nullopt;
			FlushPipeline(Core::AssistInvalidationReason::Replay);
			throw CpuInstructionTranslationSourceStaleException(fault);
		}
		CommitCpuInstructionTranslationFault(fault);
		getRuntime()->getCpuInstructionTranslation()->PendingFetchFault = std::nullopt;
		FlushPipeline(Core::AssistInvalidationReason::Trap);
		throw CpuInstructionTranslationFaultException(fault);
	}

	void Processor::CPU_Core::MarkActiveExecuteLaneCpuTranslationFault(std::shared_ptr<CpuInstructionTranslationFault> fault)
	{
		if (getRuntime()->getExecution()->Execute.ActiveLaneIndex >= 8)
		{
			throw InvalidOperationException(L"Execute-stage CPU translation fault requires a live lane.");
		}

		ScalarExecuteLaneState lane = getRuntime()->getExecution()->Execute.GetLane(getRuntime()->getExecution()->Execute.ActiveLaneIndex);
		if (!lane.IsOccupied)
		{
			throw InvalidOperationException(L"Execute-stage CPU translation fault cannot attach to an empty lane.");
		}
		lane.HasFault = true;
		lane.FaultAddress = fault->Request.VirtualAddress;
		lane.FaultIsWrite = fault->Request.AccessKind == CpuInstructionTranslationAccessKind::ScalarStore;
		lane.CpuTranslationFault = fault;
		getRuntime()->getExecution()->Execute.SetLane(getRuntime()->getExecution()->Execute.ActiveLaneIndex, lane);
	}

	void Processor::CPU_Core::MarkActiveMemoryLaneCpuTranslationFault(std::shared_ptr<CpuInstructionTranslationFault> fault)
	{
		if (getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex >= 8)
		{
			throw InvalidOperationException(L"Memory-stage CPU translation fault requires a live lane.");
		}

		ScalarMemoryLaneState lane = getRuntime()->getMemoryPipeline()->Memory.GetLane(getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex);
		if (!lane.IsOccupied)
		{
			throw InvalidOperationException(L"Memory-stage CPU translation fault cannot attach to an empty lane.");
		}
		lane.HasFault = true;
		lane.FaultAddress = fault->Request.VirtualAddress;
		lane.FaultIsWrite = fault->Request.AccessKind == CpuInstructionTranslationAccessKind::ScalarStore;
		lane.CpuTranslationFault = fault;
		getRuntime()->getMemoryPipeline()->Memory.SetLane(getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex, lane);
	}

	void Processor::CPU_Core::DeliverStageAwareExecuteCpuTranslationFault(std::shared_ptr<CpuInstructionTranslationFault> fault)
	{
		MarkActiveExecuteLaneCpuTranslationFault(fault);
		DeliverStageAwareCpuTranslationWinner();
	}

	void Processor::CPU_Core::DeliverStageAwareMemoryCpuTranslationFault(std::shared_ptr<CpuInstructionTranslationFault> fault)
	{
		MarkActiveMemoryLaneCpuTranslationFault(fault);
		DeliverStageAwareCpuTranslationWinner();
	}

	void Processor::CPU_Core::DeliverStageAwareCpuTranslationWinner()
	{
		StageAwareExceptionWinnerMetadata winner;
		if (!TryResolveStageAwareExceptionWinnerMetadata(getRuntime()->getMemoryPipeline()->WriteBack, getRuntime()->getMemoryPipeline()->Memory, getRuntime()->getExecution()->Execute, winner))
		{
			throw InvalidOperationException(L"CPU translation fault delivery requires a stage-aware winner.");
		}

		auto translationFault = winner.getCpuTranslationFault();
		if (translationFault.has_value() && *translationFault != nullptr)
		{
			DeliverCommittedCpuInstructionTranslationFault(*translationFault);
			return;
		}

		FlushPipeline(Core::AssistInvalidationReason::Trap);
		throw Core::PageFaultException(winner.getFaultAddress(), winner.getFaultIsWrite());
	}

	bool Processor::CPU_Core::TryDeliverPendingCpuFetchTranslationFault()
	{
		auto pendingFault = getRuntime()->getCpuInstructionTranslation()->PendingFetchFault;
		if (!pendingFault.has_value() || *pendingFault == nullptr)
		{
			return false;
		}

		if (getRuntime()->getDecode()->Decode.Valid || getRuntime()->getExecution()->Execute.Valid || getRuntime()->getMemoryPipeline()->Memory.Valid || getRuntime()->getMemoryPipeline()->WriteBack.Valid)
		{
			return true;
		}

		DeliverCommittedCpuInstructionTranslationFault(*pendingFault);
		return true;
	}

	void Processor::CPU_Core::ClearPendingCpuFetchTranslationFault()
	{
		getRuntime()->getCpuInstructionTranslation()->PendingFetchFault = std::nullopt;
	}

	inline Processor::CPU_Core::ScalarExceptionOrderingDecision Processor::CPU_Core::ResolveDecodeExceptionOrderingDecision(Core::DecodedBundleSlotDescriptor const slotDescriptor, unsigned long long faultingPc)
	{
		unsigned long long domainTag = slotDescriptor.GetRuntimeAdmissionDomainTag();
		int virtualThreadId = slotDescriptor.GetRuntimeExecutionVirtualThreadId();

		if (domainTag == 0 || getCsrMemDomainCert() == 0)
		{
			return ScalarExceptionOrderingDecision::None();
		}

		if ((domainTag & getCsrMemDomainCert()) != 0)
		{
			return ScalarExceptionOrderingDecision::None();
		}

		if (slotDescriptor.GetRuntimeExecutionIsFspInjected())
		{
			return ScalarExceptionOrderingDecision::SilentSpeculativeDomainSquash(virtualThreadId, faultingPc, domainTag, getCsrMemDomainCert());
		}

		return ScalarExceptionOrderingDecision::PreciseDomainFault(virtualThreadId, faultingPc, domainTag, getCsrMemDomainCert());
	}

	inline std::shared_ptr<Core::NopMicroOp> Processor::CPU_Core::CreateSilentSpeculativeSquashReplacement(unsigned int opCode)
	{
		std::shared_ptr<Core::NopMicroOp> temp_var = std::make_shared<Core::NopMicroOp>();
		temp_var->setStealable(false);
		temp_var->setOpCode(opCode);
		return temp_var;
	}

	inline std::shared_ptr<Core::DomainFaultException> Processor::CPU_Core::CreatePreciseDecodeException(Processor::CPU_Core::ScalarExceptionOrderingDecision decision)
	{
		if (!decision.isPreciseArchitecturalFault())
		{
			throw InvalidOperationException(L"Precise decode exception requested for a non-precise exception decision.");
		}

		return std::make_shared<Core::DomainFaultException>(decision.getVirtualThreadId(), decision.getFaultingPC(), decision.getOperationDomainTag(), decision.getActiveCert());
	}

	inline void Processor::CPU_Core::DeliverStageAwareExecutePageFault(std::shared_ptr<Core::PageFaultException> pageFaultException)
	{
		MarkActiveExecuteLanePageFault(pageFaultException);

		StageAwareExceptionWinnerMetadata winnerMetadata;
		if (!TryResolveStageAwareExceptionWinnerMetadata(getRuntime()->getMemoryPipeline()->WriteBack, getRuntime()->getMemoryPipeline()->Memory, getRuntime()->getExecution()->Execute, winnerMetadata))
		{
			throw InvalidOperationException(L"Stage-aware execute page fault delivery requires at least one materialized fault carrier.");
		}

		if (CanDeliverOlderStageFault(winnerMetadata.getWinnerStage()))
		{
			if (ShouldSuppressYoungerWorkForExceptionWinner(winnerMetadata.getWinnerStage(), getRuntime()->getMemoryPipeline()->WriteBack, getRuntime()->getMemoryPipeline()->Memory, getRuntime()->getExecution()->Execute))
			{
				pipeCtrl.setExceptionYoungerSuppressCount(pipeCtrl.getExceptionYoungerSuppressCount() + 1);
			}

			std::shared_ptr<Core::PageFaultException> olderStageFault = std::make_shared<Core::PageFaultException>(winnerMetadata.getFaultAddress(), winnerMetadata.getFaultIsWrite());

			FlushPipeline(Core::AssistInvalidationReason::Trap);
			throw *olderStageFault;
		}

		if (winnerMetadata.getWinnerLaneIndex() >= 8)
		{
			throw InvalidOperationException(L"Stage-aware exception ordering selected an invalid live execute lane index.");
		}

		getRuntime()->getExecution()->Execute.ActiveLaneIndex = winnerMetadata.getWinnerLaneIndex();

		FlushPipeline(Core::AssistInvalidationReason::Trap);
		throw *pageFaultException;
	}

	inline void Processor::CPU_Core::RethrowExplicitPacketExecutePageFault(std::shared_ptr<Core::PageFaultException> pageFaultException)
	{
		std::shared_ptr<Core::Execution::ExecutionOutcome> outcome = ProjectExplicitPacketPageFaultOutcome(pageFaultException);
		DeliverExplicitPacketPageFaultOutcome(outcome, pageFaultException);
	}

