	inline void Processor::CPU_Core::MarkActiveExecuteLanePageFault(std::shared_ptr<Core::PageFaultException> pageFaultException)
	{
		if (getRuntime()->getExecution()->Execute.ActiveLaneIndex >= 8)
		{
			throw InvalidOperationException(L"Execute-stage page fault requires a valid active materialized lane index.");
		}

		ScalarExecuteLaneState lane = getRuntime()->getExecution()->Execute.GetLane(getRuntime()->getExecution()->Execute.ActiveLaneIndex);
		if (!lane.IsOccupied)
		{
			throw InvalidOperationException(L"Execute-stage page fault requires an occupied materialized lane.");
		}

		lane.HasFault = true;
		lane.FaultAddress = pageFaultException->getFaultAddress();
		lane.FaultIsWrite = pageFaultException->isWrite();
		getRuntime()->getExecution()->Execute.SetLane(getRuntime()->getExecution()->Execute.ActiveLaneIndex, lane);
	}

	inline void Processor::CPU_Core::MarkActiveMemoryLanePageFault(std::shared_ptr<Core::PageFaultException> pageFaultException)
	{
		if (getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex >= 8)
		{
			throw InvalidOperationException(L"Memory-stage page fault requires a valid active materialized lane index.");
		}

		ScalarMemoryLaneState lane = getRuntime()->getMemoryPipeline()->Memory.GetLane(getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex);
		if (!lane.IsOccupied)
		{
			throw InvalidOperationException(L"Memory-stage page fault requires an occupied materialized lane.");
		}

		lane.HasFault = true;
		lane.FaultAddress = pageFaultException->getFaultAddress();
		lane.FaultIsWrite = pageFaultException->isWrite();
		getRuntime()->getMemoryPipeline()->Memory.SetLane(getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex, lane);
	}

	inline void Processor::CPU_Core::DeliverStageAwareMemoryPageFault(std::shared_ptr<Core::PageFaultException> pageFaultException)
	{
		MarkActiveMemoryLanePageFault(pageFaultException);

		StageAwareExceptionWinnerMetadata winnerMetadata;
		if (!TryResolveStageAwareExceptionWinnerMetadata(getRuntime()->getMemoryPipeline()->WriteBack, getRuntime()->getMemoryPipeline()->Memory, getRuntime()->getExecution()->Execute, winnerMetadata))
		{
			throw InvalidOperationException(L"Stage-aware memory page fault delivery requires at least one materialized fault carrier.");
		}

		if (winnerMetadata.getWinnerStage() == PipelineStage::WriteBack)
		{
			if (ShouldSuppressYoungerWorkForExceptionWinner(winnerMetadata.getWinnerStage(), getRuntime()->getMemoryPipeline()->WriteBack, getRuntime()->getMemoryPipeline()->Memory, getRuntime()->getExecution()->Execute))
			{
				pipeCtrl.setExceptionYoungerSuppressCount(pipeCtrl.getExceptionYoungerSuppressCount() + 1);
			}

			std::shared_ptr<Core::PageFaultException> olderStageFault = std::make_shared<Core::PageFaultException>(winnerMetadata.getFaultAddress(), winnerMetadata.getFaultIsWrite());

			FlushPipeline(Core::AssistInvalidationReason::Trap);
			throw *olderStageFault;
		}

		if (winnerMetadata.getWinnerStage() != PipelineStage::Memory)
		{
			throw InvalidOperationException(L"Stage-aware memory page fault delivery selected an invalid winner stage.");
		}

		getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex = winnerMetadata.getWinnerLaneIndex();

		FlushPipeline(Core::AssistInvalidationReason::Trap);
		throw *pageFaultException;
	}

	inline int Processor::CPU_Core::TruncateRetireOrderBeforeWriteBackFaultWinner(WriteBackStage const writeBackStage, std::span<unsigned char> retireOrder, int retireLaneCount, PipelineStage winnerStage, unsigned char winnerLaneIndex)
	{
		if (winnerStage != PipelineStage::WriteBack || !IsRetireAuthoritativeWriteBackLane(winnerLaneIndex))
		{
			return retireLaneCount;
		}

		int truncatedCount = 0;
		for (int i = 0; i < retireLaneCount; i++)
		{
			unsigned char laneIndex = retireOrder[i];
			if (CompareWriteBackLaneOrder(writeBackStage, laneIndex, winnerLaneIndex) >= 0)
			{
				continue;
			}

			retireOrder[truncatedCount++] = laneIndex;
		}

		return truncatedCount;
	}

	inline unsigned char Processor::CPU_Core::ResolveSuppressedYoungerWriteBackPeerMask(WriteBackStage const writeBackStage, unsigned char winnerLaneIndex)
	{
		if (!IsRetireAuthoritativeWriteBackLane(winnerLaneIndex))
		{
			return 0;
		}

		unsigned char occupiedMask = GetOccupiedRetireEligibleWriteBackLaneMask(writeBackStage);
		unsigned char suppressedMask = 0;

		for (unsigned char laneIndex = 0; laneIndex < 8; laneIndex++)
		{
			if (!IsRetireAuthoritativeWriteBackLane(laneIndex))
			{
				continue;
			}

			if ((occupiedMask & (1 << laneIndex)) == 0)
			{
				continue;
			}

			if (CompareWriteBackLaneOrder(writeBackStage, winnerLaneIndex, laneIndex) >= 0)
			{
				continue;
			}

			suppressedMask |= static_cast<unsigned char>(1 << laneIndex);
		}

		return suppressedMask;
	}

	inline void Processor::CPU_Core::ClearRetiredWriteBackLaneStateBeforeFaultDelivery(std::span<unsigned char> retireOrder, int retireLaneCount)
	{
		for (int i = 0; i < retireLaneCount; i++)
		{
			unsigned char laneIndex = retireOrder[i];
			if (!IsRetireAuthoritativeWriteBackLane(laneIndex))
			{
				continue;
			}

			ScalarWriteBackLaneState clearedLane = ScalarWriteBackLaneState();
			clearedLane.Clear(laneIndex);
			getRuntime()->getMemoryPipeline()->WriteBack.SetLane(laneIndex, clearedLane);
		}

		getRuntime()->getExecution()->WriteBackForwarding.Clear();
	}

	inline void Processor::CPU_Core::DeliverStageAwareRetireWindowFault(PipelineStage winnerStage, unsigned char winnerLaneIndex, bool shouldSuppressYoungerWork)
	{
		StageAwareExceptionWinnerMetadata winnerMetadata;
		if (!TryResolveStageAwareExceptionWinnerMetadata(getRuntime()->getMemoryPipeline()->WriteBack, getRuntime()->getMemoryPipeline()->Memory, getRuntime()->getExecution()->Execute, winnerMetadata))
		{
			throw InvalidOperationException(L"WB retire-window fault delivery requires an authoritative stage-aware winner.");
		}

		unsigned char suppressedYoungerStageMask = ResolveExceptionWinnerSuppressedLaneMask(winnerStage, getRuntime()->getMemoryPipeline()->Memory, getRuntime()->getExecution()->Execute);
		unsigned char suppressedYoungerWriteBackPeerMask = winnerStage == PipelineStage::WriteBack ? ResolveSuppressedYoungerWriteBackPeerMask(getRuntime()->getMemoryPipeline()->WriteBack, winnerLaneIndex) : static_cast<unsigned char>(0);

		if (shouldSuppressYoungerWork || suppressedYoungerStageMask != 0 || suppressedYoungerWriteBackPeerMask != 0)
		{
			pipeCtrl.setExceptionYoungerSuppressCount(pipeCtrl.getExceptionYoungerSuppressCount() + 1);
		}

		FlushPipeline(Core::AssistInvalidationReason::Trap);
		throw Core::PageFaultException(winnerMetadata.getFaultAddress(), winnerMetadata.getFaultIsWrite());
	}

