	inline bool Processor::CPU_Core::PendingDecodeWindowReadsRegister(int consumerThreadId, unsigned short registerId)
	{
		if (getRuntime()->getAdmission()->DecisionDraft.getUsesIssuePacketAsExecutionSource())
		{
			return IssuePacketReadsRegister(consumerThreadId, registerId);
		}

		return GetCurrentDecodeThreadId() == consumerThreadId && DecodeStageReadsRegister(registerId);
	}

