	inline bool Processor::CPU_Core::TryExecuteExplicitPacketAssistLane(unsigned char laneIndex, ScalarExecuteLaneState &lane, int &executedPhysicalLaneCount)
	{
	// C# TO C++ CONVERTER TASK: There is no C++ equivalent to the C# 'null-forgiving operator':
	// ORIGINAL LINE: if (!lane.MicroOp!.IsAssist)
		if (!lane.MicroOp->isAssist())
		{
			return false;
		}

		bool success = ExecuteMicroOpWithStableCoreIdentity(lane.MicroOp);
		lane.CopyFrom(getRuntime()->getExecution()->Execute.GetLane(laneIndex));

		ApplyExplicitPacketAssistExecutionOutcome(laneIndex, lane, success, executedPhysicalLaneCount);
		return true;
	}

	inline void Processor::CPU_Core::RecordExecuteLaneTraceEvent(unsigned char laneIndex, ScalarExecuteLaneState lane)
	{
// C# TO C++ CONVERTER WARNING: Nullable reference types have no equivalent in C++:
// ORIGINAL LINE: HybridCPU_ISE.Core.TraceSink? traceSink = Processor.TraceSink;
		std::shared_ptr<HybridCPU_ISE::Core::TraceSink> traceSink = Processor::TraceSink;
		if (traceSink == nullptr)
		{
			return;
		}

		TraceEvent evt;
		evt.Result = lane.ResultValue;
		evt.ExceptionCount = this->getExceptionStatus()->TotalExceptions();

		traceSink->Record(evt);

		if (traceSink->getShouldCaptureFullState())
		{
			HybridCPU_ISE::Core::FullStateTraceEvent temp_var;
			temp_var.PC = static_cast<long long>(lane.PC);
			temp_var.BundleId = static_cast<int>(lane.PC / 256);
			temp_var.OpIndex = static_cast<int>((lane.PC % 256) / 32);
			temp_var.Opcode = lane.OpCode;
			temp_var.ThreadId = lane.WasFspInjected ? 0 : lane.OwnerThreadId;
			temp_var.CycleNumber = static_cast<long long>(pipeCtrl.getCycleCount());
			temp_var.RegisterFile = std::make_shared<std::vector<unsigned long long>>(CaptureTraceRegisterFile(lane.OwnerThreadId));
			temp_var.PredicateRegisters = std::make_shared<std::vector<unsigned short>>(CaptureTracePredicateRegisters());
			temp_var.WasStolenSlot = lane.WasFspInjected;
			temp_var.OriginalThreadId = lane.OriginalThreadId;
			temp_var.PipelineStage = std::format(L"EX-L{0}", laneIndex);
			temp_var.Stalled = pipeCtrl.Stalled;
			temp_var.StallReason = PipelineStallText::Render(pipeCtrl.StallReason, PipelineStallTextStyle::Trace);
			temp_var.ActiveMemoryRequests = GetBoundMemorySubsystemCurrentQueuedRequests();
			temp_var.MemorySubsystemCycle = 0;
			temp_var.ThreadReadyQueueDepths = _fspScheduler == nullptr ? nullptr : std::make_shared<std::vector<int>>(std::initializer_list<int>{_fspScheduler->GetOutstandingMemoryCount(0), _fspScheduler->GetOutstandingMemoryCount(1), _fspScheduler->GetOutstandingMemoryCount(2), _fspScheduler->GetOutstandingMemoryCount(3)});
			temp_var.CurrentFSPPolicy = _loopBuffer.getCurrentReplayPhase().isActive() ? L"ReplayAwarePhase1" : L"DeterministicFSP";
			traceSink->RecordPhaseAwareState(temp_var, _loopBuffer.getCurrentReplayPhase(), _fspScheduler == nullptr ? SchedulerPhaseMetrics{} : _fspScheduler->GetPhaseMetrics(), _loopBuffer.getCurrentReplayPhase().isActive() && (_fspScheduler == nullptr || _fspScheduler->GetPhaseMetrics().getLastCertificateInvalidationReason() == Core::ReplayPhaseInvalidationReason::None));
		}
	}

	inline bool Processor::CPU_Core::ShouldUseExplicitPacketGenericMicroOpExecutionContour(unsigned char laneIndex, std::shared_ptr<Core::MicroOp> microOp)
	{
		return laneIndex < 4 || std::dynamic_pointer_cast<Core::MatrixTileMicroOp>(microOp) != nullptr || std::dynamic_pointer_cast<Core::TrapMicroOp>(microOp) != nullptr || (laneIndex == 7 && !microOp->isMemoryOp() && (!microOp->isControlFlow() || std::dynamic_pointer_cast<Core::TrapMicroOp>(microOp) != nullptr));
	}

	inline void Processor::CPU_Core::ApplyExplicitPacketGenericMicroOpExecutionOutcome(unsigned char laneIndex, ScalarExecuteLaneState &lane, bool success, int &executedPhysicalLaneCount, int &executedScalarLaneCount)
	{
		lane.ResultReady = success;
		lane.GeneratedEvent = success ? MaterializeLaneGeneratedEvent(lane.MicroOp) : std::nullopt;
		lane.GeneratedCsrEffect.reset(); if (success) { auto effect = MaterializeLaneCsrEffect(lane.MicroOp); if (effect) lane.GeneratedCsrEffect.emplace(effect.value()); }
		lane.GeneratedAtomicEffect.reset(); if (success) { auto effect = MaterializeLaneAtomicEffect(lane.MicroOp); if (effect) lane.GeneratedAtomicEffect.emplace(effect.value()); }
		lane.GeneratedVmxEffect.reset(); if (success) { auto effect = MaterializeLaneVmxEffect(lane.MicroOp); if (effect) lane.GeneratedVmxEffect.emplace(effect.value()); }
		if (lane.GeneratedAtomicEffect)
		{
			lane.WritesRegister = false;
		}

		if (success && std::dynamic_pointer_cast<Core::TrapMicroOp>(lane.MicroOp) != nullptr)
		{
			// Canonical-known trapped auxiliaries may carry memory/control
			// admission facts for placement truth, but once the trap event
			// materializes they must not reopen LSU/control follow-through
			// in downstream MEM.
			lane.IsMemoryOp = false;
			lane.IsLoad = false;
			lane.MemoryAccessSize = 0;
			lane.MemoryAddress = 0;
		}
		else if (success && std::dynamic_pointer_cast<Core::VectorMicroOp>(lane.MicroOp) != nullptr)
		{
			// Completed vector/stream MicroOps already own their memory-side
			// follow-through in EX. Downstream MEM must not reopen legacy
			// scalar load/store handling for the same authoritative carrier.
			lane.IsMemoryOp = false;
		}

		if (success)
		{
			if (std::dynamic_pointer_cast<Core::MatrixTileMicroOp>(lane.MicroOp) != nullptr)
			{
				// MatrixTile owns its side effects through the MicroOp capture
				// recorded in EX and published only by WB-retire.  If the
				// MicroOp-owned execution path mutates the core while capturing,
				// keep the typed lane-6 carrier occupied so the existing
				// EX->MEM->WB handoff can retire it.  This does not authorize
				// ordinary lane-6 LSU/DMA/generic work.
				lane.IsOccupied = true;
				lane.LaneIndex = laneIndex;
			}

			lane.VectorComplete = true;
			unsigned long long writeBackValue;
			lane.ResultValue = TryResolveLanePrimaryWriteBackValue(lane.MicroOp, lane.GeneratedCsrEffect, writeBackValue) ? writeBackValue : 0;
		}
		else
		{
			lane.GeneratedRetireRecordCount = 0;
			lane.GeneratedRetireRecord0 = YAKSys_Hybrid_CPU::Core::Registers::Retire::RetireRecord();
			lane.GeneratedRetireRecord1 = YAKSys_Hybrid_CPU::Core::Registers::Retire::RetireRecord();
		}

		getRuntime()->getExecution()->Execute.SetLane(laneIndex, lane);
		if (laneIndex < 4)
		{
			executedScalarLaneCount++;
		}
		executedPhysicalLaneCount++;

		// Stage 6 Phase E: per-lane EX trace
		RecordExecuteLaneTraceEvent(laneIndex, lane);
	}

	inline bool Processor::CPU_Core::TryExecuteExplicitPacketGenericMicroOpLane(unsigned char laneIndex, ScalarExecuteLaneState &lane, int &executedPhysicalLaneCount, int &executedScalarLaneCount)
	{
	// C# TO C++ CONVERTER TASK: There is no C++ equivalent to the C# 'null-forgiving operator':
	// ORIGINAL LINE: if (!ShouldUseExplicitPacketGenericMicroOpExecutionContour(laneIndex, lane.MicroOp!))
		if (!ShouldUseExplicitPacketGenericMicroOpExecutionContour(laneIndex, lane.MicroOp))
		{
			return false;
		}

		bool success;
		std::shared_ptr<Core::ScalarALUMicroOp> scalarAlu = std::dynamic_pointer_cast<Core::ScalarALUMicroOp>(lane.MicroOp);
		if (scalarAlu != nullptr)
		{
			int consumerThreadId = NormalizePipelineStateVtId(lane.OwnerThreadId);
			unsigned long long source1 = GetRegisterValueWithForwardingExcludingExecuteLane(consumerThreadId, scalarAlu->getSrc1RegID(), laneIndex);
			unsigned long long source2 = scalarAlu->getUsesImmediate() ? scalarAlu->getImmediate() : GetRegisterValueWithForwardingExcludingExecuteLane(consumerThreadId, scalarAlu->getSrc2RegID(), laneIndex);
			success = scalarAlu->ExecuteWithResolvedPipelineOperands(source1, source2, lane.PC);
		}
		else
		{
			// MicroOp.Execute() remains the execution path for non-scalar-ALU carriers.
	// C# TO C++ CONVERTER TASK: There is no C++ equivalent to the C# 'null-forgiving operator':
	// ORIGINAL LINE: success = ExecuteMicroOpWithStableCoreIdentity(lane.MicroOp!);
			success = ExecuteMicroOpWithStableCoreIdentity(lane.MicroOp);
		}
		ApplyResolvedCpuTranslationToExecuteLane(laneIndex);
		lane.CopyFrom(getRuntime()->getExecution()->Execute.GetLane(laneIndex));

		ApplyExplicitPacketGenericMicroOpExecutionOutcome(laneIndex, lane, success, executedPhysicalLaneCount, executedScalarLaneCount);
		return true;
	}

	inline void Processor::CPU_Core::ApplyResolvedCpuTranslationToExecuteLane(unsigned char laneIndex)
	{
		ScalarExecuteLaneState lane = getRuntime()->getExecution()->Execute.GetLane(laneIndex);
		std::shared_ptr<Core::LoadStoreMicroOp> memoryOperation = std::dynamic_pointer_cast<Core::LoadStoreMicroOp>(lane.MicroOp);
		unsigned long long physicalAddress;
		unsigned long long ignoredOwnerEpoch;
		if (memoryOperation == nullptr || !memoryOperation->TryGetCpuTranslatedAddress(physicalAddress, ignoredOwnerEpoch))
		{
			return;
		}

		lane.MemoryAddress = physicalAddress;
		getRuntime()->getExecution()->Execute.SetLane(laneIndex, lane);
	}

	inline void Processor::CPU_Core::FailCloseSingleLaneExecuteAfterNonFaultException()
	{
		ReleaseExecuteStageLaneAwareBookkeeping();
		getRuntime()->getExecution()->Execute.Clear();
		getRuntime()->getExecution()->ExecuteForwarding.Clear();
	}

	inline void Processor::CPU_Core::FailCloseExplicitPacketLaneAfterNonFaultExecutionException(ScalarExecuteLaneState &lane, std::runtime_error exception)
	{
		std::shared_ptr<Core::Execution::ExecutionOutcome> outcome = ProjectExplicitPacketNonFaultExceptionOutcome(exception);
		if (outcome->getKind() != Core::Execution::ExecutionOutcomeKind::FatalInvariantViolation || outcome->getDiagnostic() == nullptr)
		{
			throw Core::Execution::ExecutionOutcomeContractViolationException(L"The explicit-packet non-fault adapter requires FatalInvariantViolation.");
		}

		unsigned char laneIndex = lane.LaneIndex;
		ReleaseScalarLaneBookkeeping(lane);

		ScalarExecuteLaneState clearedLane = ScalarExecuteLaneState();
		clearedLane.Clear(laneIndex);
		lane.CopyFrom(clearedLane);
		getRuntime()->getExecution()->Execute.SetLane(laneIndex, clearedLane);
	}

	inline std::shared_ptr<Core::Execution::ExecutionOutcome> Processor::CPU_Core::ProjectExplicitPacketNonFaultExceptionOutcome(std::runtime_error exception)
	{
		std::shared_ptr<Core::Execution::ExecutionOutcome> outcome = Core::Execution::Rf07LegacyOutcomeProjection::ProjectException(exception);
		if (outcome->getKind() != Core::Execution::ExecutionOutcomeKind::FatalInvariantViolation || outcome->getDiagnostic() == nullptr)
		{
			throw Core::Execution::ExecutionOutcomeContractViolationException(L"The explicit-packet non-fault projection requires FatalInvariantViolation.");
		}

		return outcome;
	}

	inline bool Processor::CPU_Core::ShouldMaterializeIssuePacketLane(Core::BundleIssuePacket issuePacket, unsigned char laneIndex, unsigned char executableNonScalarPhysicalLaneMask)
	{
		if (laneIndex < 4)
		{
			return issuePacket.GetPhysicalLane(laneIndex).isOccupied();
		}

		return (executableNonScalarPhysicalLaneMask & (1 << laneIndex)) != 0;
	}

// C# TO C++ CONVERTER WARNING: Nullable reference types have no equivalent in C++:
// ORIGINAL LINE: [MethodImpl(MethodImplOptions.AggressiveInlining)] private static ushort ResolvePrimaryWriteRegister(Core.MicroOp? microOp)
	inline unsigned short Processor::CPU_Core::ResolvePrimaryWriteRegister(std::shared_ptr<Core::MicroOp> microOp)
	{
// C# TO C++ CONVERTER WARNING: C++ has no equivalent to a 'readonly' collection which allows modification of internal state:
// ORIGINAL LINE: IReadOnlyList<int> writeRegisters = microOp == null ? null : microOp.WriteRegisters;
		const std::vector<int> writeRegisters = microOp == nullptr ? std::vector<int>{} : microOp->getWriteRegisters();
		if (writeRegisters.empty())
		{
			return 0;
		}

// C# TO C++ CONVERTER TASK: There is no C++ equivalent to 'unchecked' in this context:
// ORIGINAL LINE: return unchecked((ushort)writeRegisters[0]);
		return static_cast<unsigned short>(writeRegisters[0]);
	}

	inline Core::IssuePacketLane Processor::CPU_Core::ResolveMaterializedIssuePacketLane(Core::BundleIssuePacket issuePacket, unsigned char laneIndex, unsigned char executableNonScalarPhysicalLaneMask)
	{
		if (!ShouldMaterializeIssuePacketLane(issuePacket, laneIndex, executableNonScalarPhysicalLaneMask))
		{
			return Core::IssuePacketLane::CreateEmpty(laneIndex);
		}

		Core::IssuePacketLane rawIssueLane = issuePacket.GetPhysicalLane(laneIndex);
		if (rawIssueLane.getMicroOp() != nullptr && rawIssueLane.getMicroOp()->isSoftwareSecureSource())
		{
			return Core::IssuePacketLane::CreateEmpty(laneIndex);
		}
		Core::IssuePacketLane issueLane = ApplyIssueLaneExecutionSurfaceContract(rawIssueLane, issuePacket.getPC());
		if (!CanVirtualThreadIssueInForeground(issueLane.getOwnerThreadId()))
		{
			return Core::IssuePacketLane::CreateEmpty(laneIndex);
		}

		bool e1Attached = _fspScheduler->TryAttachVirtualizationAdmissionAfterCanonicalLaneMaterialization(issuePacket, issueLane);
		std::shared_ptr<Core::VmxMicroOp> vmx = std::dynamic_pointer_cast<Core::VmxMicroOp>(issueLane.getMicroOp());
		if (e1Attached && vmx != nullptr)
		{
			unsigned long long rs1Value = GetRegisterValueWithForwarding(issueLane.getOwnerThreadId(), vmx->getRs1());
			bool operandAttached = _fspScheduler->TryAttachVirtualizationOperandSnapshotAfterCanonicalValueRead(issuePacket, issueLane, rs1Value, _virtualizationRestoreGenerationOwner->getCurrentGeneration());
			if (!operandAttached)
			{
// C# TO C++ CONVERTER TASK: There is no C++ equivalent to 'unchecked' in this context:
// ORIGINAL LINE: System.Nullable<Core.VmcsField> selectedField = rs1Value <= ushort.MaxValue ? unchecked((Core.VmcsField)(ushort)rs1Value) : null;
				std::optional<Core::VmcsField> selectedField;
				if (rs1Value <= std::numeric_limits<unsigned short>::max()) selectedField = static_cast<Core::VmcsField>(static_cast<unsigned short>(rs1Value));
				if ((selectedField == Core::VmcsField::GuestPhysicalAddress || selectedField == Core::VmcsField::EptViolationQualification))
				{
					_fspScheduler->TryPrepareCompletionSecondStageVmReadAfterCanonicalValueRead(_completionSecondStageVmRead, issueLane, rs1Value, _virtualizationRestoreGenerationOwner->getCurrentGeneration());
				}
				else if ((selectedField == Core::VmcsField::ExitReason || selectedField == Core::VmcsField::ExitQualification))
				{
					_fspScheduler->TryPrepareCompletionReasonQualificationVmReadAfterCanonicalValueRead(_completionReasonQualificationVmRead, issueLane, rs1Value, _virtualizationRestoreGenerationOwner->getCurrentGeneration());
				}
				else if (selectedField == Core::VmcsField::PinBasedControls)
				{
					_fspScheduler->TryPreparePinBasedControlsVmReadAfterCanonicalValueRead(_pinBasedControlsVmRead, issueLane, rs1Value, _virtualizationRestoreGenerationOwner->getCurrentGeneration());
				}
				else
				{
					_fspScheduler->TryPrepareVmReadScalarAfterCanonicalValueRead(issuePacket, issueLane, rs1Value, _virtualizationRestoreGenerationOwner->getCurrentGeneration());
				}
			}
		}
		return issueLane;
	}

	unsigned long long Processor::CPU_Core::getCurrentVirtualizationRestoreGeneration() const
	{
		return _virtualizationRestoreGenerationOwner->getCurrentGeneration();
	}

	inline void Processor::CPU_Core::MaterializeExecuteStageLaneState()
	{
		getRuntime()->getExecution()->Execute.Clear();

		Core::BundleIssuePacket issuePacket = getRuntime()->getAdmission()->Handoff.getIssuePacket();
		auto dependencySummary = getRuntime()->getAdmission()->Handoff.getDependencySummary();
		unsigned char executableNonScalarPhysicalLaneMask = ResolveExecutableNonScalarPhysicalLaneMask(issuePacket, dependencySummary);
		getRuntime()->getExecution()->Execute.Valid = getRuntime()->getDecode()->Decode.Valid;
		getRuntime()->getExecution()->Execute.PreparedScalarMask = issuePacket.getPreparedScalarMask();
		getRuntime()->getExecution()->Execute.RefinedPreparedScalarMask = issuePacket.getRefinedPreparedScalarMask();
		getRuntime()->getExecution()->Execute.RetainsReferenceSequentialPath = issuePacket.getRetainsReferenceSequentialPath();
		getRuntime()->getExecution()->Execute.SelectedNonScalarSlotMask = ResolveExecutableNonScalarSlotMask(issuePacket, executableNonScalarPhysicalLaneMask);
		getRuntime()->getExecution()->Execute.BlockedScalarCandidateMask = issuePacket.getFallbackInfo().getBlockedScalarCandidateMask();
		getRuntime()->getExecution()->Execute.AdmissionExecutionMode = getRuntime()->getAdmission()->DecisionDraft.getExecutionMode();

		if (getRuntime()->getAdmission()->DecisionDraft.getUsesIssuePacketAsExecutionSource())
		{
			getRuntime()->getExecution()->Execute.UsesExplicitPacketLanes = true;
			int preparedScalarLaneCount = issuePacket.getPreparedScalarLaneCount();
			int preparedPhysicalLaneCount = issuePacket.getPreparedPhysicalLaneCount();
			getRuntime()->getExecution()->Execute.MaterializedScalarLaneCount = preparedScalarLaneCount;
			getRuntime()->getExecution()->Execute.MaterializedPhysicalLaneCount = preparedScalarLaneCount + std::popcount(static_cast<unsigned int>(executableNonScalarPhysicalLaneMask));
			getRuntime()->getExecution()->Execute.SetLane(0, CreateExecuteLaneState(issuePacket.getPC(), ResolveMaterializedIssuePacketLane(issuePacket, 0, executableNonScalarPhysicalLaneMask)));
			getRuntime()->getExecution()->Execute.SetLane(1, CreateExecuteLaneState(issuePacket.getPC(), ResolveMaterializedIssuePacketLane(issuePacket, 1, executableNonScalarPhysicalLaneMask)));
			getRuntime()->getExecution()->Execute.SetLane(2, CreateExecuteLaneState(issuePacket.getPC(), ResolveMaterializedIssuePacketLane(issuePacket, 2, executableNonScalarPhysicalLaneMask)));
			getRuntime()->getExecution()->Execute.SetLane(3, CreateExecuteLaneState(issuePacket.getPC(), ResolveMaterializedIssuePacketLane(issuePacket, 3, executableNonScalarPhysicalLaneMask)));
			getRuntime()->getExecution()->Execute.SetLane(4, CreateExecuteLaneState(issuePacket.getPC(), ResolveMaterializedIssuePacketLane(issuePacket, 4, executableNonScalarPhysicalLaneMask)));
			getRuntime()->getExecution()->Execute.SetLane(5, CreateExecuteLaneState(issuePacket.getPC(), ResolveMaterializedIssuePacketLane(issuePacket, 5, executableNonScalarPhysicalLaneMask)));
			getRuntime()->getExecution()->Execute.SetLane(6, CreateExecuteLaneState(issuePacket.getPC(), ResolveMaterializedIssuePacketLane(issuePacket, 6, executableNonScalarPhysicalLaneMask)));
			getRuntime()->getExecution()->Execute.SetLane(7, CreateExecuteLaneState(issuePacket.getPC(), ResolveMaterializedIssuePacketLane(issuePacket, 7, executableNonScalarPhysicalLaneMask)));
			getRuntime()->getExecution()->Execute.ActiveLaneIndex = ResolveActiveMaterializedIssueLaneIndex(issuePacket, getRuntime()->getDecode()->Decode.SlotIndex);

			pipeCtrl.setIssuePacketPreparedLaneCountSum(pipeCtrl.getIssuePacketPreparedLaneCountSum() + static_cast<unsigned long long>(preparedScalarLaneCount));
			pipeCtrl.setIssuePacketPreparedPhysicalLaneCountSum(pipeCtrl.getIssuePacketPreparedPhysicalLaneCountSum() + static_cast<unsigned long long>(preparedPhysicalLaneCount));

			// Stage 6 Phase A+B: enrich each occupied lane with MicroOp, classification,
			// per-lane GRLB resource acquisition, and per-lane MSHR scoreboard registration.
			EnrichClusterPreparedLanes(issuePacket, executableNonScalarPhysicalLaneMask);

			int materializedScalarLaneCount = CountOccupiedScalarExecuteLanes(getRuntime()->getExecution()->Execute);
			int materializedPhysicalLaneCount = CountOccupiedPhysicalExecuteLanes(getRuntime()->getExecution()->Execute);
			getRuntime()->getExecution()->Execute.MaterializedScalarLaneCount = materializedScalarLaneCount;
			getRuntime()->getExecution()->Execute.MaterializedPhysicalLaneCount = materializedPhysicalLaneCount;
			pipeCtrl.setIssuePacketMaterializedLaneCountSum(pipeCtrl.getIssuePacketMaterializedLaneCountSum() + static_cast<unsigned long long>(materializedScalarLaneCount));
			pipeCtrl.setIssuePacketMaterializedPhysicalLaneCountSum(pipeCtrl.getIssuePacketMaterializedPhysicalLaneCountSum() + static_cast<unsigned long long>(materializedPhysicalLaneCount));
			if (materializedPhysicalLaneCount < preparedPhysicalLaneCount)
			{
				pipeCtrl.setIssuePacketWidthDropCount(pipeCtrl.getIssuePacketWidthDropCount() + 1);
			}

			return;
		}

		getRuntime()->getExecution()->Execute.UsesExplicitPacketLanes = false;
		getRuntime()->getExecution()->Execute.MaterializedScalarLaneCount = getRuntime()->getDecode()->Decode.Valid ? 1 : 0;
		getRuntime()->getExecution()->Execute.MaterializedPhysicalLaneCount = getRuntime()->getDecode()->Decode.Valid ? 1 : 0;
		ScalarExecuteLaneState referenceLane = CreateLegacyExecuteLaneState(getRuntime()->getDecode()->Decode);
		// Stage B has already selected the physical placement. Reference
		// execution drains one lane without relabelling that issued identity.
		getRuntime()->getExecution()->Execute.ActiveLaneIndex = referenceLane.LaneIndex;
		getRuntime()->getExecution()->Execute.SetLane(referenceLane.LaneIndex, referenceLane);
	}

