	inline Processor::CPU_Core::ScalarExecuteLaneState Processor::CPU_Core::CreateExecuteLaneState(unsigned long long pc, Core::IssuePacketLane issueLane)
	{
		Processor::CPU_Core::ScalarExecuteLaneState lane = Processor::CPU_Core::ScalarExecuteLaneState();
		lane.Clear(issueLane.getLaneIndex());

		if (!issueLane.isOccupied())
		{
			return lane;
		}

		lane.IsOccupied = true;
		lane.PC = pc;
		lane.SlotIndex = issueLane.getSlotIndex();
		lane.OpCode = issueLane.getOpCode();
		lane.MicroOp = issueLane.getMicroOp();
		lane.PostStageBIssuedAttempt = issueLane.getMicroOp() == nullptr ? nullptr : issueLane.getMicroOp()->getPostStageBIssuedAttempt();
		lane.IsMemoryOp = issueLane.getMicroOp() != nullptr && issueLane.getMicroOp()->isMemoryOp();
		lane.WritesRegister = issueLane.getMicroOp() != nullptr && issueLane.getMicroOp()->getWritesRegister();
		lane.DestRegID = issueLane.getMicroOp() != nullptr ? issueLane.getMicroOp()->getDestRegID() : 0;
		lane.DomainTag = issueLane.getMicroOp() != nullptr ? issueLane.getMicroOp()->getPlacement().DomainTag : 0;
		lane.OwnerThreadId = issueLane.getOwnerThreadId();
		lane.VirtualThreadId = issueLane.getVirtualThreadId();
		lane.OwnerContextId = issueLane.getMicroOp() != nullptr ? issueLane.getMicroOp()->getOwnerContextId() : 0;
		lane.WasFspInjected = issueLane.getMicroOp() != nullptr && issueLane.getMicroOp()->isFspInjected();
		lane.OriginalThreadId = issueLane.getOwnerThreadId();
		return lane;
	}

	inline Processor::CPU_Core::ScalarExecuteLaneState Processor::CPU_Core::CreateLegacyExecuteLaneState(const Processor::CPU_Core::DecodeStage &decodeStage)
	{
		Processor::CPU_Core::ScalarExecuteLaneState lane = Processor::CPU_Core::ScalarExecuteLaneState();
// C# TO C++ CONVERTER TASK: The following 'is' operator pattern is not converted by C# to C++ Converter:
		std::shared_ptr<Core::PostStageBIssuedAttempt> issued = decodeStage.MicroOp == nullptr ? nullptr : decodeStage.MicroOp->getPostStageBIssuedAttempt();
		lane.Clear(issued != nullptr && issued->getScheduledOperation() != nullptr ? static_cast<unsigned char>(issued->getScheduledOperation()->getPhysicalLane()) : static_cast<unsigned char>(0));

		if (!decodeStage.Valid)
		{
			return lane;
		}

		lane.IsOccupied = true;
		lane.PC = decodeStage.PC;
		lane.SlotIndex = decodeStage.SlotIndex;
		lane.OpCode = decodeStage.OpCode;
		lane.IsMemoryOp = decodeStage.IsMemoryOp;
		lane.IsVectorOp = decodeStage.IsVectorOp;
		lane.WritesRegister = decodeStage.WritesRegister;
		lane.DestRegID = ResolvePrimaryWriteRegister(decodeStage.MicroOp);
		lane.MicroOp = decodeStage.MicroOp;
		lane.PostStageBIssuedAttempt = decodeStage.MicroOp == nullptr ? nullptr : decodeStage.MicroOp->getPostStageBIssuedAttempt();
		std::shared_ptr<Core::LoadMicroOp> load = std::dynamic_pointer_cast<Core::LoadMicroOp>(decodeStage.MicroOp);
		if (load != nullptr)
		{
			lane.IsLoad = true;
			lane.MemoryAccessSize = load->getSize();
			lane.MemoryAddress = load->getAddress();
		}
		lane.OwnerThreadId = decodeStage.MicroOp != nullptr ? decodeStage.MicroOp->getOwnerThreadId() : 0;
		lane.VirtualThreadId = decodeStage.MicroOp != nullptr ? decodeStage.MicroOp->getVirtualThreadId() : 0;
		lane.OwnerContextId = decodeStage.MicroOp != nullptr ? decodeStage.MicroOp->getOwnerContextId() : 0;
		lane.WasFspInjected = decodeStage.MicroOp != nullptr && decodeStage.MicroOp->isFspInjected();
		lane.OriginalThreadId = lane.OwnerThreadId;
		return lane;
	}

	inline void Processor::CPU_Core::EnrichClusterPreparedLanes(Core::BundleIssuePacket issuePacket, unsigned char executableNonScalarPhysicalLaneMask)
	{
		for (unsigned char laneIndex = 0; laneIndex < 8; laneIndex++)
		{
			ScalarExecuteLaneState lane = getRuntime()->getExecution()->Execute.GetLane(laneIndex);
			if (!lane.IsOccupied)
			{
				continue;
			}

			Core::IssuePacketLane issueLane = issuePacket.GetPhysicalLane(laneIndex);
			std::shared_ptr<Core::MicroOp> laneOp = issueLane.getMicroOp();

			if (laneOp != nullptr)
			{
				lane.MicroOp = laneOp;
				lane.IsMemoryOp = laneOp->isMemoryOp();
				lane.WritesRegister = laneOp->getWritesRegister();
				lane.DestRegID = laneOp->getDestRegID();
				lane.DomainTag = laneOp->getPlacement().DomainTag;
				lane.WasFspInjected = laneOp->isFspInjected();

				ResourceBitset laneResourceMask = laneOp->getResourceMask();
				if (laneResourceMask.isNonZero())
				{
					unsigned long long laneResourceToken;
					AcquireResourcesWithToken(laneResourceMask, laneResourceToken);
					lane.ResourceMask = laneResourceMask;
					lane.ResourceToken = laneResourceToken;
				}

				lane.MshrScoreboardSlot = -1;
				lane.MshrVirtualThreadId = laneOp->getVirtualThreadId();
				std::shared_ptr<Core::LoadStoreMicroOp> lsOp = std::dynamic_pointer_cast<Core::LoadStoreMicroOp>(laneOp);
				if (lsOp != nullptr && _fspScheduler != nullptr)
				{
					int bankId = lsOp->getMemoryBankId();
					int vtId = lsOp->getVirtualThreadId();
					ScoreboardEntryType entryType = std::dynamic_pointer_cast<Core::LoadMicroOp>(lsOp) != nullptr ? Core::ScoreboardEntryType::OutstandingLoad : Core::ScoreboardEntryType::OutstandingStore;
					int slot = _fspScheduler->SetSmtScoreboardPendingTyped(bankId, vtId, static_cast<long long>(pipeCtrl.getCycleCount()), entryType, bankId);
					lane.MshrScoreboardSlot = slot;
				}

				std::shared_ptr<Core::LoadMicroOp> loadOp = std::dynamic_pointer_cast<Core::LoadMicroOp>(laneOp);
				if (loadOp != nullptr)
				{
					lane.IsMemoryOp = true;
					lane.IsLoad = true;
					lane.MemoryAccessSize = loadOp->getSize();
					lane.MemoryAddress = loadOp->getAddress();
				}
				else
				{
					std::shared_ptr<Core::StoreMicroOp> storeOp = std::dynamic_pointer_cast<Core::StoreMicroOp>(laneOp);
					if (storeOp != nullptr && (executableNonScalarPhysicalLaneMask & (1 << laneIndex)) != 0)
					{
						lane.IsMemoryOp = true;
						lane.IsLoad = false;
						lane.MemoryAccessSize = storeOp->getSize();
						lane.MemoryAddress = storeOp->getAddress();
					}
				}
			}

			getRuntime()->getExecution()->Execute.SetLane(laneIndex, lane);
		}
	}

	inline Processor::CPU_Core::ScalarMemoryLaneState Processor::CPU_Core::CreateMemoryLaneState(ScalarExecuteLaneState executeLane)
	{
		Processor::CPU_Core::ScalarMemoryLaneState lane = Processor::CPU_Core::ScalarMemoryLaneState();
		lane.Clear(executeLane.LaneIndex);

		if (!executeLane.IsOccupied)
		{
			return lane;
		}

		lane.IsOccupied = true;
		lane.PC = executeLane.PC;
		lane.SlotIndex = executeLane.SlotIndex;
		lane.OpCode = executeLane.OpCode;
		lane.ResultValue = executeLane.ResultValue;
		lane.ResultReady = executeLane.ResultReady;
		lane.IsMemoryOp = executeLane.IsMemoryOp;
		lane.MemoryAddress = executeLane.MemoryAddress;
		lane.MemoryData = executeLane.MemoryData;
		lane.IsLoad = executeLane.IsLoad;
		lane.MemoryAccessSize = executeLane.MemoryAccessSize;
		lane.IsVectorOp = executeLane.IsVectorOp;
		lane.VectorComplete = executeLane.VectorComplete;
		lane.WritesRegister = executeLane.WritesRegister;
		lane.DestRegID = executeLane.DestRegID;
		lane.MicroOp = executeLane.MicroOp;
		lane.PostStageBIssuedAttempt = executeLane.PostStageBIssuedAttempt;
		lane.GeneratedEvent = executeLane.GeneratedEvent;
		lane.GeneratedCsrEffect.reset(); if (executeLane.GeneratedCsrEffect) lane.GeneratedCsrEffect.emplace(executeLane.GeneratedCsrEffect.value());
		lane.GeneratedAtomicEffect.reset(); if (executeLane.GeneratedAtomicEffect) lane.GeneratedAtomicEffect.emplace(executeLane.GeneratedAtomicEffect.value());
		lane.GeneratedVmxEffect.reset(); if (executeLane.GeneratedVmxEffect) lane.GeneratedVmxEffect.emplace(executeLane.GeneratedVmxEffect.value());
		lane.GeneratedRetireRecordCount = executeLane.GeneratedRetireRecordCount;
		lane.GeneratedRetireRecord0 = executeLane.GeneratedRetireRecord0;
		lane.GeneratedRetireRecord1 = executeLane.GeneratedRetireRecord1;
		lane.DomainTag = executeLane.DomainTag;
		lane.MshrScoreboardSlot = executeLane.MshrScoreboardSlot;
		lane.MshrVirtualThreadId = executeLane.MshrVirtualThreadId;
		lane.ResourceMask = executeLane.ResourceMask;
		lane.ResourceToken = executeLane.ResourceToken;
		lane.OwnerThreadId = executeLane.OwnerThreadId;
		lane.VirtualThreadId = executeLane.VirtualThreadId;
		// Propagate architectural privilege-domain id through EX->MEM.
		lane.OwnerContextId = executeLane.OwnerContextId;
		lane.WasFspInjected = executeLane.WasFspInjected;
		lane.OriginalThreadId = executeLane.OriginalThreadId;
		lane.HasFault = executeLane.HasFault;
		lane.FaultAddress = executeLane.FaultAddress;
		lane.FaultIsWrite = executeLane.FaultIsWrite;
		lane.CpuTranslationFault = executeLane.CpuTranslationFault;

		if (executeLane.LaneIndex == 4 or 5 && executeLane.IsMemoryOp && !executeLane.GeneratedAtomicEffect)
		{
			// The live widened LSU load/store subset claims readiness from MEM completion,
			// not from EX address preparation.
			lane.ResultReady = false;
		}

		return lane;
	}

