		lane.GeneratedAtomicEffect.reset(); if (memoryLane.GeneratedAtomicEffect) lane.GeneratedAtomicEffect.emplace(memoryLane.GeneratedAtomicEffect.value());
		lane.GeneratedVmxEffect.reset(); if (memoryLane.GeneratedVmxEffect) lane.GeneratedVmxEffect.emplace(memoryLane.GeneratedVmxEffect.value());
		lane.GeneratedRetireRecordCount = memoryLane.GeneratedRetireRecordCount;
		lane.GeneratedRetireRecord0 = memoryLane.GeneratedRetireRecord0;
