	inline unsigned char Processor::CPU_Core::ResolveActiveMaterializedIssueLaneIndex(Core::BundleIssuePacket issuePacket, unsigned char slotIndex)
	{
		for (unsigned char laneIndex = 0; laneIndex < 8; laneIndex++)
		{
			Core::IssuePacketLane lane = issuePacket.GetPhysicalLane(laneIndex);
			if (lane.isOccupied() && lane.getSlotIndex() == slotIndex)
			{
				return laneIndex;
			}
		}

		unsigned char oldestLaneIndex = std::numeric_limits<unsigned char>::max();
		for (unsigned char laneIndex = 0; laneIndex < 8; laneIndex++)
		{
			Core::IssuePacketLane lane = issuePacket.GetPhysicalLane(laneIndex);
			if (!lane.isOccupied())
			{
				continue;
			}

			if (oldestLaneIndex == std::numeric_limits<unsigned char>::max() || CompareIssuePacketLaneOrder(issuePacket, laneIndex, oldestLaneIndex) < 0)
			{
				oldestLaneIndex = laneIndex;
			}
		}

		return oldestLaneIndex < 8 ? oldestLaneIndex : static_cast<unsigned char>(0);
	}

	inline int Processor::CPU_Core::CompareIssuePacketLaneOrder(Core::BundleIssuePacket issuePacket, unsigned char leftLaneIndex, unsigned char rightLaneIndex)
	{
		if (leftLaneIndex == rightLaneIndex)
		{
			return 0;
		}

		Core::IssuePacketLane leftLane = issuePacket.GetPhysicalLane(leftLaneIndex);
		Core::IssuePacketLane rightLane = issuePacket.GetPhysicalLane(rightLaneIndex);
		if (leftLane.isOccupied() && rightLane.isOccupied() && leftLane.getSlotIndex() < 8 && rightLane.getSlotIndex() < 8)
		{
			int compareResult = leftLane.getSlotIndex() < rightLane.getSlotIndex() ? -1 : (leftLane.getSlotIndex() > rightLane.getSlotIndex() ? 1 : 0);
			if (compareResult != 0)
			{
				return compareResult;
			}
		}

		return leftLaneIndex < rightLaneIndex ? -1 : (leftLaneIndex > rightLaneIndex ? 1 : 0);
	}

