	void Processor::CPU_Core::BranchPredictor::Clear()
	{
		PredictTaken = false;
		PredictedPC = 0;
		Active = false;
	}

	void Processor::CPU_Core::BranchPredictor::Predict(unsigned long long currentPC, unsigned long long fallThroughPC)
	{
		PredictTaken = false;
		PredictedPC = fallThroughPC;
		Active = true;
	}

	bool Processor::CPU_Core::BranchPredictor::WasCorrect(bool actualTaken, unsigned long long actualPC)
	{
		return (PredictTaken == actualTaken) && (PredictedPC == actualPC);
	}

	unsigned char Processor::CPU_Core::ResolveRetireEligibleWriteBackLanes(WriteBackStage const writeBackStage)
	{
		if (!writeBackStage.Valid)
		{
			return 0;
		}

		unsigned char occupiedMask = GetOccupiedRetireEligibleWriteBackLaneMask(writeBackStage);
		if (occupiedMask == 0)
		{
			return 0;
		}

		if (!writeBackStage.UsesExplicitPacketLanes && writeBackStage.RetainsReferenceSequentialPath)
		{
			unsigned char retireLaneIndex = ResolveConservativeRetireEligibleLaneIndex(writeBackStage, occupiedMask);
			if (retireLaneIndex >= 4 && !IsMatrixTileRetireLane(writeBackStage, retireLaneIndex))
			{
				return 0;
			}

			return static_cast<unsigned char>(1 << retireLaneIndex);
		}

		unsigned char faultMask = ResolveWriteBackFaultMask(writeBackStage);
		return static_cast<unsigned char>(occupiedMask & ~faultMask);
	}

	int Processor::CPU_Core::ResolveStableRetireOrder(WriteBackStage const writeBackStage, std::span<unsigned char> retireOrder)
	{
		unsigned char eligibleMask = ResolveRetireEligibleWriteBackLanes(writeBackStage);
		int count = 0;

		for (unsigned char laneIndex = 0; laneIndex < 8 && count < retireOrder.size(); laneIndex++)
		{
			if (!IsRetireAuthoritativeWriteBackLane(writeBackStage, laneIndex))
			{
				continue;
			}

			if ((eligibleMask & (1 << laneIndex)) == 0)
			{
				continue;
			}

			InsertWriteBackLaneInStableRetireOrder(writeBackStage, retireOrder, count, laneIndex);
		}

		return count;
	}

	bool Processor::CPU_Core::CanRetireLanePrecisely(WriteBackStage const writeBackStage, unsigned char laneIndex)
	{
		if (!IsRetireAuthoritativeWriteBackLane(writeBackStage, laneIndex))
		{
			return false;
		}

		return (ResolveRetireEligibleWriteBackLanes(writeBackStage) & (1 << laneIndex)) != 0;
	}

	inline bool Processor::CPU_Core::IsRetireAuthoritativeWriteBackLane(unsigned char laneIndex)
	{
		return laneIndex < 6 || laneIndex == 7;
	}

	inline bool Processor::CPU_Core::IsRetireAuthoritativeWriteBackLane(WriteBackStage const writeBackStage, unsigned char laneIndex)
	{
		if (!IsRetireAuthoritativeWriteBackLane(laneIndex) && !IsMatrixTileRetireLane(writeBackStage, laneIndex))
		{
			return false;
		}

		ScalarWriteBackLaneState lane = writeBackStage.GetLane(laneIndex);
		return !lane.IsOccupied || lane.MicroOp == nullptr || lane.MicroOp->isRetireVisible();
	}

	inline bool Processor::CPU_Core::IsMatrixTileRetireLane(WriteBackStage const writeBackStage, unsigned char laneIndex)
	{
		return laneIndex == CloseToHSL::Core::ISA::Instructions::NonVmx::Lanes00_03Vector::MatrixTile::MatrixTileResourceContour::TileStreamLaneId && writeBackStage.Lane6.IsOccupied && std::dynamic_pointer_cast<Core::MatrixTileMicroOp>(writeBackStage.Lane6.MicroOp) != nullptr;
	}

	inline bool Processor::CPU_Core::IsArchitecturallyInvisibleWriteBackLane(ScalarWriteBackLaneState const lane)
	{
		return lane.IsOccupied && lane.MicroOp != nullptr && !lane.MicroOp->isRetireVisible();
	}

	inline unsigned char Processor::CPU_Core::GetOccupiedRetireEligibleWriteBackLaneMask(WriteBackStage const writeBackStage)
	{
		unsigned char occupiedMask = 0;

		if (writeBackStage.Lane0.IsOccupied && IsRetireAuthoritativeWriteBackLane(writeBackStage, 0))
		{
			occupiedMask |= 1 << 0;
		}

		if (writeBackStage.Lane1.IsOccupied && IsRetireAuthoritativeWriteBackLane(writeBackStage, 1))
		{
			occupiedMask |= 1 << 1;
		}

		if (writeBackStage.Lane2.IsOccupied && IsRetireAuthoritativeWriteBackLane(writeBackStage, 2))
		{
			occupiedMask |= 1 << 2;
		}

		if (writeBackStage.Lane3.IsOccupied && IsRetireAuthoritativeWriteBackLane(writeBackStage, 3))
		{
			occupiedMask |= 1 << 3;
		}

		if (writeBackStage.Lane4.IsOccupied && IsRetireAuthoritativeWriteBackLane(writeBackStage, 4))
		{
			occupiedMask |= 1 << 4;
		}

		if (writeBackStage.Lane5.IsOccupied && IsRetireAuthoritativeWriteBackLane(writeBackStage, 5))
		{
			occupiedMask |= 1 << 5;
		}

		if (writeBackStage.Lane6.IsOccupied && IsRetireAuthoritativeWriteBackLane(writeBackStage, 6))
		{
			occupiedMask |= 1 << 6;
		}

		if (writeBackStage.Lane7.IsOccupied && IsRetireAuthoritativeWriteBackLane(writeBackStage, 7))
		{
			occupiedMask |= 1 << 7;
		}

		return occupiedMask;
	}

	inline int Processor::CPU_Core::CountOccupiedScalarWriteBackLanes(WriteBackStage const writeBackStage)
	{
		int count = 0;

		if (writeBackStage.Lane0.IsOccupied)
		{
			count++;
		}

		if (writeBackStage.Lane1.IsOccupied)
		{
			count++;
		}

		if (writeBackStage.Lane2.IsOccupied)
		{
			count++;
		}

		if (writeBackStage.Lane3.IsOccupied)
		{
			count++;
		}

		return count;
	}

	inline unsigned char Processor::CPU_Core::ResolveConservativeRetireEligibleLaneIndex(WriteBackStage const writeBackStage, unsigned char occupiedMask)
	{
		unsigned char explicitPacketLaneIndex;
		if (writeBackStage.UsesExplicitPacketLanes && TryResolveOldestOrderedWriteBackLaneIndex(writeBackStage, occupiedMask, explicitPacketLaneIndex))
		{
			return explicitPacketLaneIndex;
		}

		if (IsRetireAuthoritativeWriteBackLane(writeBackStage.ActiveLaneIndex))
		{
			unsigned char activeLaneMask = static_cast<unsigned char>(1 << writeBackStage.ActiveLaneIndex);
			if ((occupiedMask & activeLaneMask) != 0)
			{
				return writeBackStage.ActiveLaneIndex;
			}
		}

		for (unsigned char laneIndex = 0; laneIndex < 8; laneIndex++)
		{
			if (!IsRetireAuthoritativeWriteBackLane(writeBackStage, laneIndex))
			{
				continue;
			}

			if ((occupiedMask & (1 << laneIndex)) != 0)
			{
				return laneIndex;
			}
		}

		return std::numeric_limits<unsigned char>::max();
	}

	inline void Processor::CPU_Core::InsertWriteBackLaneInStableRetireOrder(WriteBackStage const writeBackStage, std::span<unsigned char> retireOrder, int &count, unsigned char laneIndex)
	{
		int insertIndex = count;
		while (insertIndex > 0 && CompareWriteBackLaneOrder(writeBackStage, laneIndex, retireOrder[insertIndex - 1]) < 0)
		{
			retireOrder[insertIndex] = retireOrder[insertIndex - 1];
			insertIndex--;
		}

		retireOrder[insertIndex] = laneIndex;
		count++;
	}

	inline bool Processor::CPU_Core::TryResolveOldestOrderedWriteBackLaneIndex(WriteBackStage const writeBackStage, unsigned char laneMask, unsigned char &laneIndex)
	{
		laneIndex = std::numeric_limits<unsigned char>::max();
		bool found = false;

		for (unsigned char candidateLaneIndex = 0; candidateLaneIndex < 8; candidateLaneIndex++)
		{
			if (!IsRetireAuthoritativeWriteBackLane(writeBackStage, candidateLaneIndex))
			{
				continue;
			}

			if ((laneMask & (1 << candidateLaneIndex)) == 0)
			{
				continue;
			}

			if (!found || CompareWriteBackLaneOrder(writeBackStage, candidateLaneIndex, laneIndex) < 0)
			{
				laneIndex = candidateLaneIndex;
				found = true;
			}
		}

		return found;
	}

	inline int Processor::CPU_Core::CompareWriteBackLaneOrder(WriteBackStage const writeBackStage, unsigned char leftLaneIndex, unsigned char rightLaneIndex)
	{
		if (leftLaneIndex == rightLaneIndex)
		{
			return 0;
		}

		int leftOrderKey;
		int rightOrderKey;
		if (TryResolveWriteBackLaneOrderKey(writeBackStage, leftLaneIndex, leftOrderKey) && TryResolveWriteBackLaneOrderKey(writeBackStage, rightLaneIndex, rightOrderKey))
		{
			int compareResult = leftOrderKey < rightOrderKey ? -1 : (leftOrderKey > rightOrderKey ? 1 : 0);
			if (compareResult != 0)
			{
				return compareResult;
			}
		}

		return leftLaneIndex < rightLaneIndex ? -1 : (leftLaneIndex > rightLaneIndex ? 1 : 0);
	}

	inline bool Processor::CPU_Core::TryResolveWriteBackLaneOrderKey(WriteBackStage const writeBackStage, unsigned char laneIndex, int &orderKey)
	{
		orderKey = laneIndex;
		if (!writeBackStage.UsesExplicitPacketLanes)
		{
			return false;
		}

		ScalarWriteBackLaneState lane = writeBackStage.GetLane(laneIndex);
		if (!lane.IsOccupied || lane.SlotIndex >= 8)
		{
			return false;
		}

		orderKey = lane.SlotIndex;
		return true;
	}

	unsigned char Processor::CPU_Core::ResolveAuthoritativeControlFlowScalarLanes(ExecuteStage const executeStage)
	{
		if (!executeStage.Valid)
		{
			return 0;
		}

		unsigned char occupiedControlFlowMask = GetOccupiedControlFlowExecuteLaneMask(executeStage);
		if (occupiedControlFlowMask == 0)
		{
			return 0;
		}

		unsigned char authoritativeLaneIndex = ResolveConservativeControlFlowLaneIndex(executeStage, occupiedControlFlowMask);
		if (authoritativeLaneIndex >= 4)
		{
			return 0;
		}

		return static_cast<unsigned char>(1 << authoritativeLaneIndex);
	}

	int Processor::CPU_Core::ResolveStableControlFlowOrder(ExecuteStage const executeStage, std::span<unsigned char> controlFlowOrder)
	{
		unsigned char authoritativeMask = ResolveAuthoritativeControlFlowScalarLanes(executeStage);
		int count = 0;

		for (unsigned char laneIndex = 0; laneIndex < 4 && count < controlFlowOrder.size(); laneIndex++)
		{
			if ((authoritativeMask & (1 << laneIndex)) == 0)
			{
				continue;
			}

			controlFlowOrder[count++] = laneIndex;
		}

		return count;
	}

	unsigned char Processor::CPU_Core::ResolveDominatedScalarLanesForControlFlow(ExecuteStage const executeStage)
	{
		unsigned char authoritativeMask = ResolveAuthoritativeControlFlowScalarLanes(executeStage);
		if (authoritativeMask == 0)
		{
			return 0;
		}

		unsigned char occupiedMask = GetOccupiedScalarExecuteLaneMask(executeStage);
		return static_cast<unsigned char>(occupiedMask & ~authoritativeMask);
	}

	inline unsigned char Processor::CPU_Core::GetOccupiedScalarExecuteLaneMask(ExecuteStage const executeStage)
	{
		unsigned char occupiedMask = 0;

		if (executeStage.Lane0.IsOccupied)
		{
			occupiedMask |= 1 << 0;
		}

		if (executeStage.Lane1.IsOccupied)
		{
			occupiedMask |= 1 << 1;
		}

		if (executeStage.Lane2.IsOccupied)
		{
			occupiedMask |= 1 << 2;
		}

		if (executeStage.Lane3.IsOccupied)
		{
			occupiedMask |= 1 << 3;
		}

		return occupiedMask;
	}

	inline int Processor::CPU_Core::CountOccupiedScalarExecuteLanes(ExecuteStage const executeStage)
	{
		int count = 0;

		if (executeStage.Lane0.IsOccupied)
		{
			count++;
		}

		if (executeStage.Lane1.IsOccupied)
		{
			count++;
		}

		if (executeStage.Lane2.IsOccupied)
		{
			count++;
		}

		if (executeStage.Lane3.IsOccupied)
		{
			count++;
		}

		return count;
	}

	inline unsigned char Processor::CPU_Core::GetOccupiedControlFlowExecuteLaneMask(ExecuteStage const executeStage)
	{
		unsigned char occupiedMask = 0;

		if (executeStage.Lane0.IsOccupied && IsControlFlowOpcode(executeStage.Lane0.OpCode))
		{
			occupiedMask |= 1 << 0;
		}

		if (executeStage.Lane1.IsOccupied && IsControlFlowOpcode(executeStage.Lane1.OpCode))
		{
			occupiedMask |= 1 << 1;
		}

		if (executeStage.Lane2.IsOccupied && IsControlFlowOpcode(executeStage.Lane2.OpCode))
		{
			occupiedMask |= 1 << 2;
		}

		if (executeStage.Lane3.IsOccupied && IsControlFlowOpcode(executeStage.Lane3.OpCode))
		{
			occupiedMask |= 1 << 3;
		}

		return occupiedMask;
	}

	inline unsigned char Processor::CPU_Core::ResolveConservativeControlFlowLaneIndex(ExecuteStage const executeStage, unsigned char occupiedControlFlowMask)
	{
		if (executeStage.ActiveLaneIndex < 4)
		{
			unsigned char activeLaneMask = static_cast<unsigned char>(1 << executeStage.ActiveLaneIndex);
			if ((occupiedControlFlowMask & activeLaneMask) != 0)
			{
				return executeStage.ActiveLaneIndex;
			}
		}

		for (unsigned char laneIndex = 0; laneIndex < 4; laneIndex++)
		{
			if ((occupiedControlFlowMask & (1 << laneIndex)) != 0)
			{
				return laneIndex;
			}
		}

		return std::numeric_limits<unsigned char>::max();
	}

	unsigned char Processor::CPU_Core::ResolveControlFlowDominanceForMixedPeers(ExecuteStage const executeStage)
	{
		unsigned char authoritativeMask = ResolveAuthoritativeControlFlowScalarLanes(executeStage);
		if (authoritativeMask == 0)
		{
			return 0;
		}

		unsigned char occupiedMask = GetOccupiedScalarExecuteLaneMask(executeStage);
		unsigned char dominatedPeers = static_cast<unsigned char>(occupiedMask & ~authoritativeMask);

		return dominatedPeers;
	}

	bool Processor::CPU_Core::CanYoungerPeerCommitAfterRedirectWinner(ExecuteStage const executeStage, unsigned char peerLaneIndex)
	{
		if (peerLaneIndex >= 4)
		{
			return false;
		}

		unsigned char authoritativeMask = ResolveAuthoritativeControlFlowScalarLanes(executeStage);
		if (authoritativeMask == 0)
		{
			return true;
		}

		unsigned char peerBit = static_cast<unsigned char>(1 << peerLaneIndex);
		if ((authoritativeMask & peerBit) != 0)
		{
			return true;
		}

		ScalarExecuteLaneState peer = executeStage.GetLane(peerLaneIndex);
		if (!peer.IsOccupied)
		{
			return false;
		}

		return false;
	}

	bool Processor::CPU_Core::DoesSelectedNonScalarSlotMaskContaminateRetireEligibility(WriteBackStage const writeBackStage)
	{
		unsigned char nonScalarMask = writeBackStage.SelectedNonScalarSlotMask;
		if (nonScalarMask == 0)
		{
			return false;
		}

		unsigned char occupiedMask = GetOccupiedRetireEligibleWriteBackLaneMask(writeBackStage);
		unsigned char nonScalarOnlyBits = static_cast<unsigned char>(nonScalarMask & ~occupiedMask);

		unsigned char eligibleMask = ResolveRetireEligibleWriteBackLanes(writeBackStage);
		return (eligibleMask & nonScalarOnlyBits) != 0;
	}

