	bool Processor::CPU_Core::TryResolveStageAwareExceptionWinner(WriteBackStage const writeBackStage, MemoryStage const memoryStage, ExecuteStage const executeStage, PipelineStage &winnerStage, unsigned char &winnerLaneIndex)
	{
		if (TryResolveOldestOrderedWriteBackFaultLane(writeBackStage, winnerLaneIndex))
		{
			winnerStage = PipelineStage::WriteBack;
			return true;
		}

		if (TryResolveOldestOrderedMemoryFaultLane(memoryStage, winnerLaneIndex))
		{
			winnerStage = PipelineStage::Memory;
			return true;
		}

		if (TryResolveOldestOrderedExecuteFaultLane(executeStage, winnerLaneIndex))
		{
			winnerStage = PipelineStage::Execute;
			return true;
		}

		winnerStage = PipelineStage::None;
		winnerLaneIndex = std::numeric_limits<unsigned char>::max();
		return false;
	}

	inline int Processor::CPU_Core::AppendStageAwareExceptionOrder(PipelineStage stage, unsigned char faultMask, std::span<PipelineStage> orderedStages, std::span<unsigned char> orderedLanes, int count)
	{
		for (unsigned char laneIndex = 0; laneIndex < 8 && count < orderedStages.size() && count < orderedLanes.size(); laneIndex++)
		{
			if ((faultMask & (1 << laneIndex)) == 0)
			{
				continue;
			}

			orderedStages[count] = stage;
			orderedLanes[count] = laneIndex;
			count++;
		}

		return count;
	}

