	Processor::CPU_Core::StageAwareExceptionWinnerMetadata::StageAwareExceptionWinnerMetadata(PipelineStage winnerStage, unsigned char winnerLaneIndex, int ownerThreadId, int virtualThreadId, unsigned long long faultAddress, bool faultIsWrite, unsigned long long pc, const std::optional<std::shared_ptr<Core::Memory::CpuInstructionTranslationFault>> &cpuTranslationFault)
	{
		WinnerStage = winnerStage;
		WinnerLaneIndex = winnerLaneIndex;
		OwnerThreadId = ownerThreadId;
		VirtualThreadId = virtualThreadId;
		FaultAddress = faultAddress;
		FaultIsWrite = faultIsWrite;
		PC = pc;
		CpuTranslationFault = cpuTranslationFault;
	}

	bool Processor::CPU_Core::StageAwareExceptionWinnerMetadata::isValid() const
	{
		return getWinnerStage() != PipelineStage::None && getWinnerLaneIndex() < 8;
	}

	bool Processor::CPU_Core::TryResolveStageAwareExceptionWinnerMetadata(WriteBackStage const writeBackStage, MemoryStage const memoryStage, ExecuteStage const executeStage, StageAwareExceptionWinnerMetadata &metadata)
	{
		PipelineStage winnerStage;
		unsigned char winnerLaneIndex;
		if (!TryResolveStageAwareExceptionWinner(writeBackStage, memoryStage, executeStage, winnerStage, winnerLaneIndex))
		{
			metadata = YAKSys_Hybrid_CPU::Processor::CPU_Core::StageAwareExceptionWinnerMetadata();
			return false;
		}

		switch (winnerStage)
		{
			case PipelineStage::WriteBack: metadata = BuildWriteBackWinnerMetadata(writeBackStage, winnerLaneIndex); break;
			case PipelineStage::Memory: metadata = BuildMemoryWinnerMetadata(memoryStage, winnerLaneIndex); break;
			case PipelineStage::Execute: metadata = BuildExecuteWinnerMetadata(executeStage, winnerLaneIndex); break;
			default: metadata = StageAwareExceptionWinnerMetadata(); break;
		}

		return metadata.isValid();
	}

	bool Processor::CPU_Core::ShouldSuppressYoungerWorkForExceptionWinner(PipelineStage winnerStage, WriteBackStage const writeBackStage, MemoryStage const memoryStage, ExecuteStage const executeStage)
	{
		if (winnerStage == PipelineStage::WriteBack)
		{
			return GetOccupiedLivePreciseExceptionMemoryLaneMask(memoryStage) != 0 || GetOccupiedLivePreciseExceptionExecuteLaneMask(executeStage) != 0;
		}

		if (winnerStage == PipelineStage::Memory)
		{
			return GetOccupiedLivePreciseExceptionExecuteLaneMask(executeStage) != 0;
		}

		return false;
	}

	bool Processor::CPU_Core::CanDeliverOlderStageFault(PipelineStage winnerStage)
	{
		return winnerStage == PipelineStage::WriteBack || winnerStage == PipelineStage::Memory;
	}

	unsigned char Processor::CPU_Core::ResolveExceptionWinnerSuppressedLaneMask(PipelineStage winnerStage, MemoryStage const memoryStage, ExecuteStage const executeStage)
	{
		unsigned char suppressedMask = 0;

		if (winnerStage == PipelineStage::WriteBack)
		{
			suppressedMask |= GetOccupiedLivePreciseExceptionMemoryLaneMask(memoryStage);
			suppressedMask |= GetOccupiedLivePreciseExceptionExecuteLaneMask(executeStage);
		}
		else if (winnerStage == PipelineStage::Memory)
		{
			suppressedMask |= GetOccupiedLivePreciseExceptionExecuteLaneMask(executeStage);
		}

		return suppressedMask;
	}

	bool Processor::CPU_Core::TryResolveExceptionDeliveryDecisionForRetireWindow(WriteBackStage const writeBackStage, MemoryStage const memoryStage, ExecuteStage const executeStage, PipelineStage &winnerStage, unsigned char &winnerLaneIndex, bool &shouldSuppressYoungerWork)
	{
		unsigned char wbFaultMask = ResolveWriteBackFaultMask(writeBackStage);
		unsigned char memFaultMask = ResolveMemoryFaultMask(memoryStage);
		unsigned char exFaultMask = ResolveExecuteFaultMask(executeStage);

		if (wbFaultMask == 0 && memFaultMask == 0 && exFaultMask == 0)
		{
			winnerStage = PipelineStage::None;
			winnerLaneIndex = std::numeric_limits<unsigned char>::max();
			shouldSuppressYoungerWork = false;
			return false;
		}

		if (!TryResolveStageAwareExceptionWinner(writeBackStage, memoryStage, executeStage, winnerStage, winnerLaneIndex))
		{
			shouldSuppressYoungerWork = false;
			return false;
		}

		shouldSuppressYoungerWork = ShouldSuppressYoungerWorkForExceptionWinner(winnerStage, writeBackStage, memoryStage, executeStage);

		return true;
	}

	bool Processor::CPU_Core::TryResolveStageAwareExceptionWinnerIdentity(WriteBackStage const writeBackStage, MemoryStage const memoryStage, ExecuteStage const executeStage, int &winnerVirtualThreadId, int &winnerOwnerThreadId)
	{
		StageAwareExceptionWinnerMetadata metadata;
		if (!TryResolveStageAwareExceptionWinnerMetadata(writeBackStage, memoryStage, executeStage, metadata))
		{
			winnerVirtualThreadId = -1;
			winnerOwnerThreadId = -1;
			return false;
		}

		winnerVirtualThreadId = metadata.getVirtualThreadId();
		winnerOwnerThreadId = metadata.getOwnerThreadId();
		return true;
	}

	inline Processor::CPU_Core::StageAwareExceptionWinnerMetadata Processor::CPU_Core::BuildWriteBackWinnerMetadata(WriteBackStage const writeBackStage, unsigned char laneIndex)
	{
		ScalarWriteBackLaneState lane = writeBackStage.GetLane(laneIndex);
		return Processor::CPU_Core::StageAwareExceptionWinnerMetadata(PipelineStage::WriteBack, laneIndex, lane.OwnerThreadId, lane.VirtualThreadId, lane.FaultAddress, lane.FaultIsWrite, lane.PC, lane.CpuTranslationFault);
	}

	inline Processor::CPU_Core::StageAwareExceptionWinnerMetadata Processor::CPU_Core::BuildMemoryWinnerMetadata(MemoryStage const memoryStage, unsigned char laneIndex)
	{
		ScalarMemoryLaneState lane = memoryStage.GetLane(laneIndex);
		return Processor::CPU_Core::StageAwareExceptionWinnerMetadata(PipelineStage::Memory, laneIndex, lane.OwnerThreadId, lane.VirtualThreadId, lane.FaultAddress, lane.FaultIsWrite, lane.PC, lane.CpuTranslationFault);
	}

	inline Processor::CPU_Core::StageAwareExceptionWinnerMetadata Processor::CPU_Core::BuildExecuteWinnerMetadata(ExecuteStage const executeStage, unsigned char laneIndex)
	{
		ScalarExecuteLaneState lane = executeStage.GetLane(laneIndex);
		return Processor::CPU_Core::StageAwareExceptionWinnerMetadata(PipelineStage::Execute, laneIndex, lane.OwnerThreadId, lane.VirtualThreadId, lane.FaultAddress, lane.FaultIsWrite, lane.PC, lane.CpuTranslationFault);
	}

	inline bool Processor::CPU_Core::TryResolveOldestOrderedWriteBackFaultLane(WriteBackStage const writeBackStage, unsigned char &laneIndex)
	{
		laneIndex = std::numeric_limits<unsigned char>::max();
		unsigned char faultMask = ResolveWriteBackFaultMask(writeBackStage);
		bool found = false;

		for (unsigned char candidateLaneIndex = 0; candidateLaneIndex < 8; candidateLaneIndex++)
		{
			if ((faultMask & (1 << candidateLaneIndex)) == 0)
			{
				continue;
			}

			if (!found || CompareWriteBackLaneOrder(writeBackStage, candidateLaneIndex, laneIndex) < 0)
			{
				laneIndex = candidateLaneIndex;
				found = true;
			}
		}

		return found;
	}

	inline bool Processor::CPU_Core::TryResolveOldestOrderedMemoryFaultLane(MemoryStage const memoryStage, unsigned char &laneIndex)
	{
		return TryResolveOldestOrderedMemoryLaneIndex(memoryStage, ResolveMemoryFaultMask(memoryStage), laneIndex);
	}

	inline bool Processor::CPU_Core::TryResolveOldestOrderedExecuteFaultLane(ExecuteStage const executeStage, unsigned char &laneIndex)
	{
		return TryResolveOldestOrderedExecuteLaneIndex(executeStage, ResolveExecuteFaultMask(executeStage), laneIndex);
	}

	inline bool Processor::CPU_Core::TryResolveOldestOrderedMemoryLaneIndex(MemoryStage const memoryStage, unsigned char laneMask, unsigned char &laneIndex)
	{
		laneIndex = std::numeric_limits<unsigned char>::max();
		bool found = false;

		for (unsigned char candidateLaneIndex = 0; candidateLaneIndex < 8; candidateLaneIndex++)
		{
			if ((laneMask & (1 << candidateLaneIndex)) == 0)
			{
				continue;
			}

			if (!found || CompareMemoryLaneOrder(memoryStage, candidateLaneIndex, laneIndex) < 0)
			{
				laneIndex = candidateLaneIndex;
				found = true;
			}
		}

		return found;
	}

	inline bool Processor::CPU_Core::TryResolveOldestOrderedExecuteLaneIndex(ExecuteStage const executeStage, unsigned char laneMask, unsigned char &laneIndex)
	{
		laneIndex = std::numeric_limits<unsigned char>::max();
		bool found = false;

		for (unsigned char candidateLaneIndex = 0; candidateLaneIndex < 8; candidateLaneIndex++)
		{
			if ((laneMask & (1 << candidateLaneIndex)) == 0)
			{
				continue;
			}

			if (!found || CompareExecuteLaneOrder(executeStage, candidateLaneIndex, laneIndex) < 0)
			{
				laneIndex = candidateLaneIndex;
				found = true;
			}
		}

		return found;
	}

	inline int Processor::CPU_Core::CompareMemoryLaneOrder(MemoryStage const memoryStage, unsigned char leftLaneIndex, unsigned char rightLaneIndex)
	{
		if (leftLaneIndex == rightLaneIndex)
		{
			return 0;
		}

		int leftOrderKey;
		int rightOrderKey;
		if (TryResolveMemoryLaneOrderKey(memoryStage, leftLaneIndex, leftOrderKey) && TryResolveMemoryLaneOrderKey(memoryStage, rightLaneIndex, rightOrderKey))
		{
			int compareResult = leftOrderKey < rightOrderKey ? -1 : (leftOrderKey > rightOrderKey ? 1 : 0);
			if (compareResult != 0)
			{
				return compareResult;
			}
		}

		return leftLaneIndex < rightLaneIndex ? -1 : (leftLaneIndex > rightLaneIndex ? 1 : 0);
	}

	inline bool Processor::CPU_Core::TryResolveMemoryLaneOrderKey(MemoryStage const memoryStage, unsigned char laneIndex, int &orderKey)
	{
		orderKey = laneIndex;
		if (!memoryStage.UsesExplicitPacketLanes)
		{
			return false;
		}

		ScalarMemoryLaneState lane = memoryStage.GetLane(laneIndex);
		if (!lane.IsOccupied || lane.SlotIndex >= 8)
		{
			return false;
		}

		orderKey = lane.SlotIndex;
		return true;
	}

	inline int Processor::CPU_Core::CompareExecuteLaneOrder(ExecuteStage const executeStage, unsigned char leftLaneIndex, unsigned char rightLaneIndex)
	{
		if (leftLaneIndex == rightLaneIndex)
		{
			return 0;
		}

		int leftOrderKey;
		int rightOrderKey;
		if (TryResolveExecuteLaneOrderKey(executeStage, leftLaneIndex, leftOrderKey) && TryResolveExecuteLaneOrderKey(executeStage, rightLaneIndex, rightOrderKey))
		{
			int compareResult = leftOrderKey < rightOrderKey ? -1 : (leftOrderKey > rightOrderKey ? 1 : 0);
			if (compareResult != 0)
			{
				return compareResult;
			}
		}

		return leftLaneIndex < rightLaneIndex ? -1 : (leftLaneIndex > rightLaneIndex ? 1 : 0);
	}

	inline bool Processor::CPU_Core::TryResolveExecuteLaneOrderKey(ExecuteStage const executeStage, unsigned char laneIndex, int &orderKey)
	{
		orderKey = laneIndex;
		if (!executeStage.UsesExplicitPacketLanes)
		{
			return false;
		}

		ScalarExecuteLaneState lane = executeStage.GetLane(laneIndex);
		if (!lane.IsOccupied || lane.SlotIndex >= 8)
		{
			return false;
		}

		orderKey = lane.SlotIndex;
		return true;
	}

	inline unsigned char Processor::CPU_Core::GetOccupiedScalarMemoryLaneMask(MemoryStage const memoryStage)
	{
		unsigned char occupiedMask = 0;

		if (memoryStage.Lane0.IsOccupied)
		{
			occupiedMask |= 1 << 0;
		}

		if (memoryStage.Lane1.IsOccupied)
		{
			occupiedMask |= 1 << 1;
		}

		if (memoryStage.Lane2.IsOccupied)
		{
			occupiedMask |= 1 << 2;
		}

		if (memoryStage.Lane3.IsOccupied)
		{
			occupiedMask |= 1 << 3;
		}

		return occupiedMask;
	}

	inline unsigned char Processor::CPU_Core::GetOccupiedLivePreciseExceptionExecuteLaneMask(ExecuteStage const executeStage)
	{
		unsigned char occupiedMask = GetOccupiedScalarExecuteLaneMask(executeStage);

		if (executeStage.Lane4.IsOccupied)
		{
			occupiedMask |= 1 << 4;
		}

		if (executeStage.Lane5.IsOccupied)
		{
			occupiedMask |= 1 << 5;
		}

		return occupiedMask;
	}

	inline unsigned char Processor::CPU_Core::GetOccupiedLivePreciseExceptionMemoryLaneMask(MemoryStage const memoryStage)
	{
		unsigned char occupiedMask = GetOccupiedScalarMemoryLaneMask(memoryStage);

		if (memoryStage.Lane4.IsOccupied)
		{
			occupiedMask |= 1 << 4;
		}

		if (memoryStage.Lane5.IsOccupied)
		{
			occupiedMask |= 1 << 5;
		}

		return occupiedMask;
	}

	std::shared_ptr<Core::TelemetryState> Processor::CPU_Core::PipelineControl::getTelemetry() const
	{
		return _telemetry = (_telemetry != nullptr) ? _telemetry : std::make_shared<Core::TelemetryState>();
	}

	Processor::CPU_Core::PipelineControl::PipelineControl(std::shared_ptr<Core::TelemetryState> telemetry)
	{
		ArgumentNullException::ThrowIfNull(telemetry);
		Enabled = false;
		Stalled = false;
		StallReason = PipelineStallKind::None;
		ClusterPreparedModeEnabled = false;
		_telemetry = telemetry;
	}

	Processor::CPU_Core::PipelineControl Processor::CPU_Core::PipelineControl::CreateSnapshot()
	{
		PipelineControl snapshot = *this;
		snapshot._telemetry = getTelemetry()->CreateSnapshot();
		return snapshot;
	}

