	void Processor::CPU_Core::PipelineControl::Clear()
	{
		Enabled = false;
		Stalled = false;
		StallReason = PipelineStallKind::None;
		ClusterPreparedModeEnabled = true;
		getTelemetry()->ClearPipeline();
	}

	unsigned long long Processor::CPU_Core::PipelineControl::GetClusterPreparedOpportunityCount()
	{
		return getWidePathSuccessCount() + getClusterModeFallbackCount();
	}

	double Processor::CPU_Core::PipelineControl::GetReferenceSequentialFallbackRate()
	{
		unsigned long long opportunityCount = GetClusterPreparedOpportunityCount();
		if (opportunityCount == 0)
		{
			return 0.0;
		}

		return static_cast<double>(getReferenceSequentialFallbackCount()) / static_cast<double>(opportunityCount);
	}

	bool Processor::CPU_Core::PipelineControl::ExceedsReferenceSequentialFallbackRateBudget()
	{
		unsigned long long opportunityCount = GetClusterPreparedOpportunityCount();
		return opportunityCount != 0 && GetReferenceSequentialFallbackRate() > ReferenceSequentialFallbackRateBudgetThreshold;
	}

	double Processor::CPU_Core::PipelineControl::GetIPC()
	{
		if (getCycleCount() == 0)
		{
			return 0.0;
		}
		return static_cast<double>(getInstructionsRetired()) / static_cast<double>(getCycleCount());
	}

	double Processor::CPU_Core::PipelineControl::GetEfficiency()
	{
		if (getCycleCount() == 0)
		{
			return 0.0;
		}
		return static_cast<double>(getCycleCount() - getStallCycles()) / static_cast<double>(getCycleCount());
	}

	double Processor::CPU_Core::PipelineControl::GetEffectiveIssueWidth()
	{
		unsigned long long activeCycles = getCycleCount() - getStallCycles();
		if (activeCycles == 0)
		{
			return 0.0;
		}
		return static_cast<double>(getInstructionsRetired()) / static_cast<double>(activeCycles);
	}

	double Processor::CPU_Core::PipelineControl::GetScalarIPC()
	{
		if (getCycleCount() == 0)
		{
			return 0.0;
		}
		return static_cast<double>(getScalarLanesRetired()) / static_cast<double>(getCycleCount());
	}

	double Processor::CPU_Core::PipelineControl::GetAverageRetiredWidth()
	{
		if (getRetireCycleCount() == 0)
		{
			return 0.0;
		}
		return static_cast<double>(getInstructionsRetired()) / static_cast<double>(getRetireCycleCount());
	}

