	void Processor::CPU_Core::ExecutePipelineCycle()
	{
		{
		std::scoped_lock<std::mutex> lock(liveSecureGate);
			if (liveSecureBusy || liveSecurePipelineActive || liveSecureMutationDepth != 0 || liveSecureParked || liveAdapterReservations->Depth != 0)
			{
				return;
			}
			liveAdapterReservations->Incarnation = std::any();
			liveSecurePipelineActive = true;
			liveSecurePipelineThread = static_cast<int>(std::hash<std::thread::id>{}(std::this_thread::get_id()));
		}
		try
		{
			ExecuteUnparkedPipelineCycle();
		}
		catch (...)
		{
			std::scoped_lock<std::mutex> lock(liveSecureGate);
			liveSecurePipelineThread = 0;
			liveAdapterReservations->Incarnation = std::any();
			liveSecurePipelineActive = false;
			throw;
		}
		{
			std::scoped_lock<std::mutex> lock(liveSecureGate);
			liveSecurePipelineThread = 0;
			liveAdapterReservations->Incarnation = std::any();
			liveSecurePipelineActive = false;
		}
	}

	void Processor::CPU_Core::ExecuteUnparkedPipelineCycle()
	{
		if (!pipeCtrl.Enabled)
		{
			return;
		}

		pipeCtrl.setCycleCount(pipeCtrl.getCycleCount() + 1);
		getCsr()->HardwareWrite(CsrAddresses::Cycle, pipeCtrl.getCycleCount());

		std::shared_ptr<MemorySubsystem> memorySubsystem = GetBoundMemorySubsystem();
		if (memorySubsystem != nullptr)
		{
			MemoryCyclePlatformOrchestrator::AdvanceCoreObservedPlatformEdge(memorySubsystem->getCycleController(), CoreID, pipeCtrl.getCycleCount());
		}

		RefreshInFlightExplicitMemoryProgress();
		RefreshInFlightSingleLaneLoadProgress();
	#if defined(TESTING)
		if (TestAfterMemoryProgressBeforeWriteBack != nullptr)
		{
			TestAfterMemoryProgressBeforeWriteBack->Invoke();
		}
	#endif

		// Older pipeline work must be allowed to drain before an ID-side RAW/WAW
		// interlock is evaluated. Returning on a load-use hazard while its producer
		// remains in EX/MEM permanently deadlocks the producer and consumer.
		PipelineStage_WriteBack();
		PipelineStage_Memory();

		PipelineCycleStallDecision hazardStallDecision = ResolvePipelineHazardStallDecision();
		if (hazardStallDecision.getShouldStall())
		{
			ApplyPipelineCycleStallDecision(hazardStallDecision);
			return;
		}

		pipeCtrl.Stalled = false;

		PipelineStage_Execute();
		DecodeStageResult decodeStageResult = PipelineStage_Decode();
		if (liveSecureParked)
		{
			return;
		}
		if (decodeStageResult.getShouldStall())
		{
			ApplyPipelineCycleStallDecision(PipelineCycleStallDecision::FromDecode(decodeStageResult));
			return;
		}

		PipelineStage_Fetch();

		RecordPhaseTimelineSample(L"CYCLE");

		Core::ReplayPhaseContext replayPhaseBeforeEndCycle = _loopBuffer.getCurrentReplayPhase();
		_loopBuffer.EndCycle();
		PublishReplayPhaseDeactivationToSchedulerIfNeeded(replayPhaseBeforeEndCycle);
	}

	inline void Processor::CPU_Core::ApplyPipelineCycleStallDecision(PipelineCycleStallDecision const stallDecision)
	{
		if (!stallDecision.getShouldStall())
		{
			return;
		}

		pipeCtrl.Stalled = true;
		pipeCtrl.StallReason = stallDecision.getStallReason();
		pipeCtrl.setStallCycles(pipeCtrl.getStallCycles() + 1);

		if (stallDecision.getCountMemoryStall())
		{
			pipeCtrl.setMemoryStalls(pipeCtrl.getMemoryStalls() + 1);
		}

		if (stallDecision.getCountInvariantViolation())
		{
			pipeCtrl.setInvariantViolationCount(pipeCtrl.getInvariantViolationCount() + 1);
		}

		if (stallDecision.getCountMshrScoreboardStall())
		{
			pipeCtrl.setMshrScoreboardStalls(pipeCtrl.getMshrScoreboardStalls() + 1);
		}

		if (stallDecision.getCountBankConflictStall())
		{
			pipeCtrl.setBankConflictStallCycles(pipeCtrl.getBankConflictStallCycles() + 1);
		}

		RecordPhaseTimelineSample(L"STALL");
	}

	inline void Processor::CPU_Core::PublishReplayPhaseDeactivationToSchedulerIfNeeded(Core::ReplayPhaseContext const replayPhaseBefore)
	{
		Core::ReplayPhaseContext replayPhaseAfter = _loopBuffer.getCurrentReplayPhase();
		if (!replayPhaseBefore.isActive() || replayPhaseAfter.isActive() || replayPhaseAfter.getLastInvalidationReason() == Core::ReplayPhaseInvalidationReason::None)
		{
			return;
		}

		if (_fspScheduler != nullptr)
		{
			_fspScheduler->SetReplayPhaseContext(replayPhaseAfter);
		}
	}

