	inline void Processor::CPU_Core::PublishReplayPhaseContextIfNeeded(std::shared_ptr<Core::MicroOpScheduler> scheduler, Core::ReplayPhaseContext const replayPhase)
	{
		if (scheduler == nullptr)
		{
			return;
		}

		if (replayPhase.isActive() || !ReplayPhaseContextsMatch(scheduler->getCurrentReplayPhase(), replayPhase))
		{
			scheduler->SetReplayPhaseContext(replayPhase);
		}
	}

	inline bool Processor::CPU_Core::ReplayPhaseContextsMatch(Core::ReplayPhaseContext const left, Core::ReplayPhaseContext const right)
	{
		return left.isActive() == right.isActive() && left.getEpochId() == right.getEpochId() && left.getCachedPc() == right.getCachedPc() && left.getEpochLength() == right.getEpochLength() && left.getCompletedReplays() == right.getCompletedReplays() && left.getValidSlotCount() == right.getValidSlotCount() && left.getStableDonorMask() == right.getStableDonorMask() && left.getLastInvalidationReason() == right.getLastInvalidationReason();
	}

