	Processor::CPU_Core::DecodeStageResult Processor::CPU_Core::RejectStaleDecodePreparation(unsigned long long currentBundlePc, std::shared_ptr<MainMemoryArea> memory)
	{
		// Outside source gates: older EX/MEM/WB and admitted history drain;
		// only unpublished preparation/nominations are discarded.
		bool preserveAdmissionProgress = PreserveProgressForSourceRefresh();
		DiscardUnpublishedDecodePreparation();
		getRuntime()->getDecode()->Decode.Clear();
		ResetDecodeAdmissionStateForBundle(currentBundlePc);
		InvalidateAllVliwFetchState(Core::ReplayPhaseInvalidationReason::CertificateMutation);
		getRuntime()->getReplay()->ObservedRelevantMemoryEpoch = memory->getReplayRelevantMutationEpoch();
		pipeIF.Clear();
			getRuntime()->getDecode()->BundleDecodedAndPacked = false;
		if (!preserveAdmissionProgress)
		{
			ResetCurrentDecodedBundleSlotCarrierState(currentBundlePc);
		}
		else
		{
			ClearCurrentDerivedIssuePlan(currentBundlePc);
		}
		return DecodeStageResult::NoProgress(currentBundlePc, DecodeStageDiagnosticsKind::NoInput);
	}

	Processor::CPU_Core::DecodeStageResult Processor::CPU_Core::CommitPreparedDecodeAdmission(unsigned long long currentBundlePc)
	{
		getRuntime()->getDecode()->Decode.Valid = true;

		unsigned char issuedSlots = 1;
		if (getRuntime()->getAdmission()->DecisionDraft.getUsesIssuePacketAsExecutionSource())
		{
			Core::BundleIssuePacket issuePacket = getRuntime()->getAdmission()->Handoff.getIssuePacket();
			auto dependencySummary = getRuntime()->getAdmission()->Handoff.getDependencySummary();
		unsigned char executableNonScalarPhysicalLaneMask = ResolveExecutableNonScalarPhysicalLaneMask(issuePacket, dependencySummary);
			int consumedCount = ResolveConsumedSlotCount(issuePacket, executableNonScalarPhysicalLaneMask);
			issuedSlots = consumedCount > 0 ? static_cast<unsigned char>(std::min(consumedCount, static_cast<int>(std::numeric_limits<unsigned char>::max()))) : static_cast<unsigned char>(1);
			if (consumedCount > 1)
			{
				pipeCtrl.setMultiSlotDecodeAdvanceCount(pipeCtrl.getMultiSlotDecodeAdvanceCount() + 1);
				AdvanceBundleSlotByConsumedCount(issuePacket, executableNonScalarPhysicalLaneMask);
			}
			else
			{
				AdvanceBundleSlot();
			}
		}
		else
		{
			AdvanceBundleSlot();
		}

		return DecodeStageResult::Issued(currentBundlePc, issuedSlots);
	}

	inline void Processor::CPU_Core::ResetDecodeAdmissionStateForBundle(unsigned long long bundlePc)
	{
		std::shared_ptr<Core::FspSourcePreparation> previous = std::dynamic_pointer_cast<Core::FspSourcePreparation>(getRuntime()->getAdmission()->SourcePreparation);
		if (previous != nullptr && previous->getBundlePc() != bundlePc)
		{
			WithdrawSourceFspNominations();
		}
		getRuntime()->getDecode()->ClusterPreparation = Core::ClusterIssuePreparation::CreateEmpty(bundlePc);
		getRuntime()->getAdmission()->Preparation = Core::RuntimeClusterAdmissionPreparation::CreateEmpty();
		getRuntime()->getAdmission()->CandidateView = Core::RuntimeClusterAdmissionCandidateView::CreateEmpty(bundlePc);
		getRuntime()->getAdmission()->DecisionDraft = Core::RuntimeClusterAdmissionDecisionDraft::CreateEmpty(bundlePc);
		getRuntime()->getAdmission()->Handoff = Core::RuntimeClusterAdmissionHandoff::CreateEmpty(bundlePc);
	}

	inline bool Processor::CPU_Core::TryResolveDecodeLocalStall(Core::DecodedBundleSlotDescriptor const currentSlotDescriptor, unsigned long long currentBundlePc, DecodeStageResult &decodeStageResult)
	{
		if (std::dynamic_pointer_cast<Core::TrapMicroOp>(currentSlotDescriptor.getMicroOp()) != nullptr)
		{
			decodeStageResult = YAKSys_Hybrid_CPU::Processor::CPU_Core::DecodeStageResult();
			return false;
		}

		if (currentSlotDescriptor.GetRuntimeAdmissionIsMemoryOp() && currentSlotDescriptor.GetRuntimeExecutionMemoryBankIntent() >= 0 && _fspScheduler != nullptr)
		{
			int bankId = currentSlotDescriptor.GetRuntimeExecutionMemoryBankIntent();
			int vtId = currentSlotDescriptor.GetRuntimeExecutionVirtualThreadId();
			if (_fspScheduler->IsBankPendingForVT(bankId, vtId))
			{
				decodeStageResult = DecodeStageResult::Stall(currentBundlePc, PipelineStallKind::MemoryWait, true, 1, DecodeStageDiagnosticsKind::BankPending);
				return true;
			}
		}

		decodeStageResult = YAKSys_Hybrid_CPU::Processor::CPU_Core::DecodeStageResult();
		return false;
	}

