// ORIGINAL LINE: [MethodImpl(MethodImplOptions.AggressiveInlining)] private void PublishCurrentFspDerivedIssuePlan(ulong pc, System.Collections.Generic.IReadOnlyList<Core.MicroOp?> carrierBundle)
	inline void Processor::CPU_Core::PublishCurrentFspDerivedIssuePlan(unsigned long long pc, const std::vector<std::shared_ptr<Core::MicroOp>> &carrierBundle)
	{
		if (carrierBundle.empty() || carrierBundle.size() != 8)
		{
			return;
		}

		Core::DecodedBundleTransportFacts transportFacts = BuildDecodedBundleTransportFacts(pc, carrierBundle, Core::DecodedBundleStateKind::ForegroundMutated, Core::DecodedBundleStateOrigin::FspPacking);
		Core::DecodedBundleRuntimeState runtimeState = Core::DecodedBundleRuntimeState::CreateEmpty(0);
		ReadCurrentDecodedBundleRuntimeState(runtimeState);
		PublishCurrentDerivedIssuePlanRuntimeState(runtimeState.ApplyFspPacking(transportFacts));
	}

	inline void Processor::CPU_Core::PublishCurrentForegroundSlotMutation(unsigned char slotIndex, std::shared_ptr<Core::MicroOp> microOp)
	{
		Core::DecodedBundleRuntimeState currentExecutionRuntimeState = Core::DecodedBundleRuntimeState::CreateEmpty(0);
		ReadCurrentExecutionDecodedBundleRuntimeState(currentExecutionRuntimeState);
		Core::DecodedBundleTransportFacts currentExecutionTransportFacts = currentExecutionRuntimeState.getTransportFacts();

		if (slotIndex >= 8 || slotIndex >= currentExecutionTransportFacts.getSlots().size())
		{
			return;
		}

		Core::DecodedBundleTransportFacts mutatedTransportFacts = Core::DecodedBundleSlotCarrierBuilder::BuildTransportFactsFromSingleSlotMutationContour(currentExecutionTransportFacts.getPC(), currentExecutionTransportFacts.getSlots(), slotIndex, microOp);
		if (getRuntime()->getDecode()->DerivedIssuePlan.MatchesBundlePc(currentExecutionTransportFacts.getPC()))
		{
			PublishCurrentDerivedIssuePlanRuntimeState(currentExecutionRuntimeState.ApplySingleSlotMutation(mutatedTransportFacts), true);
			return;
		}

		PublishCurrentDecodedBundleRuntimeState(currentExecutionRuntimeState.ApplySingleSlotMutation(mutatedTransportFacts), true);
	}

	inline void Processor::CPU_Core::ConsumeForegroundBundleSlotIfNonEmpty(unsigned char slotIndex)
	{
		ConsumeDecodedBundleProgressSlotIfNonEmpty(slotIndex);
	}

	inline void Processor::CPU_Core::ConsumeForegroundBundleIssuePacketSlots(Core::BundleIssuePacket issuePacket, unsigned char executableNonScalarPhysicalLaneMask)
	{
		unsigned char consumedSlotMask = ResolveConsumedDecodedBundleSlotMask(issuePacket, executableNonScalarPhysicalLaneMask);
		ConsumeDecodedBundleProgressMask(consumedSlotMask, getRuntime()->getDecode()->PipelineBundleSlot);
	}

