	inline void Processor::CPU_Core::AdvanceBundleSlot()
	{
		unsigned char consumedSlotIndex = getRuntime()->getDecode()->PipelineBundleSlot;
		ConsumeForegroundBundleSlotIfNonEmpty(consumedSlotIndex);

		unsigned char nextSlotIndex;
		if (TryGetNextRemainingBundleSlot(consumedSlotIndex, nextSlotIndex))
		{
			getRuntime()->getDecode()->PipelineBundleSlot = nextSlotIndex;
			return;
		}

		getRuntime()->getDecode()->PipelineBundleSlot = 8;
		pipeIF.Valid = false;
		AdvanceActiveLivePc(256);
	}

	inline int Processor::CPU_Core::ResolveConsumedSlotCount(Core::BundleIssuePacket issuePacket, unsigned char executableNonScalarPhysicalLaneMask)
	{
		return issuePacket.getPreparedScalarLaneCount() + std::popcount(static_cast<unsigned int>(executableNonScalarPhysicalLaneMask));
	}

	inline void Processor::CPU_Core::AdvanceBundleSlotByConsumedCount(Core::BundleIssuePacket issuePacket, unsigned char executableNonScalarPhysicalLaneMask)
	{
		unsigned char currentSlotIndex = getRuntime()->getDecode()->PipelineBundleSlot;
		ConsumeForegroundBundleIssuePacketSlots(issuePacket, executableNonScalarPhysicalLaneMask);

		unsigned char nextSlotIndex;
		if (TryGetNextRemainingBundleSlot(currentSlotIndex, nextSlotIndex))
		{
			getRuntime()->getDecode()->PipelineBundleSlot = nextSlotIndex;
			return;
		}

		getRuntime()->getDecode()->PipelineBundleSlot = 8;
		pipeIF.Valid = false;
		AdvanceActiveLivePc(256);
	}

	inline bool Processor::CPU_Core::TryGetNextRemainingBundleSlot(unsigned char currentSlotIndex, unsigned char &slotIndex)
	{
		slotIndex = 0;

		Core::DecodedBundleTransportFacts transportFacts;
		ReadCurrentExecutionDecodedBundleTransportFacts(transportFacts);
		Core::BundleProgressState progressState = EnsureDecodedBundleProgressStateForTransportFacts(transportFacts);

		if (progressState.getHasRemaining())
		{
			slotIndex = progressState.getNextSlotIndex();
			return true;
		}

		return false;
	}

	inline Core::BundleProgressState Processor::CPU_Core::EnsureDecodedBundleProgressStateForTransportFacts(Core::DecodedBundleTransportFacts const transportFacts)
	{
		Core::BundleProgressState progressState = getRuntime()->getDecode()->BundleProgress;
		if (progressState.getBundlePc() != transportFacts.getPC())
		{
			progressState = Core::BundleProgressState::CreateForCursor(transportFacts.getPC(), transportFacts.getValidNonEmptyMask(), getRuntime()->getDecode()->PipelineBundleSlot);
			getRuntime()->getDecode()->BundleProgress = progressState;
		}

		return progressState;
	}

	inline void Processor::CPU_Core::ConsumeDecodedBundleProgressSlotIfNonEmpty(unsigned char slotIndex)
	{
		Core::DecodedBundleTransportFacts transportFacts;
		ReadCurrentForegroundDecodedBundleTransportFacts(transportFacts);
		if (slotIndex >= 8 || slotIndex >= transportFacts.getSlots().size())
		{
			return;
		}

		// Passed NOP/empty positions are progress too. A later source
		// refresh must not introduce a new operation behind the cursor.
		ConsumeDecodedBundleProgressMask(static_cast<unsigned char>(1 << slotIndex), slotIndex);
	}

	inline void Processor::CPU_Core::ConsumeDecodedBundleProgressMask(unsigned char consumedSlotMask, unsigned char currentSlotIndex)
	{
		if (consumedSlotMask == 0)
		{
			return;
		}

		Core::DecodedBundleTransportFacts transportFacts;
		ReadCurrentExecutionDecodedBundleTransportFacts(transportFacts);
		Core::BundleProgressState progressState = EnsureDecodedBundleProgressStateForTransportFacts(transportFacts);
		getRuntime()->getDecode()->BundleProgress = progressState.ConsumeMask(consumedSlotMask, currentSlotIndex);
	}

	inline unsigned char Processor::CPU_Core::ResolveConsumedDecodedBundleSlotMask(Core::BundleIssuePacket issuePacket, unsigned char executableNonScalarPhysicalLaneMask)
	{
		Core::DecodedBundleTransportFacts transportFacts;
		ReadCurrentForegroundDecodedBundleTransportFacts(transportFacts);
		unsigned char consumedSlotMask = 0;

		for (unsigned char laneIndex = 0; laneIndex < 8; laneIndex++)
		{
			if (!ShouldMaterializeIssuePacketLane(issuePacket, laneIndex, executableNonScalarPhysicalLaneMask))
			{
				continue;
			}

			Core::IssuePacketLane lane = issuePacket.GetPhysicalLane(laneIndex);
			if (!lane.isOccupied() || lane.getSlotIndex() >= 8 || lane.getSlotIndex() >= transportFacts.getSlots().size())
			{
				continue;
			}

			Core::DecodedBundleSlotDescriptor slotDescriptor = transportFacts.getSlots()[lane.getSlotIndex()];
			if (!slotDescriptor.isValid() || slotDescriptor.GetRuntimeExecutionIsEmptyOrNop())
			{
				continue;
			}

			consumedSlotMask |= static_cast<unsigned char>(1 << lane.getSlotIndex());
		}

		return consumedSlotMask;
	}

	inline void Processor::CPU_Core::RecordClusterPathProbeDiagnostics(Core::RuntimeClusterAdmissionCandidateView candidateView, Core::RuntimeClusterAdmissionDecisionDraft decisionDraft)
	{
		if (!decisionDraft.getShouldProbeClusterPath())
		{
			return;
		}

		pipeCtrl.setClusterProbeCount(pipeCtrl.getClusterProbeCount() + 1);
		pipeCtrl.setClusterProbeRefinedWidthSum(pipeCtrl.getClusterProbeRefinedWidthSum() + static_cast<unsigned long long>(candidateView.getRefinedAdvisoryScalarIssueWidth()));

		if (candidateView.getSuggestsFallbackDiagnostics())
		{
			pipeCtrl.setClusterProbeNarrowFallbackCount(pipeCtrl.getClusterProbeNarrowFallbackCount() + 1);
		}
	}

