	void Processor::CPU_Core::RetireWindowBatch::CaptureVectorTransferEffect(std::shared_ptr<Core::VectorTransferRetireEffect> vectorTransferEffect)
	{
		ArgumentNullException::ThrowIfNull(vectorTransferEffect);
		if (_vectorTransferEffectCount >= _vectorTransferEffects.size() || _vectorTransferEffectCount >= std::numeric_limits<unsigned char>::max())
		{
			throw InvalidOperationException(L"Retire batch canonical vector-transfer payload capacity exceeded.");
		}

// C# TO C++ CONVERTER TASK: There is no C++ equivalent to 'checked' in this context:
// ORIGINAL LINE: byte vectorTransferEffectSlot = checked((byte)_vectorTransferEffectCount++);
		unsigned char vectorTransferEffectSlot = static_cast<unsigned char>(_vectorTransferEffectCount)++;
		_vectorTransferEffects[vectorTransferEffectSlot] = vectorTransferEffect;
		AppendEffect(RetireWindowEffect::VectorTransfer(vectorTransferEffectSlot));
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureGeneratedCsrEffect(unsigned char laneIndex, int virtualThreadId, Core::CsrRetireEffect const csrEffect)
	{
		CaptureSingletonTypedSideEffect(laneIndex, RetireWindowTypedEffectKind::Csr);
		CPU_Core::EmitGeneratedCsrRetireRecords(virtualThreadId, csrEffect, _retireRecords, _retireRecordCount);
		AppendEffect(RetireWindowEffect::Csr(csrEffect));
	}

