	void Processor::CPU_Core::RetireWindowBatch::CaptureGeneratedAtomicEffect(unsigned char laneIndex, ScalarWriteBackLaneState const traceLane, Core::AtomicRetireEffect const atomicEffect)
	{
		CaptureAtomicSideEffect(laneIndex);
		AppendEffect(RetireWindowEffect::Atomic(atomicEffect, RetiredTraceLaneSnapshot::FromLane(traceLane), true));
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureGeneratedSystemEvent(unsigned char laneIndex, Core::SystemEventKind systemEventKind, Core::SystemEventOrderGuarantee orderGuarantee, unsigned long long retiredPc, int virtualThreadId)
	{
		CaptureSingletonTypedSideEffect(laneIndex, RetireWindowTypedEffectKind::System);
		if (orderGuarantee == Core::SystemEventOrderGuarantee::FullSerialTrapBoundary)
		{
			NoteSerializingBoundary();
		}

		AppendEffect(RetireWindowEffect::System(systemEventKind, orderGuarantee, retiredPc, virtualThreadId));
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureGeneratedPipelineEvent(unsigned char laneIndex, std::shared_ptr<Core::Pipeline::PipelineEvent> pipelineEvent, Core::SystemEventOrderGuarantee orderGuarantee, unsigned long long retiredPc, int virtualThreadId)
	{
		ArgumentNullException::ThrowIfNull(pipelineEvent);
		if (std::dynamic_pointer_cast<Core::Pipeline::TrapEntryEvent>(pipelineEvent) != nullptr)
		{
			CaptureRetireVisibleSingletonTypedSideEffect(laneIndex, RetireWindowTypedEffectKind::System);
		}
		else
		{
			CaptureSingletonTypedSideEffect(laneIndex, RetireWindowTypedEffectKind::System);
		}

		if (orderGuarantee == Core::SystemEventOrderGuarantee::FullSerialTrapBoundary)
		{
			NoteSerializingBoundary();
		}

		if (static_cast<unsigned int>(_pipelineEventCount) >= static_cast<unsigned int>(_pipelineEvents.size()))
		{
			throw InvalidOperationException(L"WB pipeline-event payload buffer exhausted.");
		}

		unsigned char pipelineEventSlot = static_cast<unsigned char>(_pipelineEventCount)++;
		_pipelineEvents[pipelineEventSlot] = pipelineEvent;
		AppendEffect(RetireWindowEffect::PipelineEvent(pipelineEventSlot, orderGuarantee, retiredPc, virtualThreadId));
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureGeneratedVmxEffect(unsigned char laneIndex, ScalarWriteBackLaneState const traceLane, Core::VmxRetireEffect const vmxEffect)
	{
		CaptureSingletonTypedSideEffect(laneIndex, RetireWindowTypedEffectKind::Vmx);
		AppendEffect(RetireWindowEffect::Vmx(vmxEffect, traceLane.VirtualThreadId, RetiredTraceLaneSnapshot::FromLane(traceLane), true));
	}

	void Processor::CPU_Core::RetireWindowBatch::EmitMicroOpRetireRecords(std::shared_ptr<Processor::CPU_Core> &core, ScalarWriteBackLaneState const lane)
	{
		if (lane.MicroOp == nullptr)
		{
			throw InvalidOperationException(L"WB retire lane is missing MicroOp authority.");
		}

		lane.MicroOp->CapturePrimaryWriteBackResult(lane.ResultValue);
		int firstLaneRecord = _retireRecordCount;
		lane.MicroOp->EmitWriteBackRetireRecords(core, _retireRecords, _retireRecordCount);
		// Freeze identity from the actual records already captured by
		// this batch, using the same owner as generated-record lanes.
		// This does not emit or publish a second RegisterWrite.
		for (int i = firstLaneRecord; i < _retireRecordCount; i++)
		{
			core->CompleteIssuedScalarRetireRecord(lane, _retireRecords[i]);
		}
	}

	void Processor::CPU_Core::RetireWindowBatch::NoteSerializingBoundary()
	{
		if (_serializingBoundaryCaptured)
		{
			return;
		}

		AppendEffect(RetireWindowEffect::SerializingBoundary());
		_serializingBoundaryCaptured = true;
	}

	void Processor::CPU_Core::RetireWindowBatch::AccumulateAssistBoundaryKilled(bool killed)
	{
		_assistBoundaryKilledThisRetireWindow |= killed;
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureRetireWindowCsrEffect(Core::CsrRetireEffect const csrEffect)
	{
		CaptureRetireWindowSingletonTypedSideEffect(RetireWindowTypedEffectKind::Csr);
		AppendEffect(RetireWindowEffect::Csr(csrEffect));
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureRetireWindowAtomicEffect(Core::AtomicRetireEffect const atomicEffect)
	{
		if (_atomicEffectCaptured)
		{
			throw InvalidOperationException(L"Retire batch encountered multiple Atomic retire-window effects.");
		}

		_atomicEffectCaptured = true;
		AppendEffect(RetireWindowEffect::Atomic(atomicEffect, YAKSys_Hybrid_CPU::Processor::CPU_Core::RetiredTraceLaneSnapshot(), false));
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureRetireWindowPipelineEvent(std::shared_ptr<Core::Pipeline::PipelineEvent> pipelineEvent, Core::SystemEventOrderGuarantee orderGuarantee, unsigned long long retiredPc, int virtualThreadId, bool serializingBoundaryFollowThrough)
	{
		ArgumentNullException::ThrowIfNull(pipelineEvent);
		CaptureRetireWindowSingletonTypedSideEffect(RetireWindowTypedEffectKind::System);

		if (static_cast<unsigned int>(_pipelineEventCount) >= static_cast<unsigned int>(_pipelineEvents.size()))
		{
			throw InvalidOperationException(L"Retire batch pipeline-event payload buffer exhausted.");
		}

		unsigned char pipelineEventSlot = static_cast<unsigned char>(_pipelineEventCount)++;
		_pipelineEvents[pipelineEventSlot] = pipelineEvent;
		AppendEffect(RetireWindowEffect::PipelineEvent(pipelineEventSlot, orderGuarantee, retiredPc, virtualThreadId));

		if (orderGuarantee == Core::SystemEventOrderGuarantee::FullSerialTrapBoundary || serializingBoundaryFollowThrough)
		{
			NoteSerializingBoundary();
		}
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureRetireWindowVmxEffect(Core::VmxRetireEffect const vmxEffect, int virtualThreadId)
	{
		CaptureRetireWindowSingletonTypedSideEffect(RetireWindowTypedEffectKind::Vmx);
		AppendEffect(RetireWindowEffect::Vmx(vmxEffect, virtualThreadId, YAKSys_Hybrid_CPU::Processor::CPU_Core::RetiredTraceLaneSnapshot(), false));
		NoteSerializingBoundary();
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureRetireWindowScalarMemoryStore(unsigned long long memoryAddress, unsigned long long memoryData, unsigned char memoryAccessSize)
	{
		CaptureRetireWindowSingletonTypedSideEffect(RetireWindowTypedEffectKind::ScalarMemoryStore);
		AppendEffect(RetireWindowEffect::ScalarMemoryStore(memoryAddress, memoryData, memoryAccessSize));
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureRetireWindowPredicateState(unsigned char predicateRegisterId, unsigned long long predicateMaskValue)
	{
		CaptureRetireWindowSingletonTypedSideEffect(RetireWindowTypedEffectKind::PredicateState);
		AppendEffect(RetireWindowEffect::PredicateState(predicateRegisterId, predicateMaskValue));
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureRetireWindowVectorStreamDirty(int virtualThreadId)
	{
		if (static_cast<unsigned int>(virtualThreadId) < 32)
		{
			unsigned int vtMask = 1u << virtualThreadId;
			if ((_vectorStreamDirtyVtMask & vtMask) != 0)
			{
				return;
			}

			_vectorStreamDirtyVtMask |= vtMask;
		}

		AppendEffect(RetireWindowEffect::VectorStreamDirty(virtualThreadId));
	}

	void Processor::CPU_Core::RetireWindowBatch::AppendEffect(RetireWindowEffect const effect)
	{
		if (static_cast<unsigned int>(_effectCount) >= static_cast<unsigned int>(_effects.size()))
		{
			throw InvalidOperationException(L"WB retire-window effect buffer exhausted.");
		}

		new (&_effects[_effectCount++]) RetireWindowEffect(effect);
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureRetireWindowSingletonTypedSideEffect(RetireWindowTypedEffectKind effectKind)
	{
		if (_typedEffectKind != RetireWindowTypedEffectKind::None)
		{
			throw InvalidOperationException(L"Retire batch encountered multiple singleton typed retire-window effects.");
		}

		_typedEffectKind = effectKind;
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureSingletonTypedSideEffect(unsigned char laneIndex, RetireWindowTypedEffectKind effectKind)
	{
		if (_typedEffectKind != RetireWindowTypedEffectKind::None)
		{
			throw InvalidOperationException(L"WB retire window encountered multiple singleton typed effects.");
		}

		if (laneIndex != 7)
		{
			throw InvalidOperationException(L"WB retire window singleton typed effect was published from a non-lane7 carrier.");
		}

		_typedEffectKind = effectKind;
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureRetireVisibleSingletonTypedSideEffect(unsigned char laneIndex, RetireWindowTypedEffectKind effectKind)
	{
		if (_typedEffectKind != RetireWindowTypedEffectKind::None)
		{
			throw InvalidOperationException(L"WB retire window encountered multiple singleton typed effects.");
		}

		if (laneIndex >= 6 && laneIndex != 7)
		{
			throw InvalidOperationException(L"WB retire window singleton typed effect was published from a non-retire-visible carrier.");
		}

		_typedEffectKind = effectKind;
	}

	void Processor::CPU_Core::RetireWindowBatch::CaptureAtomicSideEffect(unsigned char laneIndex)
	{
		if (_atomicEffectCaptured)
		{
			throw InvalidOperationException(L"WB retire window encountered multiple Atomic typed effects.");
		}

		if (laneIndex >= 6)
		{
			throw InvalidOperationException(L"WB retire window Atomic effect was published from a non-retire-visible carrier.");
		}

		_atomicEffectCaptured = true;
	}

