	void Processor::CPU_Core::RegisterMatrixTileReplayJournal(std::shared_ptr<MatrixTileReplayRollbackJournal> journal)
	{
		auto &journals = getRuntime()->getExtensions()->MatrixTileReplayJournals;
		unsigned long long checkpointOrdinal = journal->getReplayIdentity()->CheckpointOrdinal;
		if (!journals.emplace(checkpointOrdinal, journal).second)
		{
			throw MatrixTileReplayRollbackValidationException(L"MTILE replay checkpoint ordinal is already registered.");
		}
	}

	bool Processor::CPU_Core::OwnsMatrixTileReplayJournal(std::shared_ptr<MatrixTileReplayRollbackJournal> journal)
	{
		auto &journals = getRuntime()->getExtensions()->MatrixTileReplayJournals;
// C# TO C++ CONVERTER WARNING: Nullable reference types have no equivalent in C++:
// ORIGINAL LINE: return _matrixTileReplayJournals != null && _matrixTileReplayJournals.TryGetValue(journal.ReplayIdentity.CheckpointOrdinal, out MatrixTileReplayRollbackJournal? registered) && ReferenceEquals(registered, journal);
		auto it = journals.find(journal->getReplayIdentity()->CheckpointOrdinal);
		return it != journals.end() && it->second == journal;
	}

	void Processor::CPU_Core::ReleaseMatrixTileReplayJournal(std::shared_ptr<MatrixTileReplayRollbackJournal> journal)
	{
	// C# TO C++ CONVERTER TASK: There is no C++ equivalent to the C# 'null-forgiving operator':
	// ORIGINAL LINE: if (!OwnsMatrixTileReplayJournal(journal) || !_matrixTileReplayJournals!.Remove( journal.ReplayIdentity.CheckpointOrdinal))
		auto &journals = getRuntime()->getExtensions()->MatrixTileReplayJournals;
		if (!OwnsMatrixTileReplayJournal(journal) || journals.erase(journal->getReplayIdentity()->CheckpointOrdinal) == 0)
		{
			throw MatrixTileReplayRollbackValidationException(L"MTILE replay journal release requires the registered core-owned journal.");
		}
	}

	void Processor::CPU_Core::ApplyLiveCpuStateWithStableCoreIdentity(std::shared_ptr<Processor::CPU_Core::LiveCpuStateAdapter> liveState)
	{
		// RF-11.33: keep the legacy ref ABI local while preserving the sole
		// reference-owned runtime identity and ApplyTo statement order.
		std::shared_ptr<CPU_Core> stableCoreIdentity = shared_from_this();
		liveState->ApplyTo(stableCoreIdentity);
	}

	inline std::optional<std::shared_ptr<Core::Pipeline::PipelineEvent>> Processor::CPU_Core::MaterializeSystemEventWithStableCoreIdentity(std::shared_ptr<Core::SysEventMicroOp> systemEventMicroOp)
	{
		if (systemEventMicroOp->getEventKind() == Core::SystemEventKind::Ecall)
		{
			int vtId = NormalizePipelineStateVtId(systemEventMicroOp->getOwnerThreadId());
			unsigned long long ecallCode = GetRegisterValueWithForwarding(vtId, static_cast<unsigned short>(17));
			std::shared_ptr<Core::Pipeline::EcallEvent> temp_var = std::make_shared<Core::Pipeline::EcallEvent>();
			temp_var->VtId = static_cast<unsigned char>(vtId);
			temp_var->BundleSerial = 0;
// C# TO C++ CONVERTER TASK: There is no C++ equivalent to 'unchecked' in this context:
// ORIGINAL LINE: temp_var.EcallCode = unchecked((long)ecallCode);
			temp_var->EcallCode = static_cast<long long>(ecallCode);
			return temp_var;
		}

		// RF-11.34: retain ECALL's architectural a7 read and the legacy
		// ref ABI without passing the value-type facade instance itself.
		std::shared_ptr<CPU_Core> stableCoreIdentity = shared_from_this();
		return systemEventMicroOp->CreatePipelineEvent(stableCoreIdentity);
	}

	inline Core::CsrRetireEffect Processor::CPU_Core::MaterializeCsrEffectWithStableCoreIdentity(std::shared_ptr<Core::CSRMicroOp> csrMicroOp)
	{
		// RF-11.35: retain CSR surface resolution/read timing while
		// localizing the legacy ref facade ABI.
		std::shared_ptr<CPU_Core> stableCoreIdentity = shared_from_this();
		return csrMicroOp->CreateRetireEffect(stableCoreIdentity);
	}

