	inline void Processor::CPU_Core::PublishRetiredWriteBackLaneForwarding(ScalarWriteBackLaneState const lane)
	{
		if (!lane.WritesRegister)
		{
			return;
		}

		getRuntime()->getExecution()->WriteBackForwarding.Valid = true;
		getRuntime()->getExecution()->WriteBackForwarding.DestRegID = lane.DestRegID;
		getRuntime()->getExecution()->WriteBackForwarding.ForwardedValue = lane.ResultValue;
	}

	inline void Processor::CPU_Core::CaptureRetiredWriteBackLaneEffects(RetireWindowBatch &retireBatch, unsigned char laneIndex, ScalarWriteBackLaneState const lane)
	{
		if (laneIndex >= 6 && laneIndex != 7 && std::dynamic_pointer_cast<Core::MatrixTileMicroOp>(lane.MicroOp) == nullptr)
		{
			return;
		}

		if (lane.MicroOp == nullptr)
		{
			throw InvalidOperationException(std::format("Live WB retire lane {} is missing MicroOp authority.", static_cast<unsigned int>(laneIndex)));
		}

		int generatedRetireRecordCount = GetGeneratedRetireRecordCount(lane);
		if (generatedRetireRecordCount != 0)
		{
			ValidateGeneratedRetireLaneContract(lane);
			AppendLaneGeneratedRetireRecords(retireBatch, lane);
		}
		else
		{
			if (lane.GeneratedCsrEffect.has_value())
			{
				retireBatch.CaptureGeneratedCsrEffect(laneIndex, lane.VirtualThreadId, lane.GeneratedCsrEffect.value());
			}
			else
			{
				std::shared_ptr<Core::VConfigMicroOp> vectorConfigMicroOp = std::dynamic_pointer_cast<Core::VConfigMicroOp>(lane.MicroOp);
				if (vectorConfigMicroOp != nullptr)
				{
					Core::VectorConfigRetireEffect vectorConfigEffect = vectorConfigMicroOp->CreateRetireEffect();
					if (vectorConfigEffect.isValid())
					{
						retireBatch.CaptureGeneratedVectorConfigEffect(laneIndex, lane.VirtualThreadId, vectorConfigEffect);
					}
					else
					{
						EmitBatchMicroOpRetireRecordsWithStableCoreIdentity(retireBatch, lane);
					}
				}
				else
				{
					if (lane.GeneratedAtomicEffect.has_value())
					{
						retireBatch.CaptureGeneratedAtomicEffect(laneIndex, lane, lane.GeneratedAtomicEffect.value());
					}
					else
					{
						std::shared_ptr<Core::VectorTransferMicroOp> vectorTransferMicroOp = std::dynamic_pointer_cast<Core::VectorTransferMicroOp>(lane.MicroOp);
						if (vectorTransferMicroOp != nullptr && vectorTransferMicroOp->getHasControllerRetireEffect())
						{
							retireBatch.CaptureVectorTransferEffect(vectorTransferMicroOp->CreateRetireEffect());
						}
						else
						{
							EmitBatchMicroOpRetireRecordsWithStableCoreIdentity(retireBatch, lane);
						}
					}
				}
			}
		}

		if (lane.GeneratedVmxEffect.has_value() && !IsExactHypercallPendingCanonicalRetire(lane.MicroOp))
		{
			retireBatch.CaptureGeneratedVmxEffect(laneIndex, lane, lane.GeneratedVmxEffect.value());
		}

		if (lane.MicroOp->getSerializationClass() == Arch::SerializationClass::FullSerial || lane.MicroOp->getSerializationClass() == Arch::SerializationClass::VmxSerial)
		{
			retireBatch.NoteSerializingBoundary();
		}

		if (lane.GeneratedEvent.has_value() && lane.GeneratedEvent.value() != nullptr)
		{
			auto generatedEvent = lane.GeneratedEvent.value();
			std::shared_ptr<Core::SysEventMicroOp> systemEventMicroOp = std::dynamic_pointer_cast<Core::SysEventMicroOp>(lane.MicroOp);
			Core::SystemEventOrderGuarantee orderGuarantee = systemEventMicroOp != nullptr ? systemEventMicroOp->getOrderGuarantee() : ResolveRetiredSystemEventOrderGuaranteeForTesting(generatedEvent);

			if (std::dynamic_pointer_cast<Core::Pipeline::EcallEvent>(generatedEvent) != nullptr)
			{
				// ECALL carries the exact architectural a7/x17 code captured at EX.
				// Reducing it to SystemEventKind would reconstruct a zero-code event
				// at retire and silently bypass the platform ECALL bridge.
				retireBatch.CaptureGeneratedPipelineEvent(laneIndex, generatedEvent, orderGuarantee, lane.PC, lane.VirtualThreadId);
			}
			else
			{
				std::shared_ptr<Core::SysEventMicroOp> typedSystemEventMicroOp = std::dynamic_pointer_cast<Core::SysEventMicroOp>(lane.MicroOp);
				if (typedSystemEventMicroOp != nullptr)
				{
					retireBatch.CaptureGeneratedSystemEvent(laneIndex, typedSystemEventMicroOp->getEventKind(), orderGuarantee, lane.PC, lane.VirtualThreadId);
				}
				else
				{
					retireBatch.CaptureGeneratedPipelineEvent(laneIndex, generatedEvent, orderGuarantee, lane.PC, lane.VirtualThreadId);
				}
			}

			std::shared_ptr<Core::PostStageBIssuedAttempt> issuedAttempt = std::dynamic_pointer_cast<Core::PostStageBIssuedAttempt>(lane.PostStageBIssuedAttempt);
			std::shared_ptr<Core::Pipeline::TrapEntryEvent> trapEntry = std::dynamic_pointer_cast<Core::Pipeline::TrapEntryEvent>(generatedEvent);
			if (trapEntry != nullptr && issuedAttempt != nullptr)
			{
				std::shared_ptr<Core::Decoder::VliwOperationId> operationId = issuedAttempt->getScheduledOperation()->getOperationId();
				if (operationId->VirtualThreadId != lane.VirtualThreadId || issuedAttempt->getScheduledOperation()->getPhysicalLane() != laneIndex || trapEntry->VtId != lane.VirtualThreadId || trapEntry->BundleSerial != operationId->WorkingBundleSequence)
				{
					throw InvalidOperationException(L"Canonical trap completion identity diverged from its live Stage-B carrier.");
				}

				retireBatch.CaptureArchitecturalCompletionCandidate(std::make_shared<Core::ArchitecturalCompletionCandidate>(lane.DomainTag, lane.OwnerContextId, lane.VirtualThreadId, operationId->OperationAttempt, Core::ArchitecturalCompletionEventIdentity::Create(operationId->WorkingBundleSequence, operationId->WorkingSlotIndex), Core::NeutralArchitecturalCompletionFacts{Core::NeutralArchitecturalCompletionClass::TrapEntry, Core::NeutralScalarFact::Present(trapEntry->CauseCode), Core::NeutralScalarFact{}, trapEntry->HasFaultAddress ? Core::NeutralAddressFact::Present(trapEntry->FaultAddress, trapEntry->FaultAddressSemantic) : Core::NeutralAddressFact{}, Core::NeutralAuxiliaryFact{}}));
			}
		}

		if (IsVectorStreamDirtyRetireOpcode(lane.OpCode))
		{
			retireBatch.CaptureRetireWindowVectorStreamDirty(lane.VirtualThreadId);
		}

		if (lane.DefersStoreCommitToWriteBack)
		{
			retireBatch.AppendDeferredStoreLane(laneIndex);
		}

	}

	inline void Processor::CPU_Core::FinalizeRetiredWriteBackLane(RetireWindowBatch &retireBatch, unsigned char laneIndex, ScalarWriteBackLaneState const lane)
	{
		getRuntime()->getRetire()->LastRetiredLaneIndex = laneIndex;
		getRuntime()->getRetire()->LastRetiredOpcode = lane.OpCode;
		getRuntime()->getRetire()->LastRetiredWritesRegister = lane.WritesRegister;
		getRuntime()->getRetire()->LastRetiredDestinationRegister = lane.DestRegID;
		getRuntime()->getRetire()->LastRetiredResultValue = lane.ResultValue;
		getRuntime()->getRetire()->LastRetiredMicroOpType = lane.MicroOp != nullptr ? lane.MicroOp->GetDescription() : L"";
		getRuntime()->getRetire()->LastRetiredMicroOpDescription = getRuntime()->getRetire()->LastRetiredMicroOpType;

		std::shared_ptr<Core::VmxMicroOp> vmx = std::dynamic_pointer_cast<Core::VmxMicroOp>(lane.MicroOp);
		if (vmx != nullptr && vmx->getExactHypercallRetireGrant() != nullptr)
		{
			ConsumeExactHypercallRetireGrant(vmx);
		}

		if ((!lane.GeneratedVmxEffect.has_value() || vmx != nullptr) && !lane.GeneratedAtomicEffect.has_value())
		{
			RecordTraceEvent(lane.PC, lane.OpCode, ResolveRetiredTraceValue(lane), lane.OwnerThreadId, lane.VirtualThreadId, lane.WasFspInjected, lane.OriginalThreadId);
		}

		getRuntime()->getTelemetry()->InstructionsRetired++;
		if (laneIndex < 4)
		{
			getRuntime()->getTelemetry()->ScalarLanesRetired++;
		}
		else
		{
			getRuntime()->getTelemetry()->NonScalarLanesRetired++;
		}

		ReleaseRetiredWriteBackLaneBookkeeping(laneIndex);

		if (lane.WasFspInjected && lane.OwnerThreadId != lane.OriginalThreadId && _fspScheduler != nullptr)
		{
			_fspScheduler->ReleaseSpeculationBudget();
		}

		if (getVectorConfig()->getFSPEnabled() == 1 && lane.MicroOp != nullptr && lane.MicroOp->getOwnerThreadId() != 0)
		{
// C# TO C++ CONVERTER NOTE: The following 'using' block is replaced by its C++ equivalent:
// ORIGINAL LINE: using var vectorAccess = ReserveCanonicalCoreWrite(null);
			{
				auto vectorAccess = ReserveCanonicalCoreWrite(nullptr);
				getRuntime()->getArchitectural()->VectorConfig.FSP_InjectionCount++;
			}
		}
	}

	inline void Processor::CPU_Core::PrevalidateRetireWindowBatchForPublication(RetireWindowBatch &retireBatch, std::span<const RetireWindowEffect> capturedRetireEffects)
	{
		getRetireCoordinator()->Prevalidate(retireBatch.getRetireRecords());

		for (std::size_t i = 0; i < capturedRetireEffects.size(); i++)
		{
			RetireWindowEffect retireEffect = capturedRetireEffects[i];
			switch (retireEffect.getKind())
			{
				case RetireWindowEffectKind::DeferredStoreCommit:
					PrevalidateDeferredStoreEffect(retireEffect.getDeferredStoreLaneIndex());
					break;

				case RetireWindowEffectKind::Csr:
					PrevalidateCsrEffect(retireEffect.getCsrEffect());
					break;

				case RetireWindowEffectKind::VectorConfig:
					PrevalidateVectorConfigEffect(retireEffect.getVectorConfigEffect());
					break;

				case RetireWindowEffectKind::Atomic:
					PrevalidateAtomicEffect(retireEffect.getAtomicEffect());
					break;

				case RetireWindowEffectKind::System:
					PrevalidateSystemEffect(retireEffect.getSystemEventKind(), retireEffect.getSystemEventOrderGuarantee(), retireEffect.getSystemEventVtId());
					break;

				case RetireWindowEffectKind::PipelineEvent:
					retireBatch.GetPipelineEventPayload(retireEffect.getPipelineEventSlot());
					PrevalidateSystemOrderAndVt(retireEffect.getSystemEventOrderGuarantee(), retireEffect.getSystemEventVtId(), L"pipeline-event retire effect");
					break;

				case RetireWindowEffectKind::Vmx:
					PrevalidateVmxEffect(retireEffect.getVmxEffect(), retireEffect.getVmxEffectVtId());
					break;

				case RetireWindowEffectKind::ScalarMemoryStore:
					PrevalidateScalarStoreEffect(retireEffect.getMemoryAddress(), retireEffect.getMemoryAccessSize(), L"Retire batch direct scalar store");
					break;

				case RetireWindowEffectKind::PredicateState:
					if (retireEffect.getPredicateRegisterId() > 15)
					{
						throw InvalidOperationException(std::format("Retire batch predicate effect targets invalid predicate register {}.", static_cast<unsigned int>(retireEffect.getPredicateRegisterId())));
					}
					break;

				case RetireWindowEffectKind::VectorStreamDirty:
					PrevalidateVirtualThreadId(retireEffect.getVectorStreamDirtyVtId(), L"vector-stream-dirty retire effect");
					break;

				case RetireWindowEffectKind::VectorTransfer:
					PrevalidateVectorTransferEffect(retireBatch.GetVectorTransferEffectPayload(retireEffect.getVectorTransferEffectSlot()));
					break;

				case RetireWindowEffectKind::SerializingBoundary:
					break;

				default:
					throw InvalidOperationException(L"Retire batch carries unsupported effect kind.");
			}
		}
	}

	inline void Processor::CPU_Core::PrevalidateDeferredStoreEffect(unsigned char laneIndex)
	{
		if (laneIndex >= 8)
		{
			throw InvalidOperationException(std::format("Retire batch deferred store names invalid WB lane {}.", static_cast<unsigned int>(laneIndex)));
		}

		ScalarWriteBackLaneState lane = getRuntime()->getMemoryPipeline()->WriteBack.GetLane(laneIndex);
		if (!lane.IsOccupied || !lane.DefersStoreCommitToWriteBack || !lane.IsMemoryOp || lane.IsLoad)
		{
			throw InvalidOperationException(std::format("Retire batch deferred store lane {} is not a live deferred scalar store carrier.", static_cast<unsigned int>(laneIndex)));
		}

		PrevalidateScalarStoreEffect(lane.MemoryAddress, lane.MemoryAccessSize, std::format(L"Retired store lane {}", static_cast<unsigned int>(lane.LaneIndex)));
	}

	inline void Processor::CPU_Core::PrevalidateCsrEffect(Core::CsrRetireEffect const csrEffect)
	{
		if (!csrEffect.getClearsArchitecturalExceptionState() && !csrEffect.getHasCsrWrite() && !csrEffect.getHasRegisterWriteback())
		{
			throw InvalidOperationException(L"Retire batch carries an empty CSR effect.");
		}

		if (csrEffect.getHasRegisterWriteback() && static_cast<unsigned int>(csrEffect.getDestRegId()) >= static_cast<unsigned int>(RenameMap::ArchRegs))
		{
			throw InvalidOperationException(std::format("Retire batch CSR effect targets invalid architectural register {}.", static_cast<unsigned int>(csrEffect.getDestRegId())));
		}

// C# TO C++ CONVERTER TASK: The following 'is' operator pattern is not converted by C# to C++ Converter:
		if (csrEffect.getHasCsrWrite() && csrEffect.getStorageSurface() != Core::CsrStorageSurface::VectorPodPlane && csrEffect.getStorageSurface() != Core::CsrStorageSurface::WiredCsrFile)
		{
			throw InvalidOperationException(L"Retire batch CSR write has no supported storage surface.");
		}
	}

	inline void Processor::CPU_Core::PrevalidateVectorConfigEffect(Core::VectorConfigRetireEffect const vectorConfigEffect)
	{
		if (!vectorConfigEffect.isValid() || vectorConfigEffect.getTailAgnostic() > 1 || vectorConfigEffect.getMaskAgnostic() > 1 || (vectorConfigEffect.getHasRegisterWriteback() && vectorConfigEffect.getDestinationRegister() >= RenameMap::ArchRegs))
		{
			throw InvalidOperationException(L"Retire batch carries an invalid vector-config effect.");
		}
	}

	inline void Processor::CPU_Core::PrevalidateAtomicEffect(Core::AtomicRetireEffect const atomicEffect)
	{
// C# TO C++ CONVERTER TASK: There is no C++ equivalent to 'unchecked' in this context:
// ORIGINAL LINE: if (!atomicEffect.IsValid || atomicEffect.CoreId != unchecked((ushort)CoreID) || atomicEffect.AccessSize != Core.Memory.MainMemoryAtomicMemoryUnit.ResolveAccessSize(atomicEffect.Opcode) || (atomicEffect.HasRegisterDestination && atomicEffect.DestinationRegister >= RenameMap.ArchRegs))
		if (!atomicEffect.isValid() || atomicEffect.getCoreId() != static_cast<unsigned short>(CoreID) || atomicEffect.getAccessSize() != Core::Memory::MainMemoryAtomicMemoryUnit::ResolveAccessSize(atomicEffect.getOpcode()) || (atomicEffect.getHasRegisterDestination() && atomicEffect.getDestinationRegister() >= RenameMap::ArchRegs))
		{
			throw InvalidOperationException(L"Retire batch carries an invalid atomic effect.");
		}

		PrevalidateVirtualThreadId(atomicEffect.getVirtualThreadId(), L"atomic retire effect");
		PrevalidateScalarStoreEffect(atomicEffect.getAddress(), atomicEffect.getAccessSize(), L"Atomic retire effect");
	}

	inline void Processor::CPU_Core::PrevalidateVmxEffect(Core::VmxRetireEffect const vmxEffect, int virtualThreadId)
	{
		if (!vmxEffect.isValid() || (vmxEffect.getHasRegisterDestination() && vmxEffect.getRegisterDestination() >= RenameMap::ArchRegs))
		{
			throw InvalidOperationException(L"Retire batch carries an invalid VMX effect.");
		}

		PrevalidateVirtualThreadId(virtualThreadId, L"VMX retire effect");
	}

	inline void Processor::CPU_Core::PrevalidateSystemEffect(Core::SystemEventKind systemEventKind, Core::SystemEventOrderGuarantee orderGuarantee, int virtualThreadId)
	{
		if (static_cast<unsigned int>(systemEventKind) > static_cast<unsigned int>(Core::SystemEventKind::VtBarrier))
		{
			throw InvalidOperationException(L"Retire batch carries unsupported system-event kind.");
		}

		PrevalidateSystemOrderAndVt(orderGuarantee, virtualThreadId, L"system retire effect");
	}

	inline void Processor::CPU_Core::PrevalidateSystemOrderAndVt(Core::SystemEventOrderGuarantee orderGuarantee, int virtualThreadId, const std::wstring &effectDescription)
	{
		if (static_cast<unsigned int>(orderGuarantee) > static_cast<unsigned int>(Core::SystemEventOrderGuarantee::FullSerialTrapBoundary))
		{
			throw InvalidOperationException(L"Retire batch carries an unsupported ordering guarantee.");
		}

		PrevalidateVirtualThreadId(virtualThreadId, effectDescription);
	}

	inline void Processor::CPU_Core::PrevalidateScalarStoreEffect(unsigned long long memoryAddress, unsigned char memoryAccessSize, const std::wstring &effectDescription)
	{
		unsigned char accessSize = NormalizeScalarMemoryAccessSize(memoryAccessSize);
// C# TO C++ CONVERTER TASK: The following 'is' operator pattern is not converted by C# to C++ Converter:
		if ((accessSize != 1 && accessSize != 2 && accessSize != 4 && accessSize != 8) || !IsScalarMemoryAccessInBounds(memoryAddress, accessSize))
		{
			throw InvalidOperationException(std::wstring(effectDescription) + L" carries invalid memory publication payload.");
		}
	}

	inline void Processor::CPU_Core::PrevalidateVirtualThreadId(int virtualThreadId, const std::wstring &effectDescription)
	{
		if (static_cast<unsigned int>(virtualThreadId) >= SmtWays)
		{
			throw InvalidOperationException(L"Retire batch targets an invalid virtual thread.");
		}
	}

