	inline void Processor::CPU_Core::ApplyRetireBatchImmediateEffects(RetireWindowBatch &retireBatch, std::span<const RetireWindowEffect> capturedRetireEffects, bool countRetireCycle, bool &hasRetiredPcWrite, unsigned long long &retiredPcWriteTarget, int &retiredPcWriteVtId)
	{
		hasRetiredPcWrite = TryResolveSingleRetiredPcWrite(retireBatch.getRetireRecords(), retiredPcWriteTarget, retiredPcWriteVtId);

		if (countRetireCycle)
		{
			getRuntime()->getTelemetry()->RetireCycleCount++;
		}

		getRetireCoordinator()->Retire(retireBatch.getRetireRecords());

		for (std::size_t i = 0; i < capturedRetireEffects.size(); i++)
		{
			RetireWindowEffect retireEffect = capturedRetireEffects[i];
			switch (retireEffect.getKind())
			{
				case RetireWindowEffectKind::DeferredStoreCommit:
					ApplyRetiredScalarStoreCommit(getRuntime()->getMemoryPipeline()->WriteBack.GetLane(retireEffect.getDeferredStoreLaneIndex()));
					break;

				case RetireWindowEffectKind::Csr:
					ApplyRetiredCsrEffect(retireEffect.getCsrEffect());
					break;

				case RetireWindowEffectKind::VectorConfig:
					ApplyRetiredVectorConfigEffect(retireEffect.getVectorConfigEffect());
					break;

				case RetireWindowEffectKind::Atomic:
				{
					// Atomic retirement is intentionally split: first apply the bound
					// memory-side effect and reservation discipline, then publish any
					// returned architectural destination value through RetireCoordinator.
					Core::AtomicRetireOutcome retiredAtomicOutcome = ApplyRetiredAtomicEffect(retireEffect.getAtomicEffect());
					if (retiredAtomicOutcome.getHasRegisterWriteback())
					{
						getRetireCoordinator()->Retire(RetireRecord::RegisterWrite(retireEffect.getAtomicEffect().getVirtualThreadId(), retiredAtomicOutcome.getRegisterDestination(), retiredAtomicOutcome.getRegisterWritebackValue()));
					}

					if (retireEffect.getHasAtomicTraceLane())
					{
						RecordTraceEvent(retireEffect.getAtomicTraceLane().getPC(), retireEffect.getAtomicTraceLane().getOpCode(), retiredAtomicOutcome.getHasRegisterWriteback() ? retiredAtomicOutcome.getRegisterWritebackValue() : retireEffect.getAtomicTraceLane().getFallbackValue(), retireEffect.getAtomicTraceLane().getOwnerThreadId(), retireEffect.getAtomicTraceLane().getVirtualThreadId(), retireEffect.getAtomicTraceLane().getWasFspInjected(), retireEffect.getAtomicTraceLane().getOriginalThreadId());
					}

					break;
				}

				case RetireWindowEffectKind::ScalarMemoryStore:
					ApplyRetiredScalarStoreCommit(retireEffect.getMemoryAddress(), retireEffect.getMemoryData(), retireEffect.getMemoryAccessSize(), L"Retire batch direct scalar store");
					break;

				case RetireWindowEffectKind::PredicateState:
					SetPredicateRegister(retireEffect.getPredicateRegisterId(), retireEffect.getPredicateMaskValue());
					break;

				case RetireWindowEffectKind::VectorStreamDirty:
					break;

				case RetireWindowEffectKind::VectorTransfer:
					ApplyRetiredVectorTransferEffect(retireBatch.GetVectorTransferEffectPayload(retireEffect.getVectorTransferEffectSlot()));
					break;
			}
		}
	}

	inline void Processor::CPU_Core::ApplyRetiredVectorTransferEffect(std::shared_ptr<Core::VectorTransferRetireEffect> vectorTransferEffect)
	{
		std::vector<unsigned char> packedData = vectorTransferEffect->CopyPackedData();
		for (unsigned long long element = 0; element < vectorTransferEffect->getElementCount(); element++)
		{
// C# TO C++ CONVERTER TASK: There is no C++ equivalent to 'checked' in this context:
// ORIGINAL LINE: ulong destinationAddress = checked(vectorTransferEffect.DestinationAddress + checked(element * vectorTransferEffect.Stride));
			unsigned long long destinationAddress = vectorTransferEffect->getDestinationAddress() + element * vectorTransferEffect->getStride();
// C# TO C++ CONVERTER TASK: There is no C++ equivalent to 'checked' in this context:
// ORIGINAL LINE: int offset = checked((int)(element * (ulong)vectorTransferEffect.ElementSize));
			int offset = static_cast<int>(element * static_cast<unsigned long long>(vectorTransferEffect->getElementSize()));
			std::vector<unsigned char> elementData(packedData.begin() + offset, packedData.begin() + offset + vectorTransferEffect->getElementSize());
			WriteBoundMainMemoryExact(destinationAddress, elementData, L"Canonical vector-transfer selected-retire publication");
			if (GetBoundMemorySubsystem() != nullptr)
			{
				GetBoundMemorySubsystem()->getCycleController()->RecordCommittedDataWriteBytes(vectorTransferEffect->getElementSize());
			}
		}
	}

	inline bool Processor::CPU_Core::HasRetiredActiveControlFlowRedirect(bool hasRetiredPcWrite, int retiredPcWriteVtId)
	{
		return hasRetiredPcWrite && NormalizePipelineStateVtId(retiredPcWriteVtId) == ReadActiveVirtualThreadId();
	}

