	inline void Processor::CPU_Core::ApplyRetireBatchLateEffectsAndRedirect(RetireWindowBatch &retireBatch, std::span<const RetireWindowEffect> capturedRetireEffects, bool hasRetiredPcWrite, unsigned long long retiredPcWriteTarget, int retiredPcWriteVtId)
	{
		for (std::size_t i = 0; i < capturedRetireEffects.size(); i++)
		{
			RetireWindowEffect retireEffect = capturedRetireEffects[i];
			if (retireEffect.getKind() != RetireWindowEffectKind::Vmx)
			{
				continue;
			}

			Core::VmxRetireOutcome retiredVmxOutcome = ApplyRetiredVmxEffect(retireEffect.getVmxEffect(), retireEffect.getVmxEffectVtId());
			retireBatch.AccumulateAssistBoundaryKilled(retiredVmxOutcome.FlushesPipeline);

			if (retireEffect.getHasVmxTraceLane())
			{
				RecordTraceEvent(retireEffect.getVmxTraceLane().getPC(), retireEffect.getVmxTraceLane().getOpCode(), retiredVmxOutcome.HasRegisterWriteback ? retiredVmxOutcome.RegisterWritebackValue : retireEffect.getVmxTraceLane().getFallbackValue(), retireEffect.getVmxTraceLane().getOwnerThreadId(), retireEffect.getVmxTraceLane().getVirtualThreadId(), retireEffect.getVmxTraceLane().getWasFspInjected(), retireEffect.getVmxTraceLane().getOriginalThreadId());
			}
		}

		for (std::size_t i = 0; i < capturedRetireEffects.size(); i++)
		{
			RetireWindowEffect retireEffect = capturedRetireEffects[i];
			if (retireEffect.getKind() != RetireWindowEffectKind::PipelineEvent)
			{
				continue;
			}

			retireBatch.AccumulateAssistBoundaryKilled(HandleRetiredSystemEventBoundary(retireBatch.GetPipelineEventPayload(retireEffect.getPipelineEventSlot()), retireEffect.getSystemEventOrderGuarantee(), retireEffect.getSystemEventPc(), retireEffect.getSystemEventVtId()));
		}

		for (std::size_t i = 0; i < capturedRetireEffects.size(); i++)
		{
			RetireWindowEffect retireEffect = capturedRetireEffects[i];
			if (retireEffect.getKind() != RetireWindowEffectKind::System)
			{
				continue;
			}

			retireBatch.AccumulateAssistBoundaryKilled(HandleRetiredSystemEventBoundary(retireEffect.getSystemEventKind(), retireEffect.getSystemEventOrderGuarantee(), retireEffect.getSystemEventPc(), retireEffect.getSystemEventVtId()));
		}

		for (std::size_t i = 0; i < capturedRetireEffects.size(); i++)
		{
			if (capturedRetireEffects[i].getKind() != RetireWindowEffectKind::SerializingBoundary)
			{
				continue;
			}

			HandleRetiredSerializingBoundary(retireBatch.getAssistBoundaryKilledThisRetireWindow());
		}

		if (HasRetiredActiveControlFlowRedirect(hasRetiredPcWrite, retiredPcWriteVtId))
		{
			FlushPipeline(Core::AssistInvalidationReason::PipelineFlush);
			RedirectActiveExecutionForControlFlow(retiredPcWriteTarget);
		}
	}

	inline void Processor::CPU_Core::HandleRetiredSerializingBoundary(bool assistBoundaryKilledThisRetireWindow)
	{
		AdvanceReplayCodeGenerationEpoch(true);
		if (_loopBuffer.getCurrentReplayPhase().isActive())
		{
			_loopBuffer.Invalidate(Core::ReplayPhaseInvalidationReason::SerializingEvent);
			if (_fspScheduler != nullptr)
			{
				_fspScheduler->SetReplayPhaseContext(_loopBuffer.getCurrentReplayPhase(), false);
			}
		}

		if (_fspScheduler != nullptr)
		{
			_fspScheduler->NotifySerializingCommit(false);
		}
		if (!assistBoundaryKilledThisRetireWindow)
		{
			InvalidateAssistRuntime(Core::AssistInvalidationReason::SerializingBoundary);
		}
	}

	inline bool Processor::CPU_Core::TryResolveSingleRetiredPcWrite(std::span<const RetireRecord> retireRecords, unsigned long long &retiredPcWriteTarget, int &retiredPcWriteVtId)
	{
		retiredPcWriteTarget = 0;
		retiredPcWriteVtId = 0;
		bool hasRetiredPcWrite = false;

		for (int i = 0; i < retireRecords.size(); i++)
		{
			RetireRecord retireRecord = retireRecords[i];
			if (!retireRecord.isPcWrite())
			{
				continue;
			}

			if (hasRetiredPcWrite)
			{
				throw InvalidOperationException(L"Retire packet published multiple PcWrite records. Control-flow redirect authority must remain singular per retire window.");
			}

			hasRetiredPcWrite = true;
			retiredPcWriteTarget = retireRecord.getValue();
			retiredPcWriteVtId = retireRecord.getVtId();
		}

		return hasRetiredPcWrite;
	}

	inline bool Processor::CPU_Core::IsVectorStreamDirtyRetireOpcode(unsigned int opcode)
	{
		if ((opcode == IsaOpcodeValues::VSTORE || opcode == IsaOpcodeValues::VSCATTER || opcode == IsaOpcodeValues::VPOPC || opcode == IsaOpcodeValues::STREAM_WAIT))
		{
			return false;
		}

		if ((opcode == IsaOpcodeValues::VSETVEXCPMASK || opcode == IsaOpcodeValues::VSETVEXCPPRI || opcode == IsaOpcodeValues::STREAM_SETUP || opcode == IsaOpcodeValues::STREAM_START))
		{
			return true;
		}

		return OpcodeRegistry::IsVectorOp(opcode);
	}

	inline void Processor::CPU_Core::ApplyRetiredSystemEvent(Core::SystemEventKind systemEventKind, unsigned long long retiredPc, int virtualThreadId)
	{
		int normalizedVtId = NormalizePipelineStateVtId(virtualThreadId);
		if (systemEventKind == Core::SystemEventKind::Sev)
		{
			for (int vt = 0; vt < SmtWays; vt++)
			{
				bool isIssuer = vt == normalizedVtId;
				if (!isIssuer && ReadVirtualThreadPipelineState(vt) != YAKSys_Hybrid_CPU::Core::PipelineState::WaitForEvent)
				{
					continue;
				}

			std::optional<unsigned long long> eventPc = isIssuer ? std::optional<unsigned long long>(retiredPc) : std::nullopt;
			ApplySystemEventKindToVirtualThread(systemEventKind, vt, eventPc);
			}

			return;
		}

		std::optional<unsigned long long> eventPc = retiredPc;
		ApplySystemEventKindToVirtualThread(systemEventKind, normalizedVtId, eventPc);
	}

	inline void Processor::CPU_Core::ApplyRetiredSystemEvent(std::shared_ptr<Core::Pipeline::PipelineEvent> systemEvent, unsigned long long retiredPc, int virtualThreadId)
	{
		ArgumentNullException::ThrowIfNull(systemEvent);
		ApplyRetiredPipelineEvent(systemEvent, retiredPc, virtualThreadId);
	}

	inline void Processor::CPU_Core::ApplyRetiredPipelineEvent(std::shared_ptr<Core::Pipeline::PipelineEvent> pipelineEvent, unsigned long long retiredPc, int virtualThreadId)
	{
		ArgumentNullException::ThrowIfNull(pipelineEvent);
		int normalizedVtId = NormalizePipelineStateVtId(virtualThreadId);
		if (std::dynamic_pointer_cast<Core::Pipeline::SevEvent>(pipelineEvent) != nullptr)
		{
			for (int vt = 0; vt < SmtWays; vt++)
			{
				bool isIssuer = vt == normalizedVtId;
				if (!isIssuer && ReadVirtualThreadPipelineState(vt) != YAKSys_Hybrid_CPU::Core::PipelineState::WaitForEvent)
				{
					continue;
				}

			std::optional<unsigned long long> eventPc = isIssuer ? std::optional<unsigned long long>(retiredPc) : std::nullopt;
			ApplyPipelineEventToVirtualThread(pipelineEvent, vt, eventPc);
			}

			return;
		}

		std::optional<unsigned long long> eventPc = retiredPc;
		ApplyPipelineEventToVirtualThread(pipelineEvent, normalizedVtId, eventPc);
	}

	inline bool Processor::CPU_Core::HandleRetiredSystemEventBoundary(Core::SystemEventKind systemEventKind, Core::SystemEventOrderGuarantee orderGuarantee, unsigned long long retiredPc, int virtualThreadId)
	{
		Core::AssistInvalidationReason invalidationReason = ResolveAssistInvalidationReasonForRetiredSystemEvent(systemEventKind, orderGuarantee);

		if (RequiresRetiredSystemEventPipelineFlush(orderGuarantee))
		{
			FlushPipeline(invalidationReason == Core::AssistInvalidationReason::None ? Core::AssistInvalidationReason::PipelineFlush : invalidationReason);
		}
		else if (invalidationReason != Core::AssistInvalidationReason::None)
		{
			InvalidateAssistRuntime(invalidationReason);
		}

		if (systemEventKind == Core::SystemEventKind::FenceI)
		{
			InvalidateAllVliwFetchState(Core::ReplayPhaseInvalidationReason::SerializingEvent);
		}

		ApplyRetiredSystemEvent(systemEventKind, retiredPc, virtualThreadId);
		return invalidationReason != Core::AssistInvalidationReason::None;
	}

	inline bool Processor::CPU_Core::HandleRetiredSystemEventBoundary(std::shared_ptr<Core::Pipeline::PipelineEvent> systemEvent, Core::SystemEventOrderGuarantee orderGuarantee, unsigned long long retiredPc, int virtualThreadId)
	{
		ArgumentNullException::ThrowIfNull(systemEvent);
		return HandleRetiredPipelineEventBoundary(systemEvent, orderGuarantee, retiredPc, virtualThreadId);
	}

	inline bool Processor::CPU_Core::HandleRetiredPipelineEventBoundary(std::shared_ptr<Core::Pipeline::PipelineEvent> pipelineEvent, Core::SystemEventOrderGuarantee orderGuarantee, unsigned long long retiredPc, int virtualThreadId)
	{
		ArgumentNullException::ThrowIfNull(pipelineEvent);
		Core::AssistInvalidationReason invalidationReason = ResolveAssistInvalidationReasonForRetiredPipelineEvent(pipelineEvent, orderGuarantee);

		if (RequiresRetiredSystemEventPipelineFlush(orderGuarantee))
		{
			FlushPipeline(invalidationReason == Core::AssistInvalidationReason::None ? Core::AssistInvalidationReason::PipelineFlush : invalidationReason);
		}
		else if (invalidationReason != Core::AssistInvalidationReason::None)
		{
			InvalidateAssistRuntime(invalidationReason);
		}

		if (IsInstructionFence(pipelineEvent))
		{
			InvalidateAllVliwFetchState(Core::ReplayPhaseInvalidationReason::SerializingEvent);
		}

		ApplyRetiredPipelineEvent(pipelineEvent, retiredPc, virtualThreadId);
		return invalidationReason != Core::AssistInvalidationReason::None;
	}

	void Processor::CPU_Core::ApplyRetiredSystemEventForTesting(std::shared_ptr<Core::Pipeline::PipelineEvent> systemEvent, int virtualThreadId, unsigned long long retiredPc)
	{
		HandleRetiredSystemEventBoundary(systemEvent, ResolveRetiredSystemEventOrderGuaranteeForTesting(systemEvent), retiredPc, virtualThreadId);
	}

