	inline PrivilegeLevel Processor::CPU_Core::ResolveRetiredSystemEventPrivilege(int virtualThreadId)
	{
		int normalizedVtId = NormalizePipelineStateVtId(virtualThreadId);
		return static_cast<unsigned int>(normalizedVtId) < static_cast<unsigned int>(getArchContexts()->size()) ? (*getArchContexts())[normalizedVtId]->getCurrentPrivilege() : PrivilegeLevel::Machine;
	}

	inline bool Processor::CPU_Core::RequiresRetiredSystemEventPipelineFlush(Core::SystemEventOrderGuarantee orderGuarantee)
	{
		return orderGuarantee == Core::SystemEventOrderGuarantee::FlushPipeline || orderGuarantee == Core::SystemEventOrderGuarantee::FullSerialTrapBoundary;
	}

	inline bool Processor::CPU_Core::IsInstructionFence(std::shared_ptr<Core::Pipeline::PipelineEvent> pipelineEvent)
	{
		auto fenceEvent = std::dynamic_pointer_cast<Core::Pipeline::FenceEvent>(pipelineEvent);
		return fenceEvent != nullptr && fenceEvent->IsInstructionFence;
	}

	inline Core::AssistInvalidationReason Processor::CPU_Core::ResolveAssistInvalidationReasonForRetiredSystemEvent(Core::SystemEventKind systemEventKind, Core::SystemEventOrderGuarantee orderGuarantee)
	{
		switch (systemEventKind)
		{
			case Core::SystemEventKind::Fence:
			case Core::SystemEventKind::FenceI:
				return Core::AssistInvalidationReason::Fence;
			case Core::SystemEventKind::Ecall:
			case Core::SystemEventKind::Ebreak:
			case Core::SystemEventKind::Mret:
			case Core::SystemEventKind::Sret:
				return Core::AssistInvalidationReason::Trap;
			default:
				return orderGuarantee == Core::SystemEventOrderGuarantee::FullSerialTrapBoundary
					? Core::AssistInvalidationReason::Trap
					: Core::AssistInvalidationReason::None;
		}
	}

	inline Core::AssistInvalidationReason Processor::CPU_Core::ResolveAssistInvalidationReasonForRetiredSystemEvent(std::shared_ptr<Core::Pipeline::PipelineEvent> systemEvent, Core::SystemEventOrderGuarantee orderGuarantee)
	{
		ArgumentNullException::ThrowIfNull(systemEvent);
		return ResolveAssistInvalidationReasonForRetiredSystemEvent(ResolveRetiredSystemEventKind(systemEvent), orderGuarantee);
	}

	inline Core::AssistInvalidationReason Processor::CPU_Core::ResolveAssistInvalidationReasonForRetiredPipelineEvent(std::shared_ptr<Core::Pipeline::PipelineEvent> pipelineEvent, Core::SystemEventOrderGuarantee orderGuarantee)
	{
		ArgumentNullException::ThrowIfNull(pipelineEvent);
		const bool isSystemBoundary =
			std::dynamic_pointer_cast<Core::Pipeline::FenceEvent>(pipelineEvent) != nullptr ||
			std::dynamic_pointer_cast<Core::Pipeline::EcallEvent>(pipelineEvent) != nullptr ||
			std::dynamic_pointer_cast<Core::Pipeline::EbreakEvent>(pipelineEvent) != nullptr ||
			std::dynamic_pointer_cast<Core::Pipeline::MretEvent>(pipelineEvent) != nullptr ||
			std::dynamic_pointer_cast<Core::Pipeline::SretEvent>(pipelineEvent) != nullptr ||
			std::dynamic_pointer_cast<Core::Pipeline::WfiEvent>(pipelineEvent) != nullptr ||
			std::dynamic_pointer_cast<Core::Pipeline::WfeEvent>(pipelineEvent) != nullptr ||
			std::dynamic_pointer_cast<Core::Pipeline::SevEvent>(pipelineEvent) != nullptr;
		if (isSystemBoundary)
		{
			return ResolveAssistInvalidationReasonForRetiredSystemEvent(
				ResolveRetiredSystemEventKind(pipelineEvent), orderGuarantee);
		}

		return orderGuarantee == Core::SystemEventOrderGuarantee::FullSerialTrapBoundary
			? Core::AssistInvalidationReason::Trap
			: Core::AssistInvalidationReason::None;
	}

	inline Core::SystemEventOrderGuarantee Processor::CPU_Core::ResolveRetiredSystemEventOrderGuaranteeForTesting(std::shared_ptr<Core::Pipeline::PipelineEvent> systemEvent)
	{
		if (const auto fenceEvent = std::dynamic_pointer_cast<Core::Pipeline::FenceEvent>(systemEvent))
		{
			return fenceEvent->IsInstructionFence
				? Core::SystemEventOrderGuarantee::FlushPipeline
				: Core::SystemEventOrderGuarantee::DrainMemory;
		}
		if (std::dynamic_pointer_cast<Core::Pipeline::EcallEvent>(systemEvent) != nullptr ||
			std::dynamic_pointer_cast<Core::Pipeline::EbreakEvent>(systemEvent) != nullptr ||
			std::dynamic_pointer_cast<Core::Pipeline::TrapEntryEvent>(systemEvent) != nullptr ||
			std::dynamic_pointer_cast<Core::Pipeline::MretEvent>(systemEvent) != nullptr ||
			std::dynamic_pointer_cast<Core::Pipeline::SretEvent>(systemEvent) != nullptr)
		{
			return Core::SystemEventOrderGuarantee::FullSerialTrapBoundary;
		}
		if (std::dynamic_pointer_cast<Core::Pipeline::WfiEvent>(systemEvent) != nullptr ||
			std::dynamic_pointer_cast<Core::Pipeline::WfeEvent>(systemEvent) != nullptr ||
			std::dynamic_pointer_cast<Core::Pipeline::SevEvent>(systemEvent) != nullptr)
		{
			return Core::SystemEventOrderGuarantee::DrainMemory;
		}
		return Core::SystemEventOrderGuarantee::None;
	}

	inline Core::SystemEventKind Processor::CPU_Core::ResolveRetiredSystemEventKind(std::shared_ptr<Core::Pipeline::PipelineEvent> systemEvent)
	{
		ArgumentNullException::ThrowIfNull(systemEvent);
		if (const auto fenceEvent = std::dynamic_pointer_cast<Core::Pipeline::FenceEvent>(systemEvent))
		{
			return fenceEvent->IsInstructionFence ? Core::SystemEventKind::FenceI : Core::SystemEventKind::Fence;
		}
		if (std::dynamic_pointer_cast<Core::Pipeline::EcallEvent>(systemEvent) != nullptr) return Core::SystemEventKind::Ecall;
		if (std::dynamic_pointer_cast<Core::Pipeline::EbreakEvent>(systemEvent) != nullptr) return Core::SystemEventKind::Ebreak;
		if (std::dynamic_pointer_cast<Core::Pipeline::MretEvent>(systemEvent) != nullptr) return Core::SystemEventKind::Mret;
		if (std::dynamic_pointer_cast<Core::Pipeline::SretEvent>(systemEvent) != nullptr) return Core::SystemEventKind::Sret;
		if (std::dynamic_pointer_cast<Core::Pipeline::WfiEvent>(systemEvent) != nullptr) return Core::SystemEventKind::Wfi;
		if (std::dynamic_pointer_cast<Core::Pipeline::WfeEvent>(systemEvent) != nullptr) return Core::SystemEventKind::Wfe;
		if (std::dynamic_pointer_cast<Core::Pipeline::SevEvent>(systemEvent) != nullptr) return Core::SystemEventKind::Sev;
		if (std::dynamic_pointer_cast<Core::Pipeline::YieldEvent>(systemEvent) != nullptr) return Core::SystemEventKind::Yield;
		if (std::dynamic_pointer_cast<Core::Pipeline::PodBarrierEvent>(systemEvent) != nullptr) return Core::SystemEventKind::PodBarrier;
		if (std::dynamic_pointer_cast<Core::Pipeline::VtBarrierEvent>(systemEvent) != nullptr) return Core::SystemEventKind::VtBarrier;
		throw InvalidOperationException(L"Unsupported retired system event payload.");
	}

	inline std::shared_ptr<Core::Pipeline::PipelineEvent> Processor::CPU_Core::CreateRetiredSystemEvent(Core::SystemEventKind systemEventKind, int virtualThreadId)
	{
		unsigned char vtId = static_cast<unsigned char>(virtualThreadId & 0xFF);
		std::shared_ptr<Core::Pipeline::PipelineEvent> event;
		switch (systemEventKind)
		{
			case Core::SystemEventKind::Fence:
			case Core::SystemEventKind::FenceI:
			{
				auto fence = std::make_shared<Core::Pipeline::FenceEvent>();
				fence->VtId = vtId;
				fence->BundleSerial = 0;
				fence->IsInstructionFence = systemEventKind == Core::SystemEventKind::FenceI;
				event = fence;
				break;
			}
			case Core::SystemEventKind::Ecall: event = std::make_shared<Core::Pipeline::EcallEvent>(); break;
			case Core::SystemEventKind::Ebreak: event = std::make_shared<Core::Pipeline::EbreakEvent>(); break;
			case Core::SystemEventKind::Mret: event = std::make_shared<Core::Pipeline::MretEvent>(); break;
			case Core::SystemEventKind::Sret: event = std::make_shared<Core::Pipeline::SretEvent>(); break;
			case Core::SystemEventKind::Wfi: event = std::make_shared<Core::Pipeline::WfiEvent>(); break;
			case Core::SystemEventKind::Wfe: event = std::make_shared<Core::Pipeline::WfeEvent>(); break;
			case Core::SystemEventKind::Sev: event = std::make_shared<Core::Pipeline::SevEvent>(); break;
			case Core::SystemEventKind::Yield: event = std::make_shared<Core::Pipeline::YieldEvent>(); break;
			case Core::SystemEventKind::PodBarrier: event = std::make_shared<Core::Pipeline::PodBarrierEvent>(); break;
			case Core::SystemEventKind::VtBarrier: event = std::make_shared<Core::Pipeline::VtBarrierEvent>(); break;
			default:
				throw InvalidOperationException(L"Unsupported retired system event kind.");
		}
		event->VtId = vtId;
		event->BundleSerial = 0;
		if (const auto ecall = std::dynamic_pointer_cast<Core::Pipeline::EcallEvent>(event))
		{
			ecall->EcallCode = 0;
		}
		return event;
	}

	inline std::shared_ptr<Core::Pipeline::PipelineEvent> Processor::CPU_Core::CreateRetiredPipelineEvent(std::shared_ptr<Core::Pipeline::PipelineEvent> pipelineEvent, int virtualThreadId)
	{
		ArgumentNullException::ThrowIfNull(pipelineEvent);
		unsigned char vtId = static_cast<unsigned char>(virtualThreadId & 0xFF);
		const unsigned long long bundleSerial = pipelineEvent->BundleSerial;
		auto initialize = [vtId, bundleSerial](const auto &event) -> std::shared_ptr<Core::Pipeline::PipelineEvent>
		{
			event->VtId = vtId;
			event->BundleSerial = bundleSerial;
			return event;
		};
		if (const auto fence = std::dynamic_pointer_cast<Core::Pipeline::FenceEvent>(pipelineEvent))
		{
			auto copy = std::make_shared<Core::Pipeline::FenceEvent>();
			copy->IsInstructionFence = fence->IsInstructionFence;
			return initialize(copy);
		}
		if (const auto ecall = std::dynamic_pointer_cast<Core::Pipeline::EcallEvent>(pipelineEvent))
		{
			auto copy = std::make_shared<Core::Pipeline::EcallEvent>();
			copy->EcallCode = ecall->EcallCode;
			return initialize(copy);
		}
		if (std::dynamic_pointer_cast<Core::Pipeline::EbreakEvent>(pipelineEvent)) return initialize(std::make_shared<Core::Pipeline::EbreakEvent>());
		if (const auto trap = std::dynamic_pointer_cast<Core::Pipeline::TrapEntryEvent>(pipelineEvent))
		{
			auto copy = std::make_shared<Core::Pipeline::TrapEntryEvent>();
			copy->CauseCode = trap->CauseCode;
			copy->FaultAddress = trap->FaultAddress;
			copy->HasFaultAddress = trap->HasFaultAddress;
			copy->FaultAddressSemantic = trap->FaultAddressSemantic;
			return initialize(copy);
		}
		if (std::dynamic_pointer_cast<Core::Pipeline::MretEvent>(pipelineEvent)) return initialize(std::make_shared<Core::Pipeline::MretEvent>());
		if (std::dynamic_pointer_cast<Core::Pipeline::SretEvent>(pipelineEvent)) return initialize(std::make_shared<Core::Pipeline::SretEvent>());
		if (std::dynamic_pointer_cast<Core::Pipeline::WfiEvent>(pipelineEvent)) return initialize(std::make_shared<Core::Pipeline::WfiEvent>());
		if (std::dynamic_pointer_cast<Core::Pipeline::YieldEvent>(pipelineEvent)) return initialize(std::make_shared<Core::Pipeline::YieldEvent>());
		if (std::dynamic_pointer_cast<Core::Pipeline::WfeEvent>(pipelineEvent)) return initialize(std::make_shared<Core::Pipeline::WfeEvent>());
		if (std::dynamic_pointer_cast<Core::Pipeline::SevEvent>(pipelineEvent)) return initialize(std::make_shared<Core::Pipeline::SevEvent>());
		if (std::dynamic_pointer_cast<Core::Pipeline::PodBarrierEvent>(pipelineEvent)) return initialize(std::make_shared<Core::Pipeline::PodBarrierEvent>());
		if (std::dynamic_pointer_cast<Core::Pipeline::VtBarrierEvent>(pipelineEvent)) return initialize(std::make_shared<Core::Pipeline::VtBarrierEvent>());
		throw InvalidOperationException(L"Unsupported retired pipeline event payload.");
	}

	inline std::optional<std::shared_ptr<Core::Pipeline::PipelineEvent>> Processor::CPU_Core::MaterializeLaneGeneratedEvent(std::shared_ptr<Core::MicroOp> microOp)
	{
		std::shared_ptr<Core::SysEventMicroOp> systemEventMicroOp = std::dynamic_pointer_cast<Core::SysEventMicroOp>(microOp);
		if (systemEventMicroOp != nullptr)
		{
			return MaterializeSystemEventWithStableCoreIdentity(systemEventMicroOp);
		}

		std::shared_ptr<Core::TrapMicroOp> trapMicroOp = std::dynamic_pointer_cast<Core::TrapMicroOp>(microOp);
		if (trapMicroOp != nullptr)
		{
			unsigned long long bundleSequence = 0;
			std::shared_ptr<Core::PostStageBIssuedAttempt> attempt = trapMicroOp->getPostStageBIssuedAttempt();
			if (attempt != nullptr && attempt->getScheduledOperation() != nullptr)
			{
				bundleSequence = attempt->getScheduledOperation()->getOperationId()->WorkingBundleSequence;
			}
			return trapMicroOp->CreatePipelineEvent(bundleSequence);
		}

		return std::nullopt;
	}

	inline std::optional<Core::CsrRetireEffect> Processor::CPU_Core::MaterializeLaneCsrEffect(std::shared_ptr<Core::MicroOp> microOp)
	{
		std::shared_ptr<Core::CSRMicroOp> csrMicroOp = std::dynamic_pointer_cast<Core::CSRMicroOp>(microOp);
		if (csrMicroOp != nullptr)
		{
			Core::CsrRetireEffect effect = MaterializeCsrEffectWithStableCoreIdentity(csrMicroOp);
			return effect.getClearsArchitecturalExceptionState() || effect.getHasCsrWrite() || effect.getHasRegisterWriteback() ? std::optional<Core::CsrRetireEffect>(effect) : std::nullopt;
		}

		return std::nullopt;
	}

	inline std::optional<Core::AtomicRetireEffect> Processor::CPU_Core::MaterializeLaneAtomicEffect(std::shared_ptr<Core::MicroOp> microOp)
	{
		std::shared_ptr<Core::AtomicMicroOp> atomicMicroOp = std::dynamic_pointer_cast<Core::AtomicMicroOp>(microOp);
		if (atomicMicroOp != nullptr)
		{
			return atomicMicroOp->CreateRetireEffect();
		}

		return std::nullopt;
	}

// C# TO C++ CONVERTER WARNING: Nullable reference types have no equivalent in C++:
// ORIGINAL LINE: [MethodImpl(MethodImplOptions.AggressiveInlining)] private static bool IsAtomicReadOnlyAlignmentFaultCarrier(Core.MicroOp? microOp)
	inline bool Processor::CPU_Core::IsAtomicReadOnlyAlignmentFaultCarrier(std::shared_ptr<Core::MicroOp> microOp)
	{
		std::shared_ptr<Core::AtomicMicroOp> atomicMicroOp = std::dynamic_pointer_cast<Core::AtomicMicroOp>(microOp);
		return atomicMicroOp != nullptr && ([&] { const auto codexPatternValue = atomicMicroOp->getOpCode(); return codexPatternValue == IsaOpcodeValues::LR_W || codexPatternValue == IsaOpcodeValues::LR_D; }());
	}

	inline bool Processor::CPU_Core::TryResolveLanePrimaryWriteBackValue(std::shared_ptr<Core::MicroOp> microOp, std::optional<Core::CsrRetireEffect> &csrEffect, unsigned long long &value)
	{
		if (csrEffect && csrEffect.value().getHasRegisterWriteback())
		{
			value = csrEffect.value().getReadValue();
			return true;
		}

		return microOp->TryGetPrimaryWriteBackResult(value);
	}

	inline void Processor::CPU_Core::EmitGeneratedCsrRetireRecords(int virtualThreadId, Core::CsrRetireEffect const csrEffect, std::span<RetireRecord> retireRecords, int &retireRecordCount)
	{
		if (!csrEffect.getHasRegisterWriteback())
		{
			return;
		}

		AppendRetireRecord(retireRecords, retireRecordCount, RetireRecord::RegisterWrite(virtualThreadId, csrEffect.getDestRegId(), csrEffect.getReadValue()));
	}

	inline void Processor::CPU_Core::EmitGeneratedVectorConfigRetireRecords(int virtualThreadId, Core::VectorConfigRetireEffect const vectorConfigEffect, std::span<RetireRecord> retireRecords, int &retireRecordCount)
	{
		if (!vectorConfigEffect.getHasRegisterWriteback())
		{
			return;
		}

		AppendRetireRecord(retireRecords, retireRecordCount, RetireRecord::RegisterWrite(virtualThreadId, vectorConfigEffect.getDestinationRegister(), vectorConfigEffect.getActualVectorLength()));
	}

