	void Processor::CPU_Core::ForwardingPath::Clear()
	{
		Valid = false;
		DestRegID = 0;
		ForwardedValue = 0;
		AvailableCycle = 0;
		SourceStage = PipelineStage::None;
	}

	bool Processor::CPU_Core::ForwardingPath::IsAvailable(long long currentCycle)
	{
		return Valid && currentCycle >= AvailableCycle;
	}

	int Processor::CPU_Core::ForwardingPath::GetDelayCycles(long long currentCycle)
	{
		if (!Valid)
		{
			return -1;
		}
		if (currentCycle >= AvailableCycle)
		{
			return 0;
		}
		return static_cast<int>(AvailableCycle - currentCycle);
	}

