	void Processor::CPU_Core::AttachRf08PostStageBIdentityTemplate(unsigned long long currentBundlePc, Core::ScalarClusterIssueEntry const entry, std::shared_ptr<Core::MicroOp> candidate)
	{
		// The approved contour is deliberately limited to the RF-06
		// scalar RegisterWrite family. Unsupported scalar carriers keep
		// the unchanged legacy path and receive no issued identity.
		if (candidate->getPostStageBIssuedAttempt() != nullptr)
		{
			candidate->setPostStageBIdentityTemplate(nullptr);
			return;
		}

		candidate->setPostStageBIdentityTemplate(nullptr);
		if (std::dynamic_pointer_cast<Core::ScalarALUMicroOp>(candidate) == nullptr)
		{
			return;
		}

		Core::DecodedBundleRuntimeState runtimeState = Core::DecodedBundleRuntimeState::CreateEmpty(0);
		ReadCurrentDecodedBundleRuntimeState(runtimeState);
		std::shared_ptr<Core::Decoder::CanonicalBundle> canonicalBundle = std::dynamic_pointer_cast<Core::Decoder::CanonicalBundle>(runtimeState.getCanonicalDecode()->getCanonicalBundle());
		if (!runtimeState.getHasCanonicalDecode() || runtimeState.getBundlePc() != currentBundlePc || canonicalBundle == nullptr)
		{
			return;
		}

		std::shared_ptr<Core::Decoder::CanonicalDecodedInstruction> canonical;
		try
		{
			canonical = canonicalBundle->GetSlot(entry.getSlotIndex());
			if (canonical->Opcode != candidate->getOpCode())
			{
				return;
			}

			std::shared_ptr<Core::Decoder::ExecutionContract> contract = Core::Decoder::Rf06ScalarLegacyProjection::CreateContract(canonical);
			std::shared_ptr<Core::Decoder::SourceOperationProvenance> provenance = std::make_shared<Core::Decoder::SourceOperationProvenance>(canonicalBundle->getSemanticKey(), entry.getVirtualThreadId(), runtimeState.getBundleSerial(), Core::SlotId::Create(entry.getSlotIndex()), runtimeState.getStateEpoch());
			std::shared_ptr<Core::Decoder::AdmissionRecord> admission = Core::Decoder::AdmissionRecord::Create(provenance, contract, entry.getVirtualThreadId(), candidate->getOwnerContextId(), candidate->getPlacement().DomainTag);
			std::shared_ptr<Core::WorkingBundleEntry> workingEntry = Core::WorkingBundleEntry::CreateSourcePreserving(admission, candidate, runtimeState.getBundleSerial(), provenance->SourceSlotId);
			workingEntry->getCarrier()->setPostStageBIdentityTemplate(workingEntry->CreatePostStageBIdentityTemplate(getRf08OperationAttemptIssuer()));
		}
		catch (const InvalidOperationException &e1)
		{
			// The live candidate is outside the frozen first scalar family;
			// retain the existing identity-less behavior for that family.
			candidate->setPostStageBIdentityTemplate(nullptr);
		}
	}

	inline unsigned char Processor::CPU_Core::ResolveForegroundRunnableVirtualThreadMask()
	{
		unsigned char runnableMask = 0;
		for (int vt = 0; vt < SmtWays; vt++)
		{
			if (CanVirtualThreadIssueInForeground(vt))
			{
				runnableMask |= static_cast<unsigned char>(1 << vt);
			}
		}

		return runnableMask;
	}

