	inline int Processor::CPU_Core::CountInjectableGaps(const std::vector<Core::DecodedBundleSlotDescriptor> &slotDescriptors)
	{
		if (slotDescriptors.empty())
		{
			return 0;
		}

		int gapCount = 0;
		for (int slot = 0; slot < slotDescriptors.size(); slot++)
		{
			Core::DecodedBundleSlotDescriptor slotDescriptor = slotDescriptors[slot];
			if (!slotDescriptor.isValid() || slotDescriptor.GetRuntimeExecutionIsEmptyOrNop())
			{
				gapCount++;
			}
		}

		return gapCount;
	}

	inline bool Processor::CPU_Core::ShouldSkipDecodedSlotForForegroundIssue(Core::DecodedBundleSlotDescriptor const slotDescriptor)
	{
		if (!slotDescriptor.isValid())
		{
			return true;
		}

		if (slotDescriptor.GetRuntimeExecutionIsEmptyOrNop() && !slotDescriptor.GetRuntimeAdmissionIsControlFlow())
		{
			return true;
		}

		return !CanVirtualThreadIssueInForeground(slotDescriptor.GetRuntimeExecutionVirtualThreadId());
	}

