	inline void Processor::CPU_Core::ClearNominatedOwnerSlots(std::vector<std::shared_ptr<Core::MicroOp>> &ownerBundle, std::vector<int> &nominatedSlots)
	{
		if (ownerBundle.empty() || nominatedSlots.empty())
		{
			return;
		}

		for (int vtId = 0; vtId < nominatedSlots.size(); vtId++)
		{
			int slotIndex = nominatedSlots[vtId];
			if (static_cast<unsigned int>(slotIndex) >= ownerBundle.size())
			{
				continue;
			}

			ownerBundle[slotIndex] = nullptr;
		}
	}

	inline void Processor::CPU_Core::RestoreUnmaterializedSmtCandidates(std::vector<std::shared_ptr<Core::MicroOp>> &packedBundle, std::vector<std::shared_ptr<Core::MicroOp>> &nominatedCandidates, std::vector<int> &nominatedSlots)
	{
		if (packedBundle.empty())
		{
			return;
		}

		for (int vtId = 0; vtId < nominatedCandidates.size(); vtId++)
		{
			std::shared_ptr<Core::MicroOp> candidate = nominatedCandidates[vtId];
			int slotIndex = nominatedSlots[vtId];
			if (candidate == nullptr || slotIndex < 0 || BundleContainsReference(packedBundle, candidate))
			{
				continue;
			}

			if (packedBundle[slotIndex] == nullptr || std::dynamic_pointer_cast<Core::NopMicroOp>(packedBundle[slotIndex]) != nullptr)
			{
				packedBundle[slotIndex] = candidate;
				continue;
			}

			int fallbackSlot = FindInjectableGapSlot(packedBundle);
			if (fallbackSlot >= 0)
			{
				packedBundle[fallbackSlot] = candidate;
			}
		}
	}

	inline int Processor::CPU_Core::FindInjectableGapSlot(std::vector<std::shared_ptr<Core::MicroOp>> &bundle)
	{
		if (bundle.empty())
		{
			return -1;
		}

		for (int slot = 0; slot < bundle.size(); slot++)
		{
			if (bundle[slot] == nullptr || std::dynamic_pointer_cast<Core::NopMicroOp>(bundle[slot]) != nullptr)
			{
				return slot;
			}
		}

		return -1;
	}

	inline bool Processor::CPU_Core::BundleContainsReference(std::vector<std::shared_ptr<Core::MicroOp>> &bundle, std::shared_ptr<Core::MicroOp> candidate)
	{
		for (int slot = 0; slot < bundle.size(); slot++)
		{
			if (bundle[slot] == candidate)
			{
				return true;
			}
		}

		return false;
	}

