	Processor::CPU_Core::ScalarExecuteLaneState Processor::CPU_Core::ExecuteStage::GetLane(unsigned char laneIndex) const
	{
		switch (PipelineLaneResolver::ResolveLaneOrThrow(laneIndex, L"ExecuteStage"))
		{
			case 0: return Lane0;
			case 1: return Lane1;
			case 2: return Lane2;
			case 3: return Lane3;
			case 4: return Lane4;
			case 5: return Lane5;
			case 6: return Lane6;
			case 7: return Lane7;
			default: throw InvalidPipelineLaneException(L"ExecuteStage", laneIndex);
		}
	}

	void Processor::CPU_Core::ExecuteStage::SetLane(unsigned char laneIndex, ScalarExecuteLaneState lane)
	{
		switch (PipelineLaneResolver::ResolveLaneOrThrow(laneIndex, L"ExecuteStage"))
		{
			case 0:
			Lane0.CopyFrom(lane);
				break;
			case 1:
			Lane1.CopyFrom(lane);
				break;
			case 2:
			Lane2.CopyFrom(lane);
				break;
			case 3:
			Lane3.CopyFrom(lane);
				break;
			case 4:
			Lane4.CopyFrom(lane);
				break;
			case 5:
			Lane5.CopyFrom(lane);
				break;
			case 6:
			Lane6.CopyFrom(lane);
				break;
			case 7:
			Lane7.CopyFrom(lane);
				break;
		}
	}

