	void Processor::CPU_Core::InitializePipeline()
	{
		BeginLiveSecureSourceMutation();
		try
		{
			InitializePipelineUnderMutationOwner();
		}
		catch (...)
		{
			EndLiveSecureSourceMutation();
			throw;
		}
		EndLiveSecureSourceMutation();
	}

	void Processor::CPU_Core::InitializePipelineUnderMutationOwner()
	{
		InvalidateDiscardedPipelineAttempts();
		CancelInFlightExplicitMemoryRequests();
		ReleaseAllInFlightLaneAwareBookkeeping();
		WithdrawSourceFspNominations();
		ResetShadowFrontendLifetime();
		CancelInFlightSingleLaneControllerRequests();
		pipeIF.Clear();
		getRuntime()->getDecode()->Decode.Clear();
		getRuntime()->getExecution()->Execute.Clear();
		getRuntime()->getMemoryPipeline()->Memory.Clear();
		getRuntime()->getMemoryPipeline()->WriteBack.Clear();
		ResetAssistRuntimeState();
		pipeCtrl.Clear();
		pipeCtrl.Enabled = false;
		getRuntime()->getRetire()->LastRetiredBundlePc = 0;
		getRuntime()->getRetire()->RetiredBundleSequence = 0;
		getRuntime()->getDecode()->PipelineBundleSlot = 0;

		// Initialize FSP bundle decode state
		ResetPipelineContourCertificates();
		getRuntime()->getDecode()->BundleStateEpochCounter = 0;
		getRuntime()->getDecode()->BundleStateVersionCounter = 0;
		ResetCurrentDecodedBundleSlotCarrierState(0);
		getRuntime()->getDecode()->BundleProgress = Core::BundleProgressState::CreateEmpty();
		ReplaceSnapshot(getRuntime()->getDecode()->DerivedIssuePlan, Core::DecodedBundleDerivedIssuePlanState::CreateEmpty(0));
		getRuntime()->getDecode()->ClusterPreparation = Core::ClusterIssuePreparation::CreateEmpty();
		getRuntime()->getAdmission()->Preparation = Core::RuntimeClusterAdmissionPreparation::CreateEmpty();
		getRuntime()->getAdmission()->CandidateView = Core::RuntimeClusterAdmissionCandidateView::CreateEmpty();
		getRuntime()->getAdmission()->DecisionDraft = Core::RuntimeClusterAdmissionDecisionDraft::CreateEmpty();
		getRuntime()->getAdmission()->Handoff = Core::RuntimeClusterAdmissionHandoff::CreateEmpty();
					getRuntime()->getDecode()->BundleDecodedAndPacked = false;

		// Clear forwarding paths
		getRuntime()->getExecution()->ExecuteForwarding.Clear();
		getRuntime()->getExecution()->MemoryForwarding.Clear();
		getRuntime()->getExecution()->WriteBackForwarding.Clear();

		// Clear branch predictor
		getRuntime()->getFrontend()->BranchPredictor.Clear();

		// Use Pod-local FSP scheduler if the topology is initialized (req.md §1).
		// Runtime legality authority now lives behind MicroOpScheduler ->
		// IRuntimeLegalityService, so the pipeline shell does not keep a
		// direct verifier instance anymore.
		std::shared_ptr<PodController> pod = Processor::GetPodForCore(static_cast<int>(this->CoreID));
		std::shared_ptr<Core::MicroOpScheduler> scheduler = (_platformContext->OwnedSoftwareSecureScheduler != nullptr) ? _platformContext->OwnedSoftwareSecureScheduler : (((((pod == nullptr ? nullptr : pod->getScheduler()) != nullptr) ? (pod == nullptr ? nullptr : pod->getScheduler()) : _fspScheduler) != nullptr) ? (((pod == nullptr ? nullptr : pod->getScheduler()) != nullptr) ? (pod == nullptr ? nullptr : pod->getScheduler()) : _fspScheduler) : std::make_shared<Core::MicroOpScheduler>());
		_fspScheduler = scheduler;
		EnsureConfiguredExactProbeRuntimeProfile(scheduler);

		// Initialize Loop Buffer (req.md §3)
		_loopBuffer = Core::LoopBuffer();
		_loopBuffer.Initialize();
		if (_fetchVliwBuffer == nullptr) _fetchVliwBuffer = std::make_shared<std::vector<unsigned char>>(256);
		if (getRuntime()->getMemoryPipeline()->ExplicitPacketImmediateReadBuffer == nullptr)
			getRuntime()->getMemoryPipeline()->ExplicitPacketImmediateReadBuffer = std::make_shared<std::vector<unsigned char>>(8);
	}

	void Processor::CPU_Core::SetPipelineMode(bool enable)
	{
		BeginLiveSecureSourceMutation();
		auto finishMutation = std::shared_ptr<void>(this, [this](void*) { EndLiveSecureSourceMutation(); });
		try
		{
			SetPipelineModeUnderMutationOwner(enable);
		}
		catch (...)
		{
			throw;
		}
	}

	void Processor::CPU_Core::SetPipelineModeUnderMutationOwner(bool enable)
	{
		pipeCtrl.Enabled = enable;
		pipeCtrl.ClusterPreparedModeEnabled = enable; // Stage 7 Phase A: toggle wide-path with pipeline
		if (enable)
		{
			SynchronizeExecutionMode();
			FlushPipeline();
		}
	}

	void Processor::CPU_Core::PrepareExecutionStart(unsigned long long pc, int activeVtId)
	{
		BeginLiveSecureSourceMutation();
		auto finishMutation = std::shared_ptr<void>(this, [this](void*) { EndLiveSecureSourceMutation(); });
		try
		{
			SynchronizeExecutionMode();
			ResetExecutionStartPcState(pc, activeVtId);
			pipeCtrl.Enabled = true;
			pipeCtrl.ClusterPreparedModeEnabled = true;
		}
		catch (...)
		{
			throw;
		}
	}

	void Processor::CPU_Core::SetClusterPreparedMode(bool enable)
	{
		BeginLiveSecureSourceMutation();
		auto finishMutation = std::shared_ptr<void>(this, [this](void*) { EndLiveSecureSourceMutation(); });
		try
		{
			pipeCtrl.ClusterPreparedModeEnabled = enable;
		}
		catch (...)
		{
			throw;
		}
	}

	void Processor::CPU_Core::FlushPipeline(Core::AssistInvalidationReason assistInvalidationReason)
	{
		BeginLiveSecureSourceMutation();
		auto finishMutation = std::shared_ptr<void>(this, [this](void*) { EndLiveSecureSourceMutation(); });
		try
		{
			FlushPipelineUnderSecureGate(assistInvalidationReason);
		}
		catch (...)
		{
			throw;
		}
	}

	void Processor::CPU_Core::FlushPipelineUnderSecureGate(Core::AssistInvalidationReason assistInvalidationReason)
	{
		liveSecureSourceCurrent = false;
		InvalidateDiscardedPipelineAttempts();
		CancelInFlightExplicitMemoryRequests();
		CancelInFlightSingleLaneControllerRequests();

		// Refactoring Pt. 4 / Priority 4C: release GRLB and MSHR bookkeeping for
		// all occupied scalar lanes before clearing stage registers.
		ReleaseAllInFlightLaneAwareBookkeeping();
		InvalidateAssistRuntime(assistInvalidationReason);
		AdvanceReplayCodeGenerationEpoch(true);
		ClearPendingCpuFetchTranslationFault();

		pipeIF.Clear();
		getRuntime()->getDecode()->Decode.Clear();
		getRuntime()->getExecution()->Execute.Clear();
		getRuntime()->getMemoryPipeline()->Memory.Clear();
		getRuntime()->getMemoryPipeline()->WriteBack.Clear();
		pipeCtrl.Stalled = false;
		pipeCtrl.StallReason = PipelineStallKind::None;

		// Reset FSP bundle decode state
		getRuntime()->getDecode()->PipelineBundleSlot = 0;
		getRuntime()->getDecode()->BundleDecodedAndPacked = false;
		ResetCurrentDecodedBundleSlotCarrierState(0);
		getRuntime()->getDecode()->BundleProgress = Core::BundleProgressState::CreateEmpty();
		ReplaceSnapshot(getRuntime()->getDecode()->DerivedIssuePlan, Core::DecodedBundleDerivedIssuePlanState::CreateEmpty());
		getRuntime()->getDecode()->ClusterPreparation = Core::ClusterIssuePreparation::CreateEmpty();
		getRuntime()->getAdmission()->Preparation = Core::RuntimeClusterAdmissionPreparation::CreateEmpty();
		getRuntime()->getAdmission()->CandidateView = Core::RuntimeClusterAdmissionCandidateView::CreateEmpty();
		getRuntime()->getAdmission()->DecisionDraft = Core::RuntimeClusterAdmissionDecisionDraft::CreateEmpty();
		getRuntime()->getAdmission()->Handoff = Core::RuntimeClusterAdmissionHandoff::CreateEmpty();
		// Invalidate Loop Buffer on pipeline flush (branch, interrupt)
		_loopBuffer.Invalidate(ResolveReplayPhaseInvalidationReasonForPipelineFlush(assistInvalidationReason));
		if (_fspScheduler != nullptr)
		{
			_fspScheduler->SetReplayPhaseContext(_loopBuffer.getCurrentReplayPhase(), false);
		}
	}

	inline Core::ReplayPhaseInvalidationReason Processor::CPU_Core::ResolveReplayPhaseInvalidationReasonForPipelineFlush(Core::AssistInvalidationReason assistInvalidationReason)
	{
		switch (assistInvalidationReason)
		{
			case Core::AssistInvalidationReason::Trap:
			case Core::AssistInvalidationReason::Fence:
			case Core::AssistInvalidationReason::VmTransition:
			case Core::AssistInvalidationReason::SerializingBoundary:
				return Core::ReplayPhaseInvalidationReason::SerializingEvent;
			default:
				return Core::ReplayPhaseInvalidationReason::Manual;
		}
	}

