	Processor::CPU_Core::ScalarMemoryLaneState Processor::CPU_Core::MemoryStage::GetLane(unsigned char laneIndex) const
	{
		switch (PipelineLaneResolver::ResolveLaneOrThrow(laneIndex, L"MemoryStage"))
		{
			case 0: return Lane0;
			case 1: return Lane1;
			case 2: return Lane2;
			case 3: return Lane3;
			case 4: return Lane4;
			case 5: return Lane5;
			case 6: return Lane6;
			case 7: return Lane7;
			default: throw InvalidPipelineLaneException(L"MemoryStage", laneIndex);
		}
	}

	void Processor::CPU_Core::MemoryStage::SetLane(unsigned char laneIndex, ScalarMemoryLaneState lane)
	{
		switch (PipelineLaneResolver::ResolveLaneOrThrow(laneIndex, L"MemoryStage"))
		{
			case 0:
		Lane0.CopyFrom(lane);
				break;
			case 1:
			Lane1.CopyFrom(lane);
				break;
			case 2:
			Lane2.CopyFrom(lane);
				break;
			case 3:
			Lane3.CopyFrom(lane);
				break;
			case 4:
			Lane4.CopyFrom(lane);
				break;
			case 5:
			Lane5.CopyFrom(lane);
				break;
			case 6:
			Lane6.CopyFrom(lane);
				break;
			case 7:
			Lane7.CopyFrom(lane);
				break;
		}
	}

	void Processor::CPU_Core::MemoryStage::Clear()
	{
		Valid = false;
		ActiveLaneIndex = 0;
		Lane0.Clear(0);
		Lane1.Clear(1);
		Lane2.Clear(2);
		Lane3.Clear(3);
		Lane4.Clear(4);
		Lane5.Clear(5);
		Lane6.Clear(6);
		Lane7.Clear(7);
		PreparedScalarMask = 0;
		RefinedPreparedScalarMask = 0;
		MaterializedScalarLaneCount = 0;
		MaterializedPhysicalLaneCount = 0;
		UsesExplicitPacketLanes = false;
		RetainsReferenceSequentialPath = true;
		SelectedNonScalarSlotMask = 0;
		BlockedScalarCandidateMask = 0;
		AdmissionExecutionMode = Core::RuntimeClusterAdmissionExecutionMode::Empty;
	}

