	void Processor::CPU_Core::ScalarMemoryLaneState::Clear(unsigned char laneIndex)
	{
		IsOccupied = false;
		LaneIndex = laneIndex;
		SlotIndex = 0;
		PC = 0;
		OpCode = 0;
		ResultValue = 0;
		ResultReady = false;
		IsMemoryOp = false;
		MemoryAddress = 0;
		MemoryData = 0;
		IsLoad = false;
		MemoryAccessSize = 0;
		IsVectorOp = false;
		VectorComplete = false;
		WritesRegister = false;
		DestRegID = 0;
		MicroOp = nullptr;
		PostStageBIssuedAttempt = nullptr;
		GeneratedEvent = std::nullopt;
		GeneratedCsrEffect = std::nullopt;
		GeneratedAtomicEffect = std::nullopt;
		GeneratedVmxEffect = std::nullopt;
		GeneratedRetireRecordCount = 0;
		GeneratedRetireRecord0 = YAKSys_Hybrid_CPU::Core::Registers::Retire::RetireRecord();
		GeneratedRetireRecord1 = YAKSys_Hybrid_CPU::Core::Registers::Retire::RetireRecord();
		DomainTag = 0;
		MshrScoreboardSlot = -1;
		MshrVirtualThreadId = 0;
		ResourceMask = Core::ResourceBitset::Zero;
		ResourceToken = 0;
		OwnerThreadId = 0;
		VirtualThreadId = 0;
		OwnerContextId = 0;
		WasFspInjected = false;
		OriginalThreadId = 0;
		HasFault = false;
		FaultAddress = 0;
		FaultIsWrite = false;
		CpuTranslationFault = std::nullopt;
		DefersStoreCommitToWriteBack = false;
		PendingMemoryRequest = nullptr;
		PendingMemoryControllerRequestId = std::nullopt;
		// Preserve the reusable read buffer across clears so the lane can
		// satisfy the next explicit async load without reallocating.
	}

	inline unsigned char Processor::CPU_Core::NormalizeScalarMemoryAccessSize(unsigned char memoryAccessSize)
	{
		return memoryAccessSize == 0 ? static_cast<unsigned char>(8) : memoryAccessSize;
	}

	inline std::vector<unsigned char> Processor::CPU_Core::ReadExplicitPacketLoadIntoReusableBuffer(unsigned long long address, unsigned char accessSize)
	{
		auto &readBuffer = getRuntime()->getMemoryPipeline()->ExplicitPacketImmediateReadBuffer;
		if (readBuffer == nullptr || readBuffer->size() < accessSize)
		{
			readBuffer = std::make_shared<std::vector<unsigned char>>(accessSize);
		}
		std::vector<unsigned char> result = ReadBoundMainMemory(address, *readBuffer, accessSize, L"Explicit-packet synchronous fallback load");
		*readBuffer = result;
		return result;
	}

	inline bool Processor::CPU_Core::IsScalarMemoryAccessInBounds(unsigned long long address, unsigned char accessSize)
	{
		unsigned long long normalizedAccessSize = NormalizeScalarMemoryAccessSize(accessSize);
		unsigned long long mainMemoryLength = GetBoundMainMemoryLength();
		return normalizedAccessSize <= mainMemoryLength && address <= mainMemoryLength - normalizedAccessSize;
	}

	inline bool Processor::CPU_Core::TryApplySingleLaneMemoryStageDomainSquash()
	{
		if (getRuntime()->getExecution()->Execute.getDomainTag() == 0 || getCsrMemDomainCert() == 0)
		{
			return false;
		}

		if ((getRuntime()->getExecution()->Execute.getDomainTag() & getCsrMemDomainCert()) != 0)
		{
			return false;
		}

		getRuntime()->getMemoryPipeline()->Memory.setWritesRegister(false);
		getRuntime()->getMemoryPipeline()->Memory.setResultValue(0);
		getRuntime()->getMemoryPipeline()->Memory.setResultReady(true);
		getRuntime()->getTelemetry()->DomainSquashCount++;
		return true;
	}

	inline void Processor::CPU_Core::PublishSingleLaneMemoryStageResult()
	{
		if (!getRuntime()->getExecution()->Execute.isMemoryOp())
		{
			getRuntime()->getMemoryPipeline()->Memory.setResultValue(getRuntime()->getExecution()->Execute.getResultValue());
			getRuntime()->getMemoryPipeline()->Memory.setResultReady(true);
			PublishExecuteCompletionContourCertificate(getRuntime()->getMemoryPipeline()->Memory.GetLane(getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex).MicroOp != nullptr ? Core::PipelineContourOwner::SingleLaneMicroOpExecution : Core::PipelineContourOwner::ReferenceExecution, Core::PipelineContourVisibilityStage::Memory, getRuntime()->getMemoryPipeline()->Memory.getPC(), static_cast<unsigned char>(1 << getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex));
			return;
		}

		if (getRuntime()->getExecution()->Execute.getGeneratedAtomicEffect().has_value())
		{
			getRuntime()->getMemoryPipeline()->Memory.setResultValue(0);
			getRuntime()->getMemoryPipeline()->Memory.setResultReady(true);
			PublishExecuteCompletionContourCertificate(getRuntime()->getMemoryPipeline()->Memory.GetLane(getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex).MicroOp != nullptr ? Core::PipelineContourOwner::SingleLaneMicroOpExecution : Core::PipelineContourOwner::ReferenceExecution, Core::PipelineContourVisibilityStage::Memory, getRuntime()->getMemoryPipeline()->Memory.getPC(), static_cast<unsigned char>(1 << getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex));
			return;
		}

		if (getRuntime()->getExecution()->Execute.isLoad())
		{
			ScalarExecuteLaneState executeLane = getRuntime()->getExecution()->Execute.GetLane(getRuntime()->getExecution()->Execute.ActiveLaneIndex);
			unsigned long long address = getRuntime()->getExecution()->Execute.getMemoryAddress();
			unsigned char loadAccessSize = NormalizeScalarMemoryAccessSize(executeLane.MemoryAccessSize);
			if (IsScalarMemoryAccessInBounds(address, loadAccessSize))
			{
				std::vector<unsigned char> buffer(loadAccessSize);
				if (std::dynamic_pointer_cast<Core::LoadMicroOp>(executeLane.MicroOp) != nullptr && executeLane.ResultReady)
					getRuntime()->getMemoryPipeline()->Memory.setResultValue(executeLane.ResultValue);
				else
				{
					ReadBoundMainMemory(address, buffer, loadAccessSize, L"PipelineStage_Memory() synchronous single-lane load");
					getRuntime()->getMemoryPipeline()->Memory.setResultValue(Core::LoadStoreMicroOp::DecodeLoadValue(executeLane.OpCode, buffer, loadAccessSize, L"PipelineStage_Memory() synchronous single-lane load"));
				}
			}
			else
			{
				std::shared_ptr<Core::PageFaultException> loadFault = std::make_shared<Core::PageFaultException>(address, false);
				getRuntime()->getTelemetry()->MemoryFaultCarrierCount++;
				DeliverStageAwareMemoryPageFault(loadFault);
			}

			getRuntime()->getMemoryPipeline()->Memory.setResultReady(true);
			PublishExecuteCompletionContourCertificate(getRuntime()->getMemoryPipeline()->Memory.GetLane(getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex).MicroOp != nullptr ? Core::PipelineContourOwner::SingleLaneMicroOpExecution : Core::PipelineContourOwner::ReferenceExecution, Core::PipelineContourVisibilityStage::Memory, getRuntime()->getMemoryPipeline()->Memory.getPC(), static_cast<unsigned char>(1 << getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex));
			return;
		}

		unsigned long long storeAddress = getRuntime()->getExecution()->Execute.getMemoryAddress();
		unsigned long long storeData = getRuntime()->getExecution()->Execute.getMemoryData();
		unsigned char accessSize = NormalizeScalarMemoryAccessSize(getRuntime()->getExecution()->Execute.GetLane(getRuntime()->getExecution()->Execute.ActiveLaneIndex).MemoryAccessSize);
		if (IsScalarMemoryAccessInBounds(storeAddress, accessSize))
		{
			ScalarMemoryLaneState lane = getRuntime()->getMemoryPipeline()->Memory.GetLane(getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex);
			lane.MemoryAccessSize = accessSize;
			lane.DefersStoreCommitToWriteBack = true;
			getRuntime()->getMemoryPipeline()->Memory.SetLane(getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex, lane);
		}
		else
		{
			std::shared_ptr<Core::PageFaultException> storeFault = std::make_shared<Core::PageFaultException>(storeAddress, true);
			getRuntime()->getTelemetry()->MemoryFaultCarrierCount++;
			DeliverStageAwareMemoryPageFault(storeFault);
		}

		getRuntime()->getMemoryPipeline()->Memory.setResultValue(storeData);
		getRuntime()->getMemoryPipeline()->Memory.setResultReady(true);
		PublishExecuteCompletionContourCertificate(getRuntime()->getMemoryPipeline()->Memory.GetLane(getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex).MicroOp != nullptr ? Core::PipelineContourOwner::SingleLaneMicroOpExecution : Core::PipelineContourOwner::ReferenceExecution, Core::PipelineContourVisibilityStage::Memory, getRuntime()->getMemoryPipeline()->Memory.getPC(), static_cast<unsigned char>(1 << getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex));
	}

	inline void Processor::CPU_Core::PublishMemoryStageForwarding()
	{
		if (!getRuntime()->getMemoryPipeline()->Memory.getWritesRegister() || !getRuntime()->getMemoryPipeline()->Memory.getResultReady())
		{
			return;
		}

		getRuntime()->getExecution()->MemoryForwarding.Valid = true;
		getRuntime()->getExecution()->MemoryForwarding.DestRegID = getRuntime()->getMemoryPipeline()->Memory.getDestRegID();
		getRuntime()->getExecution()->MemoryForwarding.ForwardedValue = getRuntime()->getMemoryPipeline()->Memory.getResultValue();
		pipeCtrl.setForwardingEvents(pipeCtrl.getForwardingEvents() + 1);
	}

	inline void Processor::CPU_Core::ApplyRetiredScalarStoreCommit(ScalarWriteBackLaneState const lane)
	{
		if (!lane.DefersStoreCommitToWriteBack || !lane.IsMemoryOp || lane.IsLoad)
		{
			return;
		}

		ApplyRetiredScalarStoreCommit(lane.MemoryAddress, lane.MemoryData, lane.MemoryAccessSize, std::format(L"Retired store lane {0}", lane.LaneIndex));
	}

	inline void Processor::CPU_Core::ApplyRetiredScalarStoreCommit(unsigned long long memoryAddress, unsigned long long memoryData, unsigned char memoryAccessSize, const std::wstring &carrierDescription)
	{
		unsigned char accessSize = NormalizeScalarMemoryAccessSize(memoryAccessSize);
		if (!IsScalarMemoryAccessInBounds(memoryAddress, accessSize))
		{
			throw InvalidOperationException(std::format(L"{0} carries out-of-range memory commit.", carrierDescription));
		}

		auto storeBuffer = CreateExplicitPacketStoreBuffer(memoryData, accessSize);
		ThrowIfBoundMainMemoryRangeUnavailable(memoryAddress, accessSize, carrierDescription);
		WriteBoundMainMemory(memoryAddress, storeBuffer, carrierDescription);
		if (GetBoundMemorySubsystem() != nullptr)
		{
			GetBoundMemorySubsystem()->getCycleController()->RecordCommittedDataWriteBytes(accessSize);
		}
	}

	inline std::shared_ptr<DmaStreamComputeCommitResult> Processor::CPU_Core::ApplyRetiredDmaStreamComputeTokenCommit(std::shared_ptr<DmaStreamComputeToken> token, std::shared_ptr<DmaStreamComputeOwnerGuardDecision> commitGuardDecision)
	{
		ArgumentNullException::ThrowIfNull(token);

		std::shared_ptr<DmaStreamComputeCommitResult> result = token->Commit(GetBoundMainMemory(), commitGuardDecision);

		if (result->getRequiresRetireExceptionPublication())
		{
			throw result->CreateRetireException();
		}

		return result;
	}

	std::shared_ptr<DmaStreamComputeCommitResult> Processor::CPU_Core::ApplyDmaStreamComputeRetireCommit(std::shared_ptr<DmaStreamComputeToken> token, std::shared_ptr<DmaStreamComputeOwnerGuardDecision> commitGuardDecision)
	{
		return ApplyRetiredDmaStreamComputeTokenCommit(token, commitGuardDecision);
	}

	inline std::vector<unsigned char> Processor::CPU_Core::CreateExplicitPacketStoreBuffer(unsigned long long data, unsigned char accessSize)
	{
		std::vector<unsigned char> temp_var149;
		auto appendLittleEndian = [&](auto value)
		{
			using ValueType = decltype(value);
			temp_var149.resize(sizeof(ValueType));
			for (size_t i = 0; i < sizeof(ValueType); ++i) temp_var149[i] = static_cast<unsigned char>((value >> (8 * i)) & 0xff);
		};
		switch (accessSize)
		{
			case 1:
				temp_var149 = {static_cast<unsigned char>(data)};
				break;
			case 2:
				appendLittleEndian(static_cast<unsigned short>(data));
				break;
			case 4:
				appendLittleEndian(static_cast<unsigned int>(data));
				break;
			default:
				appendLittleEndian(data);
				break;
		}
		return temp_var149;
	}

	inline unsigned long long Processor::CPU_Core::DecodeExplicitPacketLoadBuffer(unsigned int opcode, std::vector<unsigned char> &buffer, unsigned char accessSize)
	{
		return Core::LoadStoreMicroOp::DecodeLoadValue(opcode, buffer, accessSize, L"Explicit packet load decode");
	}

	inline void Processor::CPU_Core::CancelInFlightExplicitMemoryRequests()
	{
		std::shared_ptr<MemorySubsystem> cancelMemSub = GetBoundMemorySubsystem();
		if (cancelMemSub == nullptr || !getRuntime()->getMemoryPipeline()->Memory.Valid || !getRuntime()->getMemoryPipeline()->Memory.UsesExplicitPacketLanes)
		{
			return;
		}

		for (unsigned char laneIndex = 4; laneIndex < 6; laneIndex++)
		{
			ScalarMemoryLaneState lane; lane.CopyFrom(getRuntime()->getMemoryPipeline()->Memory.GetLane(laneIndex));
			if (!lane.IsOccupied)
			{
				continue;
			}

			if ((std::dynamic_pointer_cast<Core::LoadStoreMicroOp>(lane.MicroOp)) != nullptr)
			{
				if ((std::dynamic_pointer_cast<Core::LoadStoreMicroOp>(lane.MicroOp))->getCpuPhysicalReadBinding() != nullptr)
				{
					(std::dynamic_pointer_cast<Core::LoadStoreMicroOp>(lane.MicroOp))->getCpuPhysicalReadBinding()->RevokeUnclaimed();
				}
			}
			{
			if ((std::dynamic_pointer_cast<Core::LoadStoreMicroOp>(lane.MicroOp))->getCpuPhysicalReadBinding() != nullptr)
			{
				(std::dynamic_pointer_cast<Core::LoadStoreMicroOp>(lane.MicroOp))->getCpuPhysicalReadBinding()->RevokeUnclaimed();
			}
		}
			bool canceled = false;
			if (lane.PendingMemoryRequest != nullptr)
			{
				cancelMemSub->CancelPendingRequest(lane.PendingMemoryRequest);
				lane.PendingMemoryRequest = nullptr;
				canceled = true;
			}

			if (lane.PendingMemoryControllerRequestId)
			{
				cancelMemSub->getCycleController()->TryCancel(lane.PendingMemoryControllerRequestId.value());
				lane.PendingMemoryControllerRequestId = std::nullopt;
				canceled = true;
			}

			if (canceled)
			{
				getRuntime()->getMemoryPipeline()->Memory.SetLane(laneIndex, lane);
			}
		}
	}

	inline void Processor::CPU_Core::CancelInFlightSingleLaneControllerRequests()
	{
		if (!getRuntime()->getExecution()->Execute.Valid)
		{
			return;
		}

		for (unsigned char laneIndex = 0; laneIndex < 8; laneIndex++)
		{
			ScalarExecuteLaneState lane = getRuntime()->getExecution()->Execute.GetLane(laneIndex);
			std::shared_ptr<Core::LoadMicroOp> loadMicroOp = std::dynamic_pointer_cast<Core::LoadMicroOp>(lane.MicroOp);
			if (lane.IsOccupied && loadMicroOp != nullptr)
			{
				loadMicroOp->CancelPendingControllerRequest();
			}
			else
			{
				std::shared_ptr<Core::StoreMicroOp> storeMicroOp = std::dynamic_pointer_cast<Core::StoreMicroOp>(lane.MicroOp);
				if (lane.IsOccupied && storeMicroOp != nullptr)
				{
					storeMicroOp->CancelPendingControllerRequest();
				}
				else
				{
					std::shared_ptr<Core::LoadSegmentMicroOp> loadSegmentMicroOp = std::dynamic_pointer_cast<Core::LoadSegmentMicroOp>(lane.MicroOp);
					if (lane.IsOccupied && loadSegmentMicroOp != nullptr)
					{
						loadSegmentMicroOp->CancelPendingControllerRequest();
					}
					else
					{
						std::shared_ptr<Core::VectorTransferMicroOp> vectorTransferMicroOp = std::dynamic_pointer_cast<Core::VectorTransferMicroOp>(lane.MicroOp);
						if (lane.IsOccupied && vectorTransferMicroOp != nullptr)
						{
							vectorTransferMicroOp->CancelPendingControllerRequest();
						}
					}
				}
			}
		}
	}

	inline void Processor::CPU_Core::ExecuteExplicitPacketMemoryWork()
	{
		unsigned char originalActiveLaneIndex = getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex;
		unsigned char completedLaneMask = 0;
		unsigned long long completedContourPc = 0;

		for (unsigned char laneIndex = 4; laneIndex < 8; laneIndex++)
		{
			ScalarMemoryLaneState lane; lane.CopyFrom(getRuntime()->getMemoryPipeline()->Memory.GetLane(laneIndex));
			if (!lane.IsOccupied || !lane.IsMemoryOp)
			{
				continue;
			}

			if (lane.ResultReady && lane.PendingMemoryRequest == nullptr && !lane.PendingMemoryControllerRequestId)
			{
				continue;
			}

			getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex = laneIndex;

			unsigned long long address = lane.MemoryAddress;
			unsigned char accessSize = NormalizeScalarMemoryAccessSize(lane.MemoryAccessSize);
			bool isWrite = !lane.IsLoad;

			std::shared_ptr<Core::LoadStoreMicroOp> scalarMemoryOperation = std::dynamic_pointer_cast<Core::LoadStoreMicroOp>(lane.MicroOp);
			if (scalarMemoryOperation != nullptr)
			{
				try
				{
					std::shared_ptr<CPU_Core> stableCoreIdentity = shared_from_this();
					address = scalarMemoryOperation->ResolveCpuTranslatedAddressForPipeline(stableCoreIdentity, lane.IsLoad ? Core::Memory::CpuInstructionTranslationAccessKind::ScalarLoad : Core::Memory::CpuInstructionTranslationAccessKind::ScalarStore, accessSize);
					lane.MemoryAddress = address;
					getRuntime()->getMemoryPipeline()->Memory.SetLane(laneIndex, lane);
				}
				catch (const Core::Memory::CpuInstructionTranslationFaultException &translationFaultException)
				{
					if (scalarMemoryOperation->isSpeculative())
					{
						scalarMemoryOperation->MarkFaulted();
						ReleaseScalarLaneBookkeeping(lane);
						ScalarMemoryLaneState cleared = ScalarMemoryLaneState();
						cleared.Clear(laneIndex);
						getRuntime()->getMemoryPipeline()->Memory.SetLane(laneIndex, cleared);
						pipeCtrl.setExceptionYoungerSuppressCount(pipeCtrl.getExceptionYoungerSuppressCount() + 1);
						continue;
					}

					DeliverStageAwareMemoryCpuTranslationFault(translationFaultException.getFault());
					throw InvalidOperationException(L"Stage-aware CPU translation fault delivery must terminate the current cycle.");
				}
			}

			std::shared_ptr<MemorySubsystem> memSub = GetBoundMemorySubsystem();

			unsigned long long memoryLength = (laneIndex < 6 && memSub != nullptr) ? static_cast<unsigned long long>(GetBoundMainMemory()->getLength()) : GetBoundMainMemoryLength();

			if (static_cast<unsigned long long>(accessSize) > memoryLength || address > memoryLength - static_cast<unsigned long long>(accessSize))
			{
				std::shared_ptr<Core::PageFaultException> memoryFault = std::make_shared<Core::PageFaultException>(address, isWrite);
				getRuntime()->getTelemetry()->MemoryFaultCarrierCount++;
				DeliverStageAwareMemoryPageFault(memoryFault);
				throw InvalidOperationException(L"Memory-stage page fault delivery must terminate the current cycle.");
			}

			if (lane.GeneratedAtomicEffect)
			{
				lane.MemoryAccessSize = accessSize;
				lane.ResultValue = 0;
				lane.ResultReady = true;
				getRuntime()->getMemoryPipeline()->Memory.SetLane(laneIndex, lane);
				completedLaneMask |= static_cast<unsigned char>(1 << laneIndex);
				completedContourPc = lane.PC;
				continue;
			}

			if (laneIndex < 6 && memSub != nullptr)
			{
				if (lane.IsLoad)
				{
					if (!lane.PendingMemoryControllerRequestId)
					{
						std::shared_ptr<MemoryAdmissionResult> admission = memSub->getCycleController()->TryAcceptCpuExplicitPacketScalarLoad(static_cast<unsigned long long>(this->CoreID), address, accessSize, ((std::dynamic_pointer_cast<Core::LoadStoreMicroOp>(lane.MicroOp)) == nullptr ? nullptr : (std::dynamic_pointer_cast<Core::LoadStoreMicroOp>(lane.MicroOp))->getCpuPhysicalReadBinding()));
						if (admission->Status == MemoryAdmissionStatus::Rejected)
						{
				std::shared_ptr<Core::PageFaultException> rejectedRequestFault = std::make_shared<Core::PageFaultException>((admission->Reason.has_value()) ? admission->Reason.value(): L"MemoryCycleController rejected an explicit-packet scalar load.", address, false);
							std::shared_ptr<Core::Execution::ExecutionOutcome> rejectedOutcome = ProjectExplicitPacketCompletedMemoryRequestFailureOutcome(rejectedRequestFault);
							DeliverExplicitPacketCompletedMemoryRequestFailureOutcome(rejectedOutcome, rejectedRequestFault);
							throw InvalidOperationException(L"Stage-aware explicit-packet rejected-request fault delivery must terminate the current cycle.");
						}

						if (admission->Status == MemoryAdmissionStatus::Backpressured)
						{
							lane.ResultReady = false;
							lane.MemoryAccessSize = accessSize;
							getRuntime()->getMemoryPipeline()->Memory.SetLane(laneIndex, lane);
							continue;
						}

						lane.PendingMemoryControllerRequestId = std::make_shared<MemoryRequestId>(admission->RequestId);
						lane.ResultReady = false;
						lane.MemoryAccessSize = accessSize;
						getRuntime()->getMemoryPipeline()->Memory.SetLane(laneIndex, lane);
						continue;
					}

					std::shared_ptr<MemoryCompletion> completion;
// C# TO C++ CONVERTER WARNING: Nullable reference types have no equivalent in C++:
// ORIGINAL LINE: if (!memSub.CycleController.TryTakeCompletion(lane.PendingMemoryControllerRequestId.Value, out MemoryCompletion? completion))
					if (!memSub->getCycleController()->TryTakeCompletion(lane.PendingMemoryControllerRequestId.value(), completion))
					{
						lane.ResultReady = false;
						getRuntime()->getMemoryPipeline()->Memory.SetLane(laneIndex, lane);
						continue;
					}

					if (completion == nullptr || !completion->getSucceeded())
					{
						std::wstring completionFailure = completion == nullptr ? std::wstring{} : completion->getFailureReason();
						std::shared_ptr<Core::PageFaultException> completedControllerFault = std::make_shared<Core::PageFaultException>(L"Explicit-packet MEM observed failed completed controller request. " + (!completionFailure.empty() ? completionFailure : L"MemoryCycleController did not provide a failure reason."), address, false);
						std::shared_ptr<Core::Execution::ExecutionOutcome> outcome = ProjectExplicitPacketCompletedMemoryRequestFailureOutcome(completedControllerFault);
						// Preserve the packet's older lanes for the original WB
						// prefix selector. Immediate MEM flush would discard their
						// completed effects before they can retire.
						(void)outcome;
						MarkActiveMemoryLanePageFault(completedControllerFault);
						lane.CopyFrom(getRuntime()->getMemoryPipeline()->Memory.GetLane(laneIndex));
						lane.PendingMemoryControllerRequestId = std::nullopt;
						lane.ResultReady = true;
						getRuntime()->getMemoryPipeline()->Memory.SetLane(laneIndex, lane);
						continue;
					}

					auto completedBytes = completion->getData();
					std::vector<unsigned char> completedBuffer(completedBytes.begin(), completedBytes.end());
					lane.ResultValue = DecodeExplicitPacketLoadBuffer(lane.OpCode, completedBuffer, accessSize);
					lane.PendingMemoryControllerRequestId = std::nullopt;
				}
				else
				{
					if (!lane.PendingMemoryControllerRequestId)
					{
						std::vector<unsigned char> storeBytes = CreateExplicitPacketStoreBuffer(lane.MemoryData, accessSize);
						std::shared_ptr<MemoryAdmissionResult> admission = memSub->getCycleController()->TryAcceptExplicitPacketScalarStore(static_cast<unsigned long long>(this->CoreID), address, accessSize, storeBytes);
						if (admission->Status == MemoryAdmissionStatus::Rejected)
						{
						std::shared_ptr<Core::PageFaultException> rejectedStoreFault = std::make_shared<Core::PageFaultException>((admission->Reason.has_value()) ? admission->Reason.value(): L"MemoryCycleController rejected an explicit-packet scalar store.", address, true);
							std::shared_ptr<Core::Execution::ExecutionOutcome> rejectedStoreOutcome = ProjectExplicitPacketCompletedMemoryRequestFailureOutcome(rejectedStoreFault);
							DeliverExplicitPacketCompletedMemoryRequestFailureOutcome(rejectedStoreOutcome, rejectedStoreFault);
							throw InvalidOperationException(L"Stage-aware explicit-packet rejected-store fault delivery must terminate the current cycle.");
						}

						if (admission->Status == MemoryAdmissionStatus::Backpressured)
						{
							lane.ResultReady = false;
							lane.MemoryAccessSize = accessSize;
							getRuntime()->getMemoryPipeline()->Memory.SetLane(laneIndex, lane);
							continue;
						}

						lane.PendingMemoryControllerRequestId = std::make_shared<MemoryRequestId>(admission->RequestId);
						lane.ResultReady = false;
						lane.MemoryAccessSize = accessSize;
						getRuntime()->getMemoryPipeline()->Memory.SetLane(laneIndex, lane);
						continue;
					}

					std::shared_ptr<MemoryCompletion> storeCompletion;
// C# TO C++ CONVERTER WARNING: Nullable reference types have no equivalent in C++:
// ORIGINAL LINE: if (!memSub.CycleController.TryTakeCompletion(lane.PendingMemoryControllerRequestId.Value, out MemoryCompletion? storeCompletion))
					if (!memSub->getCycleController()->TryTakeCompletion(lane.PendingMemoryControllerRequestId.value(), storeCompletion))
					{
						lane.ResultReady = false;
						getRuntime()->getMemoryPipeline()->Memory.SetLane(laneIndex, lane);
						continue;
					}

					if (storeCompletion == nullptr || !storeCompletion->getSucceeded())
					{
						std::wstring storeFailure = storeCompletion == nullptr ? std::wstring{} : storeCompletion->getFailureReason();
						std::shared_ptr<Core::PageFaultException> completedStoreFault = std::make_shared<Core::PageFaultException>(L"Explicit-packet MEM observed failed completed controller store request. " + (!storeFailure.empty() ? storeFailure : L"MemoryCycleController did not provide a failure reason."), address, isWrite);
						std::shared_ptr<Core::Execution::ExecutionOutcome> storeOutcome = ProjectExplicitPacketCompletedMemoryRequestFailureOutcome(completedStoreFault);
						DeliverExplicitPacketCompletedMemoryRequestFailureOutcome(storeOutcome, completedStoreFault);
						throw InvalidOperationException(L"Stage-aware explicit-packet controller-store fault delivery must terminate the current cycle.");
					}

					lane.DefersStoreCommitToWriteBack = true;
					lane.PendingMemoryControllerRequestId = std::nullopt;
				}
			}
			else
			{
				if (lane.IsLoad)
				{
					std::vector<unsigned char> readBuffer = ReadExplicitPacketLoadIntoReusableBuffer(address, accessSize);
					lane.ResultValue = DecodeExplicitPacketLoadBuffer(lane.OpCode, readBuffer, accessSize);
				}
				else
				{
					lane.DefersStoreCommitToWriteBack = true;
				}
			}

			if (!lane.IsLoad)
			{
				lane.ResultValue = lane.MemoryData;
			}

			lane.MemoryAccessSize = accessSize;
			lane.ResultReady = true;
			getRuntime()->getMemoryPipeline()->Memory.SetLane(laneIndex, lane);
			completedLaneMask |= static_cast<unsigned char>(1 << laneIndex);
			completedContourPc = lane.PC;
		}

		getRuntime()->getMemoryPipeline()->Memory.ActiveLaneIndex = originalActiveLaneIndex;
		PublishExecuteCompletionContourCertificate(Core::PipelineContourOwner::ExplicitPacketExecution, Core::PipelineContourVisibilityStage::Memory, completedContourPc, completedLaneMask);
	}

	inline bool Processor::CPU_Core::TryPrepareExplicitPacketExecuteMemoryCarrierLane(unsigned char laneIndex, ScalarExecuteLaneState &lane, int &executedPhysicalLaneCount)
	{
		std::shared_ptr<Core::LoadMicroOp> loadOp = std::dynamic_pointer_cast<Core::LoadMicroOp>(lane.MicroOp);
		if (laneIndex < 6 && loadOp != nullptr)
		{
			if (loadOp->getUsesBaseRegisterAddressing())
			{
				int consumerThreadId = NormalizePipelineStateVtId(lane.OwnerThreadId);
				unsigned long long baseValue = GetRegisterValueWithForwardingExcludingExecuteLane(consumerThreadId, loadOp->getBaseRegID(), laneIndex);
				loadOp->ResolveBaseRelativeAddressForPipeline(baseValue);
			}
			lane.IsMemoryOp = true;
			lane.IsLoad = true;
			lane.MemoryAccessSize = loadOp->getSize();
			lane.MemoryAddress = loadOp->getAddress();
			lane.MemoryData = 0;
			lane.ResultValue = 0;
			lane.ResultReady = true;
			getRuntime()->getExecution()->Execute.SetLane(laneIndex, lane);
			executedPhysicalLaneCount++;

			RecordExecuteLaneTraceEvent(laneIndex, lane);
			return true;
		}

		std::shared_ptr<Core::StoreMicroOp> storeOp = std::dynamic_pointer_cast<Core::StoreMicroOp>(lane.MicroOp);
		if (laneIndex < 6 && storeOp != nullptr)
		{
			int consumerThreadId = NormalizePipelineStateVtId(lane.OwnerThreadId);
			if (storeOp->getUsesBaseRegisterAddressing())
			{
				unsigned long long baseValue = GetRegisterValueWithForwardingExcludingExecuteLane(consumerThreadId, storeOp->getBaseRegID(), laneIndex);
				storeOp->ResolveBaseRelativeAddressForPipeline(baseValue);
			}
			lane.IsMemoryOp = true;
			lane.IsLoad = false;
			lane.MemoryAccessSize = storeOp->getSize();
			lane.MemoryAddress = storeOp->getAddress();
			lane.MemoryData = GetRegisterValueWithForwardingExcludingExecuteLane(consumerThreadId, storeOp->getSrcRegID(), laneIndex);
			lane.ResultValue = lane.MemoryData;
			lane.ResultReady = true;
			getRuntime()->getExecution()->Execute.SetLane(laneIndex, lane);
			executedPhysicalLaneCount++;

			RecordExecuteLaneTraceEvent(laneIndex, lane);
			return true;
		}

		std::shared_ptr<Core::AtomicMicroOp> atomicOp = std::dynamic_pointer_cast<Core::AtomicMicroOp>(lane.MicroOp);
		if (laneIndex < 6 && atomicOp != nullptr && lane.GeneratedAtomicEffect)
		{
			lane.IsMemoryOp = true;
			lane.IsLoad = false;
			lane.MemoryAccessSize = atomicOp->getSize();
			lane.MemoryAddress = atomicOp->getAddress();
			lane.MemoryData = lane.GeneratedAtomicEffect.value().getSourceValue();
			lane.ResultValue = 0;
			lane.ResultReady = true;
			getRuntime()->getExecution()->Execute.SetLane(laneIndex, lane);
			executedPhysicalLaneCount++;

			RecordExecuteLaneTraceEvent(laneIndex, lane);
			return true;
		}

		return false;
	}

	inline std::shared_ptr<Core::Execution::ExecutionOutcome> Processor::CPU_Core::ProjectExplicitPacketCompletedMemoryRequestFailureOutcome(std::shared_ptr<Core::PageFaultException> exception)
	{
		std::shared_ptr<Core::Execution::ExecutionOutcome> outcome = Core::Execution::Rf07LegacyOutcomeProjection::ProjectException(*exception);
		if (outcome->getKind() != Core::Execution::ExecutionOutcomeKind::ArchitecturalFault || outcome->getDiagnostic() == nullptr || outcome->getDiagnostic()->getCode() != Core::Execution::ExecutionDiagnosticCode::PageFault || outcome->getDiagnostic()->getFaultAddress() != exception->getFaultAddress() || outcome->getDiagnostic()->getFaultIsWrite() != exception->isWrite() || outcome->getResult() != nullptr || outcome->getHasArchitecturalEffects())
		{
			throw Core::Execution::ExecutionOutcomeContractViolationException(L"Explicit-packet completed-token failure requires an exact no-effect ArchitecturalFault/PageFault outcome->");
		}

		return outcome;
	}

	inline void Processor::CPU_Core::DeliverExplicitPacketCompletedMemoryRequestFailureOutcome(std::shared_ptr<Core::Execution::ExecutionOutcome> outcome, std::shared_ptr<Core::PageFaultException> exception)
	{
		if (outcome->getKind() != Core::Execution::ExecutionOutcomeKind::ArchitecturalFault || outcome->getDiagnostic() == nullptr || outcome->getDiagnostic()->getCode() != Core::Execution::ExecutionDiagnosticCode::PageFault || outcome->getDiagnostic()->getFaultAddress() != exception->getFaultAddress() || outcome->getDiagnostic()->getFaultIsWrite() != exception->isWrite() || outcome->getResult() != nullptr || outcome->getHasArchitecturalEffects())
		{
			throw Core::Execution::ExecutionOutcomeContractViolationException(L"Explicit-packet completed-token failure delivery requires its exact projected PageFault outcome->");
		}

		DeliverStageAwareMemoryPageFault(exception);
	}

	inline std::shared_ptr<Core::Execution::ExecutionOutcome> Processor::CPU_Core::ProjectExplicitPacketMemoryNonFaultExceptionOutcome(std::runtime_error exception)
	{
		std::shared_ptr<Core::Execution::ExecutionOutcome> outcome = Core::Execution::Rf07LegacyOutcomeProjection::ProjectException(exception);
		if (outcome->getKind() != Core::Execution::ExecutionOutcomeKind::FatalInvariantViolation || outcome->getDiagnostic() == nullptr || outcome->getResult() != nullptr || outcome->getHasArchitecturalEffects())
		{
			throw Core::Execution::ExecutionOutcomeContractViolationException(L"Explicit-packet memory non-fault projection requires a no-effect FatalInvariantViolation outcome->");
		}

		return outcome;
	}

	void Processor::CPU_Core::ScalarWriteBackLaneState::Clear(unsigned char laneIndex)
	{
		IsOccupied = false;
		LaneIndex = laneIndex;
		SlotIndex = 0;
		PC = 0;
		OpCode = 0;
		ResultValue = 0;
		IsMemoryOp = false;
		MemoryAddress = 0;
		MemoryData = 0;
		IsLoad = false;
		MemoryAccessSize = 0;
		WritesRegister = false;
		DestRegID = 0;
		MicroOp = nullptr;
		PostStageBIssuedAttempt = nullptr;
		GeneratedEvent = std::nullopt;
		GeneratedCsrEffect = std::nullopt;
		GeneratedAtomicEffect = std::nullopt;
		GeneratedVmxEffect = std::nullopt;
		GeneratedRetireRecordCount = 0;
		GeneratedRetireRecord0 = YAKSys_Hybrid_CPU::Core::Registers::Retire::RetireRecord();
		GeneratedRetireRecord1 = YAKSys_Hybrid_CPU::Core::Registers::Retire::RetireRecord();
		DomainTag = 0;
		MshrScoreboardSlot = -1;
		MshrVirtualThreadId = 0;
		ResourceMask = Core::ResourceBitset::Zero;
		ResourceToken = 0;
		OwnerThreadId = 0;
		VirtualThreadId = 0;
		OwnerContextId = 0;
		WasFspInjected = false;
		OriginalThreadId = 0;
		HasFault = false;
		FaultAddress = 0;
		FaultIsWrite = false;
		CpuTranslationFault = std::nullopt;
		DefersStoreCommitToWriteBack = false;
	}

