	unsigned char Processor::CPU_Core::Nope()
	{
		if (IsEmulationExecutionMode())
		{
			return static_cast<unsigned char>(InstructionsEnum::Nope);
		}
		if (IsCompilerExecutionMode())
		{
			RecordCompatSystemInstruction(CpuCoreSystemInstructionEmitter::EncodeNope());
		}

		return static_cast<unsigned char>(InstructionsEnum::Nope);
	}

	void Processor::CPU_Core::RecordCompatSystemInstruction(VLIW_Instruction const instruction)
	{
		Processor::RecordCompilerInstruction(instruction);
	}

