	void Processor::InitializeLegacyCompatRuntime(ProcessorMode processorMode, std::shared_ptr<ProcessorConfig> config)
	{
		CurrentProcessorMode = processorMode;
		Config = config;
		Ready_Flag = false;

		Compiler = std::make_shared<ProcessorCompilerBridge>();
		if (processorMode == ProcessorMode::Compiler)
		{
			Compiler->DeclareCompilerContractVersion(CompilerContract::Version, std::format(L"{0}.{1}", L"Processor", L"InitializeLegacyCompatRuntime"));
		}
		MainMemory = std::make_shared<MultiBankMemoryArea>(CompatMainMemoryBankCount, CompatMainMemoryBankSize);

		IOMMU::Initialize();
		SharedMemoryLockManager::Initialize();
		InterruptData::Initialize();

		Processor proc(ProcessorMode::Emulation);
		DMAController = std::make_shared<HybridCPU_ISE::CloseToHSL::Memory::DMA::DMAController>(proc);
		Memory = std::make_shared<MemorySubsystem>(proc, DMAController);

		BeginCoreTableConstruction(1024);
		for (int coreIndex = 0; coreIndex < getCPUCores().size(); coreIndex++)
		{
			ReplaceCore(coreIndex, std::make_shared<CPU_Core>(static_cast<unsigned short>(coreIndex), std::make_shared<CpuCorePlatformContext>(CpuCorePlatformContext::CreateLegacy(MainMemory))));
		}
		ValidateCoreTableConstructionComplete();

		Pods = std::vector<std::shared_ptr<PodController>>(TOTAL_PODS);
// C# TO C++ CONVERTER NOTE: The following call to the 'RectangularVectors' helper class reproduces the rectangular array initialization that is automatic in C#:
// ORIGINAL LINE: NoCRouters = new NoC_XY_Router[POD_GRID_DIM, POD_GRID_DIM];
		NoCRouters = RectangularVectors::rectangularNoC_XY_RouterVector(POD_GRID_DIM, POD_GRID_DIM);
		InitializePodTopology();
		SyncPrimitives::Initialize(getCPUCores().size());

		MapCompatIdentityWindow(std::max(static_cast<unsigned long long>(MainMemory->getLength()), CompatIdentityMapBytes));
		AllocateCompatThreadDomains(config);

		Ready_Flag = true;
	}

	void Processor::MapCompatIdentityWindow(unsigned long long byteCount)
	{
		if (byteCount == 0)
		{
			return;
		}

		IOMMU::Map(0, 0, 0, byteCount, IOMMUAccessPermissions::ReadWrite);
	}

	void Processor::AllocateCompatThreadDomains(std::shared_ptr<ProcessorConfig> config)
	{
		for (int threadId = 0; threadId < CompatBootstrapThreadDomainCount; threadId++)
		{
			unsigned long long domainSize = ResolveCompatThreadDomainSize(config, threadId);
			if (domainSize == 0)
			{
				continue;
			}

			IOMMU::AllocateDomain(threadId, domainSize, MemoryDomainFlags::ReadWrite);
		}
	}

	unsigned long long Processor::ResolveCompatThreadDomainSize(std::shared_ptr<ProcessorConfig> config, int threadId)
	{
		unsigned long long customDomainSize;
		auto domains = config->getCustomThreadDomainSizes();
		if (domains.has_value() && domains->find(threadId) != domains->end() && (customDomainSize = domains->at(threadId)) > 0)
		{
			return customDomainSize;
		}

		return config->getThreadDomainSize();
	}

