	std::shared_ptr<Processor::CPU_Core> Processor::GetCoreRef(int coreId)
	{
		auto cores = getCPUCores();
		if (static_cast<unsigned int>(coreId) >= cores.size()) throw ArgumentOutOfRangeException(L"coreId");
				std::shared_ptr<Processor::CPU_Core> liveCore = cores[coreId];
		if (liveCore == nullptr)
		{
			throw InvalidOperationException(std::format(L"The platform core table contains an absent core slot at index {0}.", coreId));
		}
		liveCore->getRuntime();
		return liveCore;
	}

	void Processor::BeginCoreTableConstruction(int coreCount)
	{
		if (coreCount <= 0)
		{
			throw ArgumentOutOfRangeException(L"coreCount");
		}

		setCPUCores(std::vector<std::shared_ptr<CPU_Core>>(coreCount));
	}

	void Processor::ValidateCoreTableConstructionComplete()
	{
	std::vector<std::shared_ptr<CPU_Core>> cores = getCPUCores();
	if (cores.empty())
	{
		throw InvalidOperationException(L"The platform core table is not initialized.");
	}
		if (cores.empty())
		{
			throw InvalidOperationException(L"The platform core table has no configured cores.");
		}

		for (int coreId = 0; coreId < cores.size(); coreId++)
		{
			if (cores[coreId] == nullptr)
			{
				throw InvalidOperationException(std::format(L"The platform core table contains an absent core slot at index {0}.", coreId));
			}

			try
			{
				cores[coreId]->getRuntime();
			}
			catch (const InvalidOperationException &exception)
			{
				throw InvalidOperationException(std::format(L"The platform core table contains an absent core slot at index {0}.", coreId));
			}
		}
	}

