	void Processor::InitializePodTopology()
	{
		// 1. Create Pods and NoC routers
		for (int y = 0; y < POD_GRID_DIM; y++)
		{
			for (int x = 0; x < POD_GRID_DIM; x++)
			{
				int podIndex = y * POD_GRID_DIM + x;
				std::shared_ptr<MicroOpScheduler> scheduler = std::make_shared<MicroOpScheduler>();
				Pods[podIndex] = std::make_shared<PodController>(x, y, scheduler);

				NoCRouters[x][y] = std::make_shared<NoC_XY_Router>(x, y);

				// Initialize CSRs for the 16 cores belonging to this Pod
				unsigned short podId = Pods[podIndex]->getPodId();
				int baseCoreId = podIndex * PodController::CORES_PER_POD;
				for (int c = 0; c < PodController::CORES_PER_POD; c++)
				{
					int globalId = baseCoreId + c;
					if (globalId < getCPUCores().size())
					{
						std::shared_ptr<CPU_Core> core = GetCoreRef(globalId);
						core->setCsrPodId(podId);
						core->setCsrPodAffinityMask(0xFFFF); // all 16 cores active
					}
				}
			}
		}

		// 2. Wire NoC mesh: connect each router to its cardinal neighbours
		for (int y = 0; y < POD_GRID_DIM; y++)
		{
			for (int x = 0; x < POD_GRID_DIM; x++)
			{
				std::shared_ptr<NoC_XY_Router> router = NoCRouters[x][y];
				if (x + 1 < POD_GRID_DIM)
				{
					router->ConnectNeighbor(NoCPort::East, NoCRouters[x + 1][y]);
				}
				if (x - 1 >= 0)
				{
					router->ConnectNeighbor(NoCPort::West, NoCRouters[x - 1][y]);
				}
				if (y + 1 < POD_GRID_DIM)
				{
					router->ConnectNeighbor(NoCPort::North, NoCRouters[x][y + 1]);
				}
				if (y - 1 >= 0)
				{
					router->ConnectNeighbor(NoCPort::South, NoCRouters[x][y - 1]);
				}
			}
		}
	}

// C# TO C++ CONVERTER WARNING: Nullable reference types have no equivalent in C++:
// ORIGINAL LINE: public static PodController? GetPodForCore(int globalCoreId)
	std::shared_ptr<PodController> Processor::GetPodForCore(int globalCoreId)
	{
		int podIndex = globalCoreId / PodController::CORES_PER_POD;
		if (static_cast<unsigned int>(podIndex) >= static_cast<unsigned int>(TOTAL_PODS))
		{
			return nullptr;
		}
		return Pods[podIndex];
	}

// C# TO C++ CONVERTER WARNING: Nullable reference types have no equivalent in C++:
// ORIGINAL LINE: public static PodController? GetPodById(ushort podId)
	std::shared_ptr<PodController> Processor::GetPodById(unsigned short podId)
	{
		int podX = podId >> 8;
		int podY = podId & 0xFF;
		if (static_cast<unsigned int>(podX) >= POD_GRID_DIM || static_cast<unsigned int>(podY) >= POD_GRID_DIM)
		{
			return nullptr;
		}

		int podIndex = (podY * POD_GRID_DIM) + podX;
		if (static_cast<unsigned int>(podIndex) >= static_cast<unsigned int>(TOTAL_PODS))
		{
			return nullptr;
		}

		return Pods[podIndex];
	}

