	void Processor::EntryPoint::AddAddress(unsigned long long Address)
	{
		if (List_Call_Addresses.empty())
		{
			List_Call_Addresses = std::vector<unsigned long long>();
		}
		if (List_Jump_Addresses.empty())
		{
			List_Jump_Addresses = std::vector<unsigned long long>();
		}
		if (List_Interrupt_Addresses.empty())
		{
			List_Interrupt_Addresses = std::vector<unsigned long long>();
		}

		if (getType() == EntryPointType::EntryPoint && bool_EntryPointAddressAlreadyDefined == false)
		{
			setEntryPointAddress(Address);

			bool_EntryPointAddressAlreadyDefined = true;

			return;
		}

		if (bool_EntryPointAddressAlreadyDefined == true)
		{
			if (getType() == EntryPointType::Return)
			{
				throw UnsupportedEntryPointOperationException(L"Return", L"AddAddress");
			}

			if (getType() == EntryPointType::InterruptReturn)
			{
				throw UnsupportedEntryPointOperationException(L"InterruptReturn", L"AddAddress");
			}
		}

		if (bool_EntryPointAddressAlreadyDefined == false)
		{
			if (getType() == EntryPointType::Return)
			{
				throw UnsupportedEntryPointOperationException(L"Return", L"AddAddress");
			}

			if (getType() == EntryPointType::InterruptReturn)
			{
				throw UnsupportedEntryPointOperationException(L"InterruptReturn", L"AddAddress");
			}
		}

		if (getType() == EntryPointType::Call)
		{
			List_Call_Addresses.push_back(Address);
		}

		if (getType() == EntryPointType::Jump)
		{
			List_Jump_Addresses.push_back(Address);
		}

		if (getType() == EntryPointType::Interrupt)
		{
			List_Interrupt_Addresses.push_back(Address);
		}
	}

	void Processor::EntryPoint::AddRelocation(RelocationKind kind, unsigned long long emissionCursor)
	{
		if (!getEntryPointAddressAlreadyDefined())
		{
			std::optional<unsigned long long> requestedAddress = std::nullopt;
		throw EntryPointDefinitionException(L"AddRelocation", ulong_EntryPoint_Address, requestedAddress, L"EntryPoint relocation cannot be resolved before target address is defined.");
		}

		if (List_RelocationEntries.empty())
		{
			List_RelocationEntries = std::vector<std::shared_ptr<RelocationEntry>>();
		}

		List_RelocationEntries.push_back(RelocationEntry::CreateLegacyAbsolute64(kind, emissionCursor, getSymbolName(), getEntryPointAddress()));
	}

