	unsigned char Processor::InterruptData::CallInterrupt(DeviceType DeviceID, unsigned short InterruptID, unsigned long long CoreID)
	{
		// Validate interrupt ID
		if (InterruptID >= IRQ.size())
		{
			return 0xFF; // Invalid interrupt ID
		}

		// Look up interrupt handler address from vector table
		unsigned long long handlerAddress = IRQ[InterruptID].getMemoryAddress();

		if (handlerAddress == 0)
		{
			// No handler registered for this interrupt
			return 0xFE; // No handler error
		}

		// Get the target CPU core
		if (CoreID >= static_cast<unsigned long long>(getCPUCores().size()))
		{
			return 0xFD; // Invalid core ID
		}

// C# TO C++ CONVERTER TASK: There is no C++ equivalent to 'checked' in this context:
// ORIGINAL LINE: CPU_Core targetCore = GetCoreRef(checked((int)CoreID));
		std::shared_ptr<CPU_Core> targetCore = GetCoreRef(static_cast<int>(CoreID));

		// Route through the external-interrupt contour unless the core
		// already has a live interrupt-handler frame in flight.
		if (!targetCore->HasActiveInterruptHandlerFrame())
		{
			targetCore->EnterExternalInterruptHandler(handlerAddress);

			// In a real system, additional state would be saved here:
			// - Processor status flags
			// - Exception cause register
			// - Exception return address
		}

		return 0; // Success
	}

	bool Processor::InterruptData::RegisterHandler(unsigned short interruptID, unsigned long long handlerAddress, unsigned char priority)
	{
		// Validate interrupt ID
		if (interruptID >= IRQ.size())
		{
			return false;
		}

		// Validate priority (0-7)
		if (priority > 7)
		{
			return false;
		}

		// Register handler in IRQ table
		IRQ[interruptID].setInterruptID(interruptID);
		IRQ[interruptID].setMemoryAddress(handlerAddress);
		IRQ[interruptID].setPriority(priority);

		return true;
	}

	bool Processor::InterruptData::UnregisterHandler(unsigned short interruptID)
	{
		// Validate interrupt ID
		if (interruptID >= IRQ.size())
		{
			return false;
		}

		// Clear handler entry
		IRQ[interruptID].setMemoryAddress(0);
		IRQ[interruptID].setPriority(0);

		return true;
	}

	bool Processor::InterruptData::GetHandler(unsigned short interruptID, unsigned long long &handlerAddress, unsigned char &priority)
	{
		handlerAddress = 0;
		priority = 0;

		if (interruptID >= IRQ.size())
		{
			return false;
		}

		handlerAddress = IRQ[interruptID].getMemoryAddress();
		priority = IRQ[interruptID].getPriority();

		return handlerAddress != 0;
	}

	void Processor::InterruptData::DefaultVectorExceptionHandler(unsigned long long coreID)
	{
		if (coreID >= static_cast<unsigned long long>(getCPUCores().size()))
		{
			return;
		}

// C# TO C++ CONVERTER TASK: There is no C++ equivalent to 'checked' in this context:
// ORIGINAL LINE: CPU_Core core = GetCoreRef(checked((int)coreID));
		std::shared_ptr<CPU_Core> core = GetCoreRef(static_cast<int>(coreID));
		auto status = core->getExceptionStatus();

		// Log exception information (in real hardware, this might write to a trace buffer)
		// For emulation, we track the exception occurred
		bool hasExceptions = false;

		if (status->getOverflowCount() > 0)
		{
			hasExceptions = true;
			// In a real implementation: Console.WriteLine($"Core {coreID}: Overflow exceptions: {status.OverflowCount}");
		}

		if (status->getUnderflowCount() > 0)
		{
			hasExceptions = true;
			// Console.WriteLine($"Core {coreID}: Underflow exceptions: {status.UnderflowCount}");
		}

		if (status->getDivByZeroCount() > 0)
		{
			hasExceptions = true;
			// Console.WriteLine($"Core {coreID}: Divide-by-zero exceptions: {status.DivByZeroCount}");
		}

		if (status->getInvalidOpCount() > 0)
		{
			hasExceptions = true;
			// Console.WriteLine($"Core {coreID}: Invalid operation exceptions: {status.InvalidOpCount}");
		}

		if (status->getInexactCount() > 0)
		{
			hasExceptions = true;
			// Console.WriteLine($"Core {coreID}: Inexact result exceptions: {status.InexactCount}");
		}

		// Clear exception counters after handling
		core->ClearCanonicalVectorExceptionCounters();

		// Return from the default handler contour by releasing one saved
		// interrupt frame and restoring the active VT's runnable state.
		if (core->HasActiveInterruptHandlerFrame())
		{
			core->Pop_Interrupt_EntryPoint_Address();
		}

		core->ApplyInterruptTransitionToVirtualThread(core->ReadActiveVirtualThreadId());
	}

	void Processor::InterruptData::Initialize()
	{
		// Clear all IRQ entries
		for (int i = 0; i < IRQ.size(); i++)
		{
			IRQ[i].setInterruptID(static_cast<unsigned short>(i));
			IRQ[i].setMemoryAddress(0);
			IRQ[i].setPriority(0);
		}

		// Register default vector exception handler at IRQ 0x80
		// In a real system, this would be the address of DefaultVectorExceptionHandler
		// For simulation, we use a symbolic address (0x1000)
		RegisterHandler(0x80, 0x1000, 7); // Highest priority for exceptions
	}

