// C# TO C++ CONVERTER WARNING: Nullable reference types have no equivalent in C++:
// ORIGINAL LINE: public static void ConfigureProfiling(bool enable, ProfilingOptions? opts = null)
	void Processor::ConfigureProfiling(bool enable, std::shared_ptr<ProfilingOptions> opts)
	{
		ProfilingEnabled = enable;
		CurrentProfilingOptions = (opts != nullptr) ? opts : ProfilingOptions::Default();

		if (enable)
		{
			// Initialize burst trace collection if requested
			if (CurrentProfilingOptions->getCollectBurstTraces())
			{
				burstTraces = std::vector<std::shared_ptr<PerformanceReport::BurstTrace>>();

				// Subscribe to memory subsystem events
				if (Memory != nullptr)
				{
					Memory->BurstStarted->addListener(L"OnBurstStarted", [&] (std::any sender, std::shared_ptr<BurstEventArgs> e) {OnBurstStarted(sender, e);});
					Memory->BurstCompleted->addListener(L"OnBurstCompleted", [&] (std::any sender, std::shared_ptr<BurstEventArgs> e) {OnBurstCompleted(sender, e);});
				}
			}
		}
		else
		{
			// Unsubscribe from events
			if (Memory != nullptr)
			{
				Memory->BurstStarted->removeListener(L"OnBurstStarted");
				Memory->BurstCompleted->removeListener(L"OnBurstCompleted");
			}

			burstTraces = std::vector<std::shared_ptr<PerformanceReport::BurstTrace>>();
		}
	}

